window.HB_TR["job"]["ks"]=["1.\\tاُز کِس سرزمینس مَنٛز اوس اَکھ شخٕص یُس ناو {اوس} ایوب اوس۔ تہٕ سُہ انسان اوس کامل تہٕ سیود تہٕ یُس خدایس کھوژان اوس، تہٕ بدی نِش بچان اوس۔\n2. تہٕ أمِس زایہِ سَتھ نیٚچِوِ تہٕ ترےٚ کورِ۔\n3.\\tتٔمۍ سُند مال تہِ اوس سَتھ ساس کۅکر، تہٕ ترے ساس اونٹ، تہٕ پانژھ ہتھ بیل تہٕ پانژھ ہتھ گٔرۍ، تہٕ اکھ واریاہ بوٚڈ گر۔ تہ یہ انسان اوس مشرق کین سارِنٕے نفرن منز سارِوٕے کھۄتہٕ بوڈ ۔ {مادہ: یا، مویشی} {گھر: یا، رچھن} {مرد: ہیب۔ سنز}\n4.\\tتہٕ تٔمۍ سٕندِ نیچوۍ گٔیہِ تہٕ تِمن ہٕندِس گَرَن مَنٛز دعوت دِنہٕ۔ تہٕ سوٗزُن تہٕ بُلٲوِن تِمن سٍتۍ کھٮ۪نہٕ تہٕ چیٚنہٕ خٲطرٕ۔\n5. تہٕ یێلہِ یێلہِ تِہٕندِس دعوتُک دۅہ گٔیہِ، ایوب سوٗزۍ تہٕ پاکیز، تہٕ سُلہِ ووٚتھ، تہٕ سارِنٕے سارِنٕے ہٕندِس تعدادس مُطٲبق دِژُن نذرانہ پیش کرنہٕ، تکیازِ ایوب وۆن زِ یہ ہیکہِ میانین نیچویو گۅنہگار کورمُت، تہٕ دِلَس مَنٛز خدایہ سٕندِس دِلس مُطٲبق دِژن دِنہٕ۔ یتھے پاٹھۍ اوس ایوب لگاتار کران۔ {مسلسل: ہیب۔ سارِنٕے دۅہہ}\n6. وُنہِ اوس اَکھ دۅہ ییلہ خدایہِ سٕندِ نیچو خداوند سٕندِس برونہہ کُن پیش کرنہٕ آمٕتۍ، تہٕ شیطان تہِ آو تِمن مَنٛز۔ {شیطان: ہیب۔ مخٲلف} {among: Heb. منز}\n7. تہٕ خداوند ووٚن شیطانس زِ ژیہ کتہِ آو؟ اَمہِ پَتہٕ دِیُت شیطانَن خدایہِ سُند جواب تہٕ وونُن، زمینہِ مَنٛز یور یور گژھنہٕ نِش تہٕ اَتھ مَنٛز ہیوٚر بۄن پکنہٕ نشہِ۔\n8. تہٕ خداوند ووٚن شیطانس زِ کیا ژے چُھہ میانہِ بندہ ایوب سٕندِس زمینس مَنٛز کانہہ تہِ ہیوٗ کانہہ تہِ، کامل تہٕ نیک انسان، یُس خدایہ سُند خوف تھاوان چُھ، تہٕ بدی نِش بچان چُھ؟ {غور کرنہٕ آمُت: ہیب۔ پَنُن دِل تھاوُن تھاوُن}\n9. اَمہِ پَتہٕ دِیُت شیطان خداوند سُند جواب تہٕ وونُن، کیا ایوب چُھہ خدایہِ سٍتـ̡ کُنہِ تہِ خوفزدہ سپدان؟\n10.\\tکیا ژے چھُکھ نہٕ أمِس تہٕ أمۍ سٕندِس گرس مُتعلِق تہٕ پرٮ۪تھ طرفہٕ یُس أمِس سٍتـ̡ موجود چھُ، تێلہِ چُھہ نہٕ باڑ بنوومُت؟ تٔمۍ سٕندِس اتھن ہٕنزِ کامہِ سٍتـ̡ برکت دِژمٕژ تہٕ تٔمۍ سُند مال چُھ زمینس مَنٛز ہُریر۔ {مادہ: یا، مویشی}\n11. مگر وۅنۍ ترٲو پنُن اتھہ، تہٕ أمِس نِش موجود سارِنٕے چیزس اتھہٕ لاگُن، تہٕ سُہ کرِ تۅہہِ بُتھِس پیٹھ لعنت۔ {تہٕ سُہ...: ہیب۔ اگر نہ تۅہہ بُتھِس پیٹھ لعنت}\n12.\\tتہٕ خداوند ووٚن شیطانس زِ وُچھِو سُہ سُہ سُہ یُس تُہٕندِس اختیارس مَنٛز چھُ۔ صرف پانس پیٹھ تھوو نہ پنُن اتھہ۔ تہٕ شیطان دراو خداوند سٕندِ حضوری منز۔ {پاور: ہیب۔ اتھہٕ}\n13.\\tتہٕ سُہ اوس اکھ دۅہ ییلہ تٔمۍ سٕندِ نیچوۍ تہٕ کورِ پننِس بٔڈِس بٲے سٕندِس گرس مَنٛز شراب کھیوان تہٕ چیوان ٲسۍ۔\n14.\\tتہٕ آو ایوب نِش اکھ قاصد تہٕ وونُن زِ بیل ٲسۍ ہل چلاوان، تہٕ گَرٕ ٲسۍ تِمن سٍتـ̡ کھٮ۪وان:\n15.\\tتہٕ صابین پیوٚو تمن پیٹھ، تہٕ نِتھ نِن۔ آ، تِمو چھِ تلوار ہٕندِ دھالہٕ سٍتۍ نوکر مٲرۍمٕتۍ۔ تہٕ بہٕ چُھس صرف ژےٚ وننہٕ خٲطرٕ تنہا ژلان۔\n16.\\tییلہ سُہ وُنہِ تہِ کتھ کران اوس، بیاکھ تہِ آو تہٕ وونُن، خدایہ سُند نار چُھ آسمانہٕ پى۪ٹھہٕ پۯاونہٕ آمُت، تہٕ کٔرِن دانٛد تہٕ خادمَن زٲلِتھ تہٕ تِم زٲلِتھ دِژمٕتۍ۔ تہٕ بہٕ چُھس صرف ژےٚ وننہٕ خٲطرٕ تنہا ژلان۔ {نار...: یا، اکھ عظیم نار}\n17.\\tییلہ سُہ وُنہِ تہِ کتھ کران اوس، بیاکھ اکھ تہِ آو تہٕ وونُن، چالدینو کٔر تریہ بند، تہٕ لٔگِکھ اونٹَن پیٹھ، تہٕ تِم نِتھ نِنہٕ آمٕتۍ، آ، تہٕ مٲرِکھ نوکر تلوارِ ہٕندِ دھار سٍتـ̡ ۔ تہٕ بہٕ چُھس صرف ژےٚ وننہٕ خٲطرٕ تنہا ژلان۔ {فیل: ہیب۔ جلدی کٔرِتھ}\n18.\\tییلہ سُہ وُنہِ تہِ کتھ کران اوس، بیاکھ اکھ تہِ آو تہٕ وونُن، تہند نیچو تہٕ کورِ ٲسۍ پننِس بٔڈِس بٲے سٕندِس گرس منز شراب کھیوان تہٕ چیوان ۔\n19.\\tتہٕ وُچھ بیابان منزٕ آو اکھ زبردست واو، تہٕ گرٕ کِس ژۅشونی کونس لٔگِتھ تہٕ سُہ پیوٚو نوجوانن پیٹھ، تہٕ تِم گٔیہِ مٔرۍ۔ تہٕ بہٕ چُھس صرف ژےٚ وننہٕ خٲطرٕ تنہا ژلان۔ {پیٹھ...: ہیب۔ اَکہِ طرفہٕ وغیرہ}\n20.\\tاَمہِ پَتہٕ ووٚتھ ایوب ووٚتھ، تہٕ کلہٕ ژٔٹِتھ لوٚگُن تہٕ لوٚگُن زمینس پیٹھ، تہٕ پوٗزا کٔرِتھ\n21.\\tتہٕ وونُن، بہٕ ووت ننگہٕ پننہِ ماجہ ہٕندِس کوکھ منز، تہٕ ننگہٕ کٔرِتھ واپس: خداوند دِیُت، تہٕ خداوند چُھ نِیومُت۔ خداوند سُند ناو آسُن بابرک۔\n22. اتھ سارِنٕے مَنٛز کٔر نہٕ ایوب گۅناہ تہٕ نہ کٔرٕن خدایس بیوقوفی سٍتـ̡ ۔ {الزام شد...: یا، خدایس سٕتۍ منسوب حماقت}","1. بییہِ اوس اکھ دۅہ ییلہ خدایہِ سٕندِ نیچوۍ خداوند سٕندِس برونہہ کُن پان پیش کرنہٕ خٲطرٕ آیہ، تہٕ شیطان تہِ آو تِمن مَنٛز خداوند سٕندِ برونہہ کُن پیش۔\n2. تہٕ خداوند ووٚن شیطانس زِ ژیہ کتہِ پیٹھہ آو؟ تہٕ شیطانن دیُت خداوند سُند جواب تہٕ وونُن، زمینس منز یور یور گژھنہٕ نشہِ تہٕ اتھ منز ہیوٚر بۄن پکنہٕ نشہِ۔\n3. تہٕ خداوند چُھ شیطانس ووٚنمُت، کیا ژے چُھہ میانہِ خادم ایوب سٕندِس زمینس مَنٛز کانہہ تہِ ہیوٗ نہٕ کانہہ تہِ، یُس خدایہ سُند خوف چُھ، تہٕ بدی نِش بچان چُھ؟ تہٕ توتہِ چُھ سُہ پنٕنۍ دیانت برقرار تھاوان، حالانکہ ژے کٔر مے أمِس خٕلاف مُتٲثِر کرنہٕ خٲطرٕ، أمِس بغٲر وجہہ تباہ کرنہٕ خٲطرٕ۔ {تباہ کرنہٕ خٲطرٕ...: ہیب۔ امس نگلنہٕ خٲطرٕ}\n4. تہٕ شیطانن دیُت خداوند سُند جواب تہٕ وونُن، ژمہٕ بدلہٕ ژلہٕ، آ، سُہ چُھ سُہ سُہ پننہِ زُوٕ خٲطرٕ دِوان۔\n5. مگر وۅنۍ ترٲو پنُن اتھہ، تہٕ تٔمۍ سٕنزِ أڈجہِ تہٕ مازس اَتھٕ لاگُن، تہٕ سُہ کرِ تۅہہِ بُتھِس پیٹھ لعنت۔\n6. تہٕ خداوند ووٚن شیطانس زِ وُچھو، سُہ چُھہ تُہندس اتھس منز۔ مگر بچٲوۍ تٔمۍ سٕنز زُو۔ {مگر: یا، صرف}\n7. یێتھے پٲٹھـ̡ دِژ شیطان خداوند سٕنزِ حضوری منز، تہٕ دِژُن ایوب سٕندِس کھورِ پیٹھٕ تاجس تام۔\n8.\\tتہٕ تٔمۍ نِش پانس کھرنہٕ خٲطرٕ اکھ بانہٕ۔ تہٕ بیوٹھ سُہ آشس منز۔\n9.\\tاَمہِ پتہٕ ووٚن أمۍ سٕنزِ خانٛدارِنہِ تٔمِس زِ کیا تُہۍ چھوا وُنہِ تہِ پنٕنۍ دیانت برقرار تھاوان؟ خدایہ سٕندِ لعنت، تہٕ مرُن۔\n10.\\tمگر تٔمۍ ووٚن أمِس زِ تۅہہ چھے بیوقوف زنانہِ ہٕنز کتھ کران۔ کیا؟ کیا اسہِ کیا خدایہ سٕندِ دٔسۍ نیکی میلہِ، تہٕ کیا اسہِ پزٕ نہٕ بُردی میلہٕ؟ اتھ سارِنٕے سٍتـ̡ اوس نہٕ ایوب سٍتـ̡ گۅناہ کٔرمُت۔\n11. وۅنۍ ییلہ ایوب سٕندیو تریہ یارو یُس سٲرۍسٕے بُرٲیی ہٕنز خبر بوز، تِم آیہ پرٮ۪تھ کانہہ پننہِ جایہ پیٹھ۔ الیفاز تیمانی، تہٕ بلداد شُہیت تہٕ زوفر نامتھی: تکیازِ تِمو اوس أمِس سٍتۍ ماتم کرنہٕ خٲطرٕ تہٕ تسٕندِس تسلی دِنہٕ خٲطرٕ اِکہٕ وٹہٕ ملاقات کورمُت۔\n12. تہٕ ییلہ تِمو پنٕنۍ أچھ دور تُل، تہٕ أمِس ٲس نہٕ زانان، تِمو کٔر پنٕنۍ آواز تھوٚد تہٕ رووُن۔ تہٕ تِمو کٔر پرٮ۪تھ أکِس سُند پوشہٕ ژٔٹِتھ، تہٕ کٔرٕکھ پننِس کلس پیٹھ آسُن آسمانس کُن۔\n13.\\tتہ بیوٹھ تِم أمِس سٍتـ̡ سَتھ دۅہ تہٕ سَتھ رٲژ زمینس پیٹھ، تہٕ کٲنسہ تہِ کٔر أمِس سٍتـ̡ کتھ تہِ، تکیازِ تِمو وُچھ زِ تٔمۍ سُند غم اوس سٮ۪ٹھاہ زیادٕ۔","1.\\tامہ پتہ کھولن ایوب پنن بوش تہ دۅہس کٔرُن لعنت۔\n2. تہٕ ایوب کٔر کتھ تہٕ وونُن، {سپک: حب۔ جواب}\n3.\\tسُہ دۅہ گژھہِ ختم سپدُن یتھ منز بہٕ زامُت اوس، تہٕ سُہ رٲژ یَتھ مَنٛز یہِ وننہٕ اوس آمُت زِ اَکھ انسان بچہٕ چُھ پٲدٕ سپدان۔\n4. سُہ دۅہ گژھہِ انہِ گوٚٹ آسُن۔ خدایہ گژھہِ نہ اتھ ہیرِ پیٹھے وچھان، نہ گژھہِ اتھ پیٹھ گاش گاش۔\n5. انہِ گوٚٹ تہٕ موتُک ژھایہ دِیُن اَتھ داغ۔ اَتھ پیٹھ گژھہِ اوٚبرُن روزُن؛ دۅہک سیاہ پن گژھہِ اتھ خوفزدہ کرُن۔ {داغ: یا، چلینج} {دِیُن...: یا، تِم گژھن اتھ خوفزدہ کرُن، یِتھٕ پٲٹھۍ یِمن ہُند دۅہ تلخ چُھ}\n6.\\tیتھہ پاٹھۍ چھہ تمہِ رٲژ انہِ گٹہِ پیٹھ رٔٹتھ۔ یہ گژھہِ نہ ؤری کین دۅہن سٍتۍ رلاونہٕ یُن، یہ گژھہِ نہ ریتن ہندس تعدادس منز یُن۔ {یہ گژھہِ نہ آسُن...: یا گژھہِ نہ دۅہن منز خۅش گژھُن}\n7.\\tلو، سۅ رٲژ گژھہِ کُنہِ کُنہِ تہِ خوشی ہٕنز آواز یِنہٕ۔\n8.\\tتِم گژھن اتھ دۅہس لعنت، یُس پنُن ماتم تُلنہٕ خٲطرٕ تیار چھُ۔ {تِہُند...: یا، لیویتھن}\n9.\\tاَمہ کِس شفقٕکۍ تارکھ گژھن انہِ گٹہِ۔ گاش ژھانڈُن، مگر {چُھ} نہٕ۔ نہ گژھہِ یہ دۅہُک فجر وُچھُن: {صبح...: ہیب۔ صبحٕچ أچھ ٹٲرۍ}\n10.\\tکیازِ یہ چھُنہٕ میانہِ ماجہ ہٕندِس رحم ہٕندِ دروازٕ بند کٔرِتھ، تہٕ نہ کٔرٕن میانہِ اچھن نِش غم ژوٗر۔\n11.\\tمیہ کیازِ چھہ نہ رحمہ منزہ مرُن؟ {} ییلہ بہٕ اڈِ منزہ نیبر نیران اوسس میہ {نہ} ترووُن بھوت؟\n12. کۅٹھن کیازِ رُکٲوۍ میہ ؟ نتہ کیازِ چھہ میہ سین چوسان؟\n13.\\tفی الحال اوسس میہ شوٚنگتھ تہ ژھۅپہ کٔرتھ، تیلہ آسہ ہا میہ آرام کٔرتھ،\n14.\\tزمینہِ ہندین بادشاہن تہٕ مشیرن سٍتۍ، یِمو پانس خٲطرٕ ویران جاے بنٲوۍ۔\n15. یا تِمن شہزادن سٍتـ̡ یِمن سٍتـ̡ سۄنہٕ آسہِ، یِمو پَنٕنـ̡ گَرٕ رۄپہٕ سٍت\n16.\\tیا چھُس نہ میہ اکھ پوشیدہ بے وقعت پیدائش۔ شُرۍ ٲسۍ نہٕ زانہہ گاش وُچھمٕتۍ۔\n17.\\tتتہِ چھہ بدکار پریشان سپدان۔ تہٕ تَتہِ چھُ تھکان آسُن۔ {تھکاوٹ: ہیب۔ طاقتس منز تھکان گومُت}\n18.\\t{تتہِ}قٲدۍ چھہِ اکوٹہ آرام کران۔ تِم چھِنہٕ ظالم سٕنز آواز بوزان۔\n19.\\tلۅکٹۍ تہ بٔڈ چھہِ تتہِ۔ تہٕ خادم چُھ پننِس آقا نِش آزاد۔\n20. اَمہِ مۄکھٕ چُھ تٔمِس گاش دِنہٕ آمُت یُس مُصیبت چُھہ تہٕ تلخ روحس زندگی دِنہٕ آمُت۔\n21.\\tیُس موتُک طمع کران چھُ، مگر یہ چھہ نہٕ یِوان۔ تہٕ چھپاونہٕ آمٕتۍ خزانہٕ کھوتہٕ زیادٕ کھٔنِتھ کٔرِو۔ {زیٹھ: ہیب۔ انتظار کٔرِو}\n22.\\tکُس چھُ سٮ۪ٹھاہ خۅش سپدان، {تہٕ} ییلہ تم قبر میلان چھِ؟\n23. {گاش کیازِ چُھ دِنہٕ آمُت} تٔمِس شخصس یٔمۍ سٕنز وتھ پوشیدٕ آسہِ، تہٕ یٔمِس خداین رٔٹِتھ چُھ؟\n24.\\tمیانہِ آہ کھٮ۪نہٕ برونہہ چھُ یِوان، تہٕ میٲنۍ گُرٕ چھِ آبہٕ ہٕندۍ پٲٹھۍ وسان۔ {بہٕ چُھس کھٮ۪وان: ہیب۔ میون ماز}\n25.\\tیُس چیز میہ واریاہ کھوژان اوس، سُہ آو میہ نِش۔ {چیز...: ہیب۔ میہ اوس خوفہٕ کھوژان، تہٕ یہ آو میہ پیٹھ}\n26. بہٕ اوسُس نہٕ محفوٗظ تہٕ نہ اوسُس آرام کٔرِتھ، نہ اوسُس بہٕ ژھۄپہٕ کٔرِتھ۔ توتہِ آو پریشانی۔","1.\\tاَمہ پتہٕ دِژ الیفاز تیمانِین جواب تہٕ وونُن،\n2. {اگر} أسۍ ژے سٍتۍ کتھ باتھ کرنٕچ کوشش کٔرِو، کیا ژیہ گژھہِ غم؟ مگر کُس ہیکہِ پانس کتھ کرنہٕ نِش رُکٲوِتھ؟ {to...: Heb. اکھ لفظ} {رُکاونہٕ...: ہیب۔ لفظو نش پرہیز؟}\n3.\\tوُچھ، ژے چھے واریاہن ہدایتَن دِژمٕژ، تہٕ ژے کٔرِکھ کمزور اتھہٕ مضبوٗط۔\n4. چانہِ کلامَن چُھ سُہ تھپھ کٔرِتھ یُس پَسُن اوس، تہٕ ژے کٔر کمزور کۄٹھن مضبوٗط۔\n5.\\tمگر وۅنۍ چھہ یہ ژے پیٹھ آمُت، تہٕ ژے چھکھ بے ہوش گومُت۔ یہ چھہ ژیہ ژیہ پریشان کران۔\n6.\\t{یہ} چھُنہٕ تُہند خوف، تُہند اعتماد، تُہٕنز وۅمید تہٕ پننہِ وتہِ ہٕنز پاکیزگی چھُنہٕ؟\n7. یاد تھاوُن، بہٕ چُھس ژےٚ دُعا کران، یُس {زانہہ} بےٚ گناہ آسنہٕ سٍتـ̡ ہلاک گومُت؟ نتہٕ کتہِ ٲسۍ نیک بند؟\n8.\\tیُتھ زن میہ وُچھمُت چُھ، یِم بد کار چِھ کران تہٕ بدکاری کران چھِ، تِم چھِ یۅہے لُٹان۔\n9.\\tخدایہ سٕندِ دھماکہٕ سٍتـ̡ چھِ تِم ختم سپدان، تہٕ تٔمۍ سٕنزِ نستہٕ سٍتـ̡ چھِ تِم کھٮ۪وان۔ {شہس سٍتۍ...: یعنی تمۍ سندِ شرارت سٍتۍ}\n10.\\tشیرِ ہٕنز گڑبڑ تہٕ خوفناک شیر سٕنز آواز تہٕ جوان شیرن ہٕندِ دند چھِ پھُٹمٕتۍ۔\n11.\\tپرون شیر چھہ شکارہ نہ آسنہ کِنۍ ماران تہ موٚٹۍ شیر سٕندِ بچہٕ چھِ پردٕ نیبر کُن پھٔلِتھ۔\n12.\\tوۅنۍ آو میہ نِش اکھ چیز ژوٗرِ پٲٹھۍ، تہٕ میٲنس کنس آو رژھ کھنڈ رژھ۔ {ژوٗرِ پٲٹھۍ: ہیب۔ بذریعہ سٹیلتھ}\n13.\\tرٲژ ہٕندِس خیالس منز، ییلہ انسانس سٍتـ̡ گۆو نندر پیوان چُھ،\n14.\\tمیہ آو خوف، تہٕ تھرتھر لٔگۍ، ییمہ سٍتۍ میانہِ سارِنٕے أڈجہ لرزاونہٕ آیہ۔ {آو...: ہیب۔ met} {all: Heb. کثیر}\n15.\\tاَمہ پتہٕ گۆو اَکھ روح میٲنِس بُتھِس برونہہ کُن۔ میانہِ مازُک مس ووٚتھ تھوٚد:\n16.\\tیہ کھڑا مگر میہ ہیوٚک نہ امچ شکل وچھتھ: میانین اچھن برونہہ کنہِ اکھ تصویر {ٲس}، {اتہِ} ٲس خاموشی، تہ میہ بوز اکھ آواز، {تتہِ...: یا بوز میہ اکھ خاموش آواز}\n17. کیا انسان خدایہ کھوتہٕ زیادٕ عادل آسُن؟ کیا انسان آسِہ پننِس بناون وٲلس کھوتہٕ زیادٕ پاک؟\n18.\\tوُچھِو نہٕ تٔمِس پننٮ۪ن نوکرَن پیٹھ کانہہ بھروسہٕ۔ تہٕ تٔمۍ سٕندٮ۪ن فرشتن پیٹھ اوس بیوقوفی ہُند الزام لگاوان: {تہٕ تٔمۍ سٕندِ...: یا نہ پننین فرشتن منز، یمن منز تٔمۍ گاش دِژ}\n19.\\tتِمن منز کوتاہ کم یم میژِ ہندین گرن منز روزان چھہِ، یمن ہنز بنیاد {چھہ} گردِ منز، {یِم} چھہِ کیمس برونہہ کنہِ لٔٹتھ دِنہٕ آمٕتۍ۔\n20. تِم چھِ صُبحہ پیٹھٕ شامَس تام تباہ سپدان: تِم چھِ ہمیشہٕ خٲطرٕ ختم گَژھان۔ {تباہ: ہیب۔ ٹکڑن منز مارنہٕ}\n21.\\tکیا تِمن منز چُھہ نہٕ تِمن ہٕنزِ عظمتُک {یُس چُھ} ختم سپدان چھُ؟ تِم چھِ مران، دانشمٲری ورٲے تہِ۔","1. وۅنۍ کٔرِو فون اگر کانہہ آسہِ یُس تۅہہِ جواب دِیہِ۔ تہٕ تُہۍ کُس مُقدسن کُن پھیرِو؟ {موڑ: یا، وُچھ؟}\n2. تکیازِ غصہٕ چُھ بیوقوف انسان ماران، تہٕ حسد چُھ بیوقوفس ماران۔ {حسد: یا، غصہٕ}\n3.\\tمیہ چھہ بیوقوفس جڑ وُچھمُت: مگر اچانک کٔر میہ تٔمۍ سٕنزِ بستی پیٹھ لعنت۔\n4.\\tتٔمۍ سٕندِ شُرۍ چھِ محفوٗظ نِش دور، تہٕ تِم چھِ دروازس مَنٛز لَبنہٕ آمٕتۍ، نَہ چھُنہٕ کانہہ تہِ دِنہٕ خٲطرٕ۔\n5. یٔمۍ سُند فصلہٕ فاقہٕ کھٮ۪وان چُھ، تہٕ سُہ چھُ کانٹَو منزٕ تہِ نِوان تہٕ لُٹُن چُھ تِہُند مال نِوان۔\n6. یودوَے مُصیبت چھُنہٕ میٚژِ منزٕ نیران، تہٕ نہ چھُ مصیبت زٔمیٖنہٕ منزٕ نیران۔ {مصیبت: یا، بدکاری}\n7. توتہِ چُھ انسان مصیبت سٍتـ̡ پٲدٕ سپدان، یێلہِ چِھہ چِھہ چِھہ ہیوٚر کُن وُڈان۔ {پریشانی: یا، محنت} {سپارکس...: ہیب۔ دزنہٕ وٲل کولہٕ ہنٛد نیچو چُھ وڑنہٕ خاطرٕ تُلان}\n8. بہٕ کَرٕ خدایہِ سٕندِ سٍتـ̡ تہٕ خدایہِ سٍتـ̡ پنُن مقصد حٲصِل کَرُن:\n9.\\tیُس بٔڈ کٲم کران چھہ تہٕ ناقابل تلاش چھُ۔ حیرت انگیز چیز بغیر نمبر: {unsearchable: Heb. تَتھ چھُنہٕ کانٛہہ تَلاش} {بغٲر ...: ہیب۔ یوٚت تام نہ کانہہ نمبر آسہِ}\n10. یُس زمینس پیٹھ روٗد تراوان چُھ، تہٕ کھاہن پیٹھ آب تراوان چُھ: {کھیت: ہیب۔ آؤٹ پلیس}\n11. تھزرس پیٹھ یِم کم آسن تِم قٲیم کرٕنۍ۔ تاکہ یِم ماتم کران چھِ، تِم گژھن حفاظتہٕ خٲطرٕ تھزراونہٕ۔\n12.\\tسُہ چھُ چالاکی ہٕندِس آلاتس مایوس کران، یُتھ زن تِہٕندِ اتھہٕ ہیکن نہٕ تِمن ہٕندِس کارٕبارس انجام دِتھ۔ {تہند انٹرپرائز: یا، کنہہ چیز}\n13.\\tسُہ چُھ دانشمندن ہٕنزِ چالاکی سٍتـ̡ رٔٹِتھ تہٕ بدمعاش سُند مشورٕ چُھ کُنہِ سٍتـ̡ نِنہٕ یوان۔\n14.\\tتِم چھِ دۅہلہِ انہِ گٹہِ سٍتـ̡ میلان تہٕ رٲژ ہٕندِس پٲٹھـ̡ دوپہرس گٔژھان۔ {میٹ...: یا، رن انٹو}\n15. مگر سُہ چُھ غریبن تلوار نِش، تِہندِ ٲسِس نِش تہٕ طاقتور سٕندِ اتھہٕ نِش بچاوان ۔\n16.\\tیێلہِ چُھہ غریبس وۅمید تہٕ بدکاری چھے أمِس ٲسس بند کران۔\n17.\\tوُچھو، سُہ انسان یُس خدا اصلاح کران چُھ، تێمہِ مۅکھہ گژھ نہٕ قادر مطلق سٕندِس عذابس سٍتـ̡ حقارت کٔرِتھ:\n18.\\tکیازِ سُہ چُھ دگ دِوان، تہٕ رٔٹِتھ چُھ، سُہ چُھ زخم دِوان، تہٕ تٔمۍ سٕندِ اتھہٕ چھِ پوٗرٕ گژھان۔\n19.\\tسُہ کرِ ژےٚ شیٚن مصیبتن مَنٛز بچاوُن: آ، سَتن مَنٛز گژھِ نہٕ کانہہ بُرٕ۔\n20. قحطس منز کرِ سُہ ژے موتہٕ نِش تہٕ جنگس منز تلوار کہِ طاقتہٕ نِش نجات دِنہٕ۔ {پاور: ہیب۔ اتھہٕ}\n21.\\tژیہ گژھہِ زبانہِ ہٕندِس عذابَس نِش ژوٗرِ روزُن: یێلہِ یِنہٕ وِزِ تُہۍ گژھِ تباہی نِش خوف۔ {منز...: یا، ییلہ زبنہِ دِنہٕ یوان چھِ}\n22.\\tتباہی تہٕ قحط وِزِ گژھہِ ژیہ اسُن: تہٕ نہ گژھ ژیہ زمینہٕ کین درندن نِش کھوژُن۔\n23. تِکیازِ تُہۍ گژھِو کھہٕ کِس کٔنِس سٍتـ̡ رٔلِتھ تہٕ میدانٕکۍ درندٕ روزن ژے سٍتـ̡ سٍتـ̡ امن سٍتـ̡ ۔\n24. تہٕ ژے گژھہِ پتاہ زِ تُہند خیمہ آسہِ امن سٍتـ̡ ۔ تہٕ ژے گژھ پننہِ بستی ہُند دور، تہٕ گژھ نہٕ گۅناہ کرنہٕ۔ {تُہند خیمہ چُھ...: یا، امن چُھ تُہند خیمہ } {گناہ: یا، غلط}\n25. ژے گژھہِ یہ تہِ زانان زِ تُہند بُل آسہِ بٔڈ تہٕ تُہند اولادٕ آسہِ زمینہِ ہٕندِس گاسہٕ ہٕندۍ پٲٹھۍ۔ {عظیم: یا، زیادٕ}\n26.\\tژیہ گژھہِ پورٕ وٲنسہِ منز قبرِ منز یِتھ، یتھہ پاٹھۍ مکایہِ ہُند جھٹکہٕ تٔمۍ سٕندِس موسمس منز یوان چھُ۔ {آو اِن: ہیب۔ عروج}\n27.\\tلو یہ چھہ اسہِ ژھانڈمُت، لہذا چھہ یہ {is}؛ یہ بوزو، تہٕ زان تہٕ ژے ژیہ پننہ بھلائی خٲطرٕ۔ {for...: ہیب۔ پننہِ خٲطرٕ}","1. مگر ایوب دیت جواب تہٕ وونُن،\n2.\\tکاش میون غم گژھہِ پورہ پاٹھۍ تول تہ میون آفت یکوٹہ ترازو منز! {لیڈ: ہیب۔ تُلنہٕ آمُت}\n3.\\tفی الحال آسہِ یہ سمندرچ سیکہِ کھۅتہ زیادہ وزن: لہذا چھہ میون کلام گِلہِ۔ {میٲنۍ الفاظ...: یعنی بہٕ چھُس پننہ غم ظاہر کرنہٕ خٲطرٕ لفظ یژھان}\n4.\\tخدایہ سٕندِ تیر چُھہ میانہِ اندر یُس زہر چُھہ میانہِ روح چُھہ چُھہ: خدایہ سٕنز دہشت چھے پانس پانس سٍتـ̡ میہ خلاف کھڑا کران۔\n5.\\tییلہ تس گاسہ آسہِ تیلہِ کیا جنگلی گٔر کُنہِ وِز نتہ چھہ داند پننس چارس پیٹھ کم کٔرتھ؟ {ییلہ سہ...: ہیب۔ گاسہٕ پیٹھ؟}\n6.\\tیُس ناپسندیدہ آسہِ سہ ہیکہِ نونہٕ ورٲے کھٮ۪تھ؟ یا ٹھوٗل کس سفیدس منز چھا {کنہہ ذائقہٕ؟\n7.\\tیم چیز {یِم} میانہِ روحن اتھہ لاگنس انکار کٔرۍ} چھہِ میانہِ غمگسار ماز۔\n8.\\tاوہ کاش میہ گژھہِ میون فرمائش۔ تہٕ یہ زِ خدایہ دِیہ سُہ چیز یُس بہٕ یژھان چھُس! {چیز...: ہیب۔ میٲنۍ توقع}\n9.\\tیہ تہِ زِ یہ تہِ کرِ خدایہ خۅش زِ سُہ کرِ میہ برباد۔ زِ سُہ تراوِ پنُن اتھہٕ یلہٕ، تہٕ ژٔٹِتھ ژٔٹِھ!\n10.\\tتیلہ گژھہِ میہ ونہِ تہِ آرام آسُن۔ آ، بہٕ کٔرٕ غمس منز پان سخٕت: سُہ گژھ نہٕ تراوُن۔ تکیازِ میہ چھہ نہ مقدس سند کلام ژوٗرِ تھاوان۔\n11. میون طاقت کیا چُھ، یُس میہ وۅمید کرُن؟ تہٕ میون انجام کیا چُھ، زِ بہٕ پزِ پنٕنۍ زندگی زیٹھراوٕنۍ؟\n12. کیا میٲنۍ طاقت چھا کنن ہٕنز طاقت؟ یا {چھا} میون پیتلُک ماز؟ {پیتل: ہیب۔ براسن؟}\n13. {کیا } چُھنہٕ میانہِ مدد؟ تہٕ کیا حکمت چھا میانہِ نِش بالکل نیران؟\n14.\\tیُس مُتٲثِر آسہِ تٔمِس دوستس سٍتـ̡ رحم کرنہٕ یُن۔ مگر سُہ چُھ قادر مطلق سُند خوف ترک کران۔ {چُھ مُتٲثِر: ہیب۔ پگھلُن}\n15.\\tمیانیو بٲے چُھ دھوکہ دِتھ نالہٕ ہٕندِس نالہٕ سٍتـ̡ ژلان؛\n16.\\tیِم شینہٕ کِنۍ سیاہ چھِ، {تہٕ} یتھ منز شیٖن چھُ ژوٗرِ روزان:\n17.\\tییلہ تم گرم گژھان چھہِ، تم چھہِ غیب سپدان: ییلہ یہ گرم آسہِ، تم چھہِ پننہِ جایہ کھیوان۔ {غٲب: ہیب۔ کٔرِتھ چھِ} {ییلہ...: Heb. تَمہِ کِس گرمی منز} {کھٮ۪نہٕ آمُت: ہیب۔ بنٛد کرنہٕ}\n18.\\tتہنزِ وتہِ ہٕنزِ وتہٕ چھِ اَکہِ طرفہٕ پھیرنہٕ آمٕژ۔ تِم چھِ نہٕ کُنہِ تہِ گَژھان تہٕ ختم گَژھان۔\n19.\\tتیما ہٕکۍ فوج وُچھ، شیبا ہٕچ کمپنی ٲس تِمن ہُند پیاران۔\n20. تِم گٔے پریشان تکیازِ تِمن ٲس وۅمید کٔرمٕژ۔ تِم آیہِ تتہِ تہٕ گٔیہِ شرمندٕ۔\n21. وُنکینس چھِو نہٕ تُہۍ کینہہ تہِ۔ ژیہ چھکھ وچھان {میانۍ} تراوان تہ کھوژان۔ {تُہۍ چھِو...: یا، تُہۍ چھِو تِمن ہٕندۍ پٲٹھۍ: ہیب۔ اَتھ کُن} {کُنہِ چیز: ہیب۔ نہٕ}\n22.\\tمیہ کیا ووٚنمُت، میہ نِش أنِو؟ یا دِیُن میانہِ خٲطرٕ پنُن چیزُک انعام؟\n23. یا دُشمن سٕندِ اتھہٕ نِش بچاوُن؟ یا کٔرِو مے طاقتور سٕندِ اتھہٕ نِش نجات دِنہٕ؟\n24.\\tمے ہیچھناوُن، تہٕ بہٕ کرٕ پنٕنۍ زبان تھپھ کٔرِتھ، تہٕ بہٕ کرٕ بہٕ سمجُن زِ بہٕ کَتہِ چُھس غلطی کٔرمٕژ۔\n25.\\tصحیح لفظ کوتاہ زبردستی چھہِ! مگر تُہٕندِس استدلال سٍتۍ کیا چُھ ملامت کران؟\n26.\\tکیا تۅہہ چھِو کلامَن تہٕ مایوس سٕنزِ کلامَن ہٕنز ملامت کرنُک خیال تھاوان، {یُس واو ہٕندۍ پٲٹھۍ} چھُ؟\n27.\\tآ، ژے چھکھ بے باپ مغلوب کران، تہٕ توے چھکھ پننس یارس خٲطرٕ کھنان۔ {تم مغلوب: ہیب۔ یُس وجہ چُھہ پَسُن}\n28.\\tتێلہِ گژھہِ مطمئن، میہ وچھو۔ تکیازِ {یہ} چُھہ ژیہ ظٲہر اگر بہٕ اپُز کرُن۔ {واضح...: ہیب۔ بُتھِس برونہہ کُن}\n29. واپس، بہٕ چُھس دُعا کران زِ یہ گژھہِ نہٕ بدکار آسُن۔ آ، واپس، میٲنۍ نیکی {چھ} اتھ منٛز۔ {اتھ منز: یعنی یتھ معاملس منز}\n30. کیا میانہِ زبانہِ منز چھا بدکاری ؟ میون ذوق ہیکہ نہ غلط چیزن سمجِتھ؟ {میون ذائقہ: ہیب۔ میون تالو }","1. {کیا چُھ} زمینس پیٹھ انسانس خٲطرٕ اکھ مقرر وقت؟ {کیا نہ} تمۍ سندِ دۅہ تہِ چھہ کرایہ دار سندین دۅہن ہندۍ پاٹھۍ آسان؟ {اکھ مقرر...: یا، اکھ جنگ}\n2.\\tیتھہ پاٹھۍ اکھ نوکر چھہ ژھایہ ژھایہ ژھایہِ ژھایہ تہ یتھہ پاٹھۍ اکھ کرایہ دار پننہِ کامہِ ہند ثواب ژھانڈان چھہِ: {سنجیدگی سان...: ہیب۔ گیپتھ پتہٕ}\n3. یِتھے پٲٹھۍ چُھس بہٕ ریتہٕ وادن ہٕندِ باطل ہُند مُقرر کرنہٕ آمُت، تہٕ تھکہٕ دار رٲژ چھے میہ خٲطرٕ مقرر کرنہٕ آمٕژ۔\n4.\\tییلہ بہٕ بٔرِتھ روزان چھُس، بہٕ کٔر وۅتھان تہٕ رٲژ گٔیہِ؟ تہٕ بہٕ چُھس دۅہہ کِس فجرس تام یور یور پھیُر کٔرِتھ بٔرِتھ۔ {رٲژ ...: ہیب۔ شامُک پیچھا گژھُن؟}\n5.\\tمیانہِ ماز چھہ کیمۍ تہ گردِ ہُند لوٚگ۔ میون مٕسلہٕ چھُ پھُٹمُت، تہٕ چھُس نفرت کران۔\n6.\\tمیانہِ دۅہ چھِ وونۍ والہِ سٕندِ شٹل کھۅتہٕ تیز تہٕ وۅمید ورٲے گُزاران۔\n7.\\tاے یاد تھاوُن زِ میانہِ زندگی چھیہ واو: میانہِ اچھ چھیہ نہ وۅنۍ خیر وچھان۔ {شال...: ہیب۔ واپس} {وُچھِو: وُچھُن، یعنی لُطف تُلنہٕ خٲطرٕ}\n8.\\tیمۍ میہ وچھمُت سُہ چھہ نہ میہ وچھان: چانۍ اچھ چھیہ میہ کُن تہ میہ چھہ نہ۔ {بہٕ چھُس...: یعنی بہٕ ہیکہِ نہ مزید زندٕ روزِتھ}\n9.\\t{یێلہِ} گۆو اوٚبرہ کھٮ۪وان تہٕ غٲب سپدِ: یُس قبرس تام وسان چُھہ سُہ گژھہِ نہٕ بییہ کانہہ تہِ وۅتھان۔\n10.\\tسُہ گژھِ نہٕ مزید پننِس گرس منز واپس، تہٕ نہ گژھِ أمِس جایہ پتہٕ۔\n11. لہذا بہٕ کرٕ نہٕ پنُن ٲسس رُکاونہٕ۔ بہٕ کَرٕ پننہِ روح کِس عذابس منز کتھ بہٕ کٔرٕ پننہ روح چہ تلخی منز شکایت۔\n12.\\tبہٕ چھُس سمندر، یا وہیل، یُس ژے میانہِ رٲچھ کٔرِتھ؟\n13.\\tییلہ بہٕ ونان چھُس، میون بسترٕ کرِ میہ تسلی دِنہٕ، میون کاؤچ کرِ میانہِ شکایت کم۔\n14.\\tتێلہِ چھکھ میہ خوابو سٍتـ̡ ڈراوان، تہٕ وژنو سٍتـ̡ خوفزدہ کٔرِتھ:\n15.\\tیُتھ میانہِ روح میانہِ زندگی بجایہ گُلہٕ دِنُک انتخاب کرُن، {تہٕ} موت۔ {زندگی: ہیب۔ بونز}\n16.\\tمیہ چھہ نفرت {یہ}؛ بہٕ روزٕ نہٕ ہمیشہٕ زندٕ: مے تراوُن کُنی؛ میانین دۅہن خٲطرٕ {are} vanity۔\n17. انسان کیا چُھہ یُس تٔمِس بٔرِتھ کرُن؟ تہٕ یہ زِ ژے پزِ پنُن دِل أمِس پیٹھ تھاوُن؟\n18.\\tتہٕ {یہ} ژیہ پزِ پریتھ صبحس أمس نِش گژھُن، {تہٕ} پریتھ ساعتہ کوشش کرُن؟\n19.\\tژے کُس کالس روزِ نہ میہ نِش نیرُن، تہٕ نہ تراوِ میہ توٚت تام یوٚت تام نہ بہٕ پنُن تھوک نِگِلہِ۔\n20. میہ چھہ گۅنہہ کورمُت۔ بہٕ کیا کٔرِتھ ژے کٔرِتھ، اے انسانس رٲچھ کرن وٲلۍ؟ ژے کیازِ کور میہ پانس خلاف نشانہ، یُتھ بہٕ پانس خٲطرٕ بوج۔\n21. تہٕ ژٕ کیازِ چُھکھ نہٕ میٲنۍ غلطی معافی دِوان، تہٕ میون گناہ دور کٔرِتھ؟ بہ اوسس وۅنۍ گردِ منز شوٚنگتھ۔ تہٕ ژٕ کٔرٕ صبحٲے میہ ژھانڈان، مگر بہٕ کرٕ نہٕ {بنہ}۔","1.\\tاَمہ پتہٕ دیت بلداد شُہیت سُند جواب تہٕ وونُن\n2. ژیہ کٲتِس کالس کٔرِو یِم {چیز}؟ تہٕ {کٲتِس کالس روزِ} تۅہہِ ہٕندِس لفظس {تیز واوٕکۍ پٲٹھۍ}۔\n3. کیا خدا چُھ فیصلس غلط کران؟ کِنہ خدایہ چھہ انصاف غلط کران؟\n4. اگر تۅہہِ شُرِ أمِس سٍتـ̡ گۅناہ کورمُت، تہٕ تٔمۍ کٔرِن تِمن ہٕنزِ زیادتی کِنہِ دِنہٕ۔ {for...: ہیب۔ تِمن ہٕنزِ خلاف ورزی ہٕندِس اتھس منز}\n5. یێلہِ تہٕ یێلہِ تہٕ خدایہِ سٕندِس سٍتـ̡ دُعا کٔرِو۔\n6.\\tاگر تۅہہ پاک تہٕ سیدِ سیود ٲسِو۔ یقینا وۅنۍ کرِ سُہ تۅہہِ خٲطرٕ بیدار، تہٕ چانہِ نیکی ہٕنز روزن واجنہِ۔\n7. یودوَے تُہُند آغاز لۄکُٹ اوس، توتہِ گژھہِ تُہند ٲخری انجام واریاہ ہُرُن۔\n8.\\tپرژھہ گٲر کرنہٕ خٲطرٕ، بہٕ چُھس ژے دُعا کران زِ پۯاوٕنـ̡ زمانہٕ سٍتـ̡ تہٕ پَنُن پان کٔرِو تِہٕندِس مٲلن ہٕنزِ تلاشہٕ خٲطرٕ تیار۔\n9. (تکیازِ أسۍ چھہِ راتھ تہ کینہہ زانان چھہِ، تکیازِ زمینس پیٹھ چھہِ سانۍ دۅہ ژھایہ:) {کنہِ: ہیب۔ نہٕ}\n10.\\tکیا تِم چھِنہٕ تۅہہِ ہیچھناوُن، {تہٕ} تہٕ دِلہٕ سٍتـ̡ کٔرِتھ؟\n11. کیا رش ہیکہٕ رَلہٕ ورٲے بڑِتھ؟ کیا جھنڈٕ ہیکہٕ آبہٕ ورٲے بڑتھ؟\n12.\\tییلہ زن یہ {چھُ} وُنہِ تہِ پننہِ سبزی منز، {تہٕ} ژٹنہٕ آمُت چھُ، یہ چھُ کُنہِ تہِ {باقی} کُنہِ\n13.\\tیتھے پاٹھۍ چھہِ خدایہ مشتھ گژھن والین سارِنٕے سارِنٕے وتہٕ سٍتـ̡ وتہٕ۔ تہٕ منافق سٕنز وۅمید گژھہِ ختم:\n14.\\tیمۍ سٕنز وۅمید گژھہِ ژٹنہٕ، تہٕ یٔمۍ سُند بھروسہٕ آسہِ مکھرِ ہُند جال۔ {ویب: ہیب۔ ہاؤس}\n15.\\tسُہ گژھہِ پننِس گرس پیٹھ جھکُن، مگر سُہ گژھہِ نہٕ اتھ تھپھ کٔرِتھ، مگر یہ روزِ نہٕ برقرار روزُن۔\n16.\\tسُہ چُھ آفتابس برونہہ کُن سبز تہٕ تٔمۍ سٕنز لٔر چھِ پننِس باغس مَنٛز پھٔلان۔\n17.\\tتٔمۍ سٕندِ موٗل چھِ انبارس اندۍ پٔکھۍ ؤلِتھ، {تہٕ} چھِ کنن ہٕنز جاے وُچھان۔\n18.\\tاگر سُہ أمِس پننہِ جایہِ نِش تباہ کرِ، تیلہِ کرِ أمِس نِش انکار، {ونِتھ}، مے چُھہ نہٕ ژے وُچھمُت۔\n19.\\tوچھو یۅہے چھہ تمۍ سنزِ وتہِ ہنز خوشی، تہ زمینہِ منزہ گژھن باقی کھسنہِ۔\n20.\\tوچھو، خدا کرِ نہ کٲمل انسانس کُن تراوُن، تہٕ نہ کرِ سُہ بدکارن ہنز مدد: {مدد...: ہیب۔ بد دیندار رٔٹِو اتھہٕ سٍت} {آو: ہیب۔ گژھِ نہٕ آسُن}\n21.\\tیوٚت تام سُہ تُہٕندِس ٲسس اسُن تہٕ چُھس چُھس خۅش گٔژھِتھ بٔرِتھ۔ {خوشی: ہیب۔ خوشی خٲطرٕ کرٛٮ۪کہٕ دِوان}\n22. یِم تۅہہِ سٍتـ̡ نفرت کران چِھ، تِمن گژھن شرم ہُند پلو لاگنہٕ۔ تہٕ بدکارن ہٕنز روزن جاے گژھہِ ختم۔ {گژھہِ یِن...: ہیب۔ گژھِ نہٕ آسُن}","1. اَمہِ پتہٕ دِژ ایوب جواب تہٕ وونُن،\n2. میہ چھیہ پتاہ زِ یہ چھہ حقیقت: مگر انسان کتھہ پاٹھۍ گژھہِ خدایس سیتۍ انصاف کرُن؟ {خدایس سٍتۍ: یا، خدایس برونہہ کُن؟}\n3.\\tاگر سُہ أمِس سٍتـ̡ مُقابلہٕ کرِ، سُہ ہیکہِ نہٕ ساس سٍتـ̡ أکِس سٍتـ̡ جواب دِتھ۔\n4. {سُہ} چُھہ دِلس منز دانا تہٕ طاقتور: کُس چُھ أمِس خٕلاف سختی کٔرمٕژ، تہٕ چُھ ترقی کٔرمٕژ؟\n5.\\tیُس پہاڑ ہٹاوان چھُ، تہٕ تِم چھِنہٕ پتاہ زِ یُس تِمن ہٕندِس غصس سٍتـ̡ الٹاوان چھُ۔\n6.\\tیُس زمینہِ پننہِ جایہ نِش ہلاوان چھُ، تہٕ اَمہ کِس ستون چھِ تھران ۔\n7. یُس آفتابس حکم دِوان چُھ، تہٕ سُہ چُھ نہٕ طلوع سپدان۔ تہٕ ستارن پیٹھ مہر تراوُن۔\n8.\\tیُس کُنہِ آسمانس پھٔہلٲوِتھ سمندرٕ کِس لہرن پیٹھ پکان چھُ۔ {لہر: ہیب۔ تھزر}\n9. یُس آرکٹورس، اورین تہٕ پلیاڈس تہٕ جنوبٕکۍ چیمبر بناوان چُھ۔ {آرکٹورس...: ہیب۔ ایش، سیسل تہٕ سیماہ}\n10. یُس بٔڈ کٲم کران چھُ۔ آ، تہٕ تعدادٕ ورٲے عجائب۔\n11.\\tسُہ چُھہ میہ نِش نیران، تہٕ بہٕ چُھس نہٕ وُچھان: سُہ تہِ چُھہ پکان مگر بہٕ چُھس نہٕ تس وچھان۔\n12.\\tوچھو، سہ چھہ دور کران، کُس ہیکہِ تس رُکاوٹ کٔرتھ۔ أمِس کُس وَنُن، تُہۍ کیا چُھکھ کران؟ {رکاوٹ...: ہیب۔ سہ پھیُر؟}\n13.\\tاگر خدایہ پنُن غصہ ژٹِتھ کرِ نہ، مغرور مددگارن چھہ تس تلہ کنہِ نژان۔ {فخر...: ہیب۔ فخرٕکۍ مددگار، یا، طاقت}\n14.\\tمیہ کوتاہ کم جواب دِیہ، {تہِ} پننین لفظن ہند انتخاب کرُن {تٔمِس سٍتـ̡ استدلال کرنہٕ؟\n15.\\tبہ اوسس بہ نیک اوسس، {توتہِ} بہٕ کٔرِس نہ جواب، {مگر} بہٕ کرِ پننِس قاضس نِش دُعا۔\n16.\\tاگر میہ فون کٔرِتھ، تہٕ تٔمۍ دِیُت جواب دِنہٕ۔ {توتہِ} کیا میہ چھہ نہ یقین زِ تمۍ ٲس میانہِ آواز بوزمژ۔\n17.\\tکیازِ سُہ چُھ میہ طوفانس سٍتـ̡ پھُٹراوان، تہٕ میانہِ زخم چُھہ بے وجہ بڑاوان۔\n18.\\tسُہ دِیہ نہٕ میہ دم رٹنہٕ خٲطرٕ، بلکہ کرِ میہ تلخی سٍتـ̡ بٔرِتھ۔\n19.\\tاگر {بہٕ طاقتٕچ کتھ کٔرِتھ}، لو، سُہ چُھہ مضبوط: تہٕ اگر فیصلہ کٔرِتھ، کُس کرِ میہ اکھ وق {درخواست کرنہٕ خٲطرٕ}؟\n20.\\tاگر بہٕ پننِس پانس جواز پیش کٔرِتھ، میون پنن اوس میہ مذمت کرُن: {اگر بہٕ ونان}، بہٕ چھُس {کامل}، یہ تہِ کرِ میہ بدکار ثٲبت۔\n21.\\t{اگرچہ} میہ {اوسس} کامل، {توتہِ} کیا میہ چھہ نہ پننہ روح زانان: میہ کٔر پننہ زندگی حقارت۔\n22. یہِ {چُھ} اَکھ {چیز}، تَمہِ کِنۍ چُھ مے وَنُن {یہ}، سُہ چُھ کامل تہٕ بدکارن تباہ کران۔\n23.\\tاگر یہ عذاب اچانک مارِ، سُہ گژھہِ بے گناہ سٕندِس مقدمس پیٹھ اسان۔\n24.\\tزمین چُھ بدکارن ہٕندِس اتھس مَنٛز دِنہٕ آمُت: سُہ چُھ اَمہ کِس قاضن ہٕندِس بُتھِس پیٹھ دِنہٕ آمُت۔ اگر نہ، کتہِ، {تہٕ} سُہ کُس چھُ؟\n25.\\tوۅنۍ چھہِ میانہِ دۅہ پوسٹ کھۅتہ تیز رفتار: تم چھہِ ژلان، تمن چھہ نہ کانہہ خیر وچھان۔\n26.\\tتِم چھِ تیز جہازن ہٕندۍ پٲٹھۍ، یِتھٕ پٲٹھۍ گُرِ {یُس} شکارس کُن جلدی کران چھُ۔ {تیز رفتار...: یا، جہازٕ ایبے: ہیب۔ خواہش ہٕندۍ جہاز}\n27.\\tاگر بہٕ وَنُن، بہٕ کَرٕ پنٕنۍ شکایت مٔشِد، بہٕ تراوٕ پنُن وزن، تہٕ تسلی دِنہٕ:\n28.\\tبہٕ چُھس پننیو سارِنٕے غمَو سٍتۍ کھوژان، بہٕ چھُس پتاہ زِ ژٕ کٔرِکھ نہٕ میہ بے گناہ۔\n29. {اگر} بہٕ بدکار آسہِ، تیلہِ کیازِ چھُس بہٕ بیکار محنت۔\n30.\\tاگر بہٕ شینہٕ آبہٕ سٍتـ̡ پنُن پان چھلناوُن، تہٕ پنُن اَتھٕ زانہہ تہِ صاف کرُن۔\n31.\\tتوتہِ کٔرِکھ میہ کھۅلہِ منز، تہٕ میٲنۍ پلو کرِ میہ نفرت۔ {نفرت...: یا، میہ بناو نفرت}\n32.\\tتکیازِ {سُہ} چُھہ نہٕ کانہہ انسان، یُتھ بہٕ چُھس {چُھس} بہٕ پزِ أمس جواب دِنۍ، {تہٕ} اسہِ پزِ اِکہٕ وٹہٕ فیصلس منز یِنہٕ۔\n33.\\tنہ چھہ اسہِ درمیان کانہہ دۅہہ، {یُس} اسہِ دۅشوے پیٹھ اتھہ تراوِ۔ {کنہِ...: ہیب۔ اَکھ یُس بَحَث کَرُن} {Daysman: or, umpire}\n34.\\tسُہ نِش نِش پنُن لٔر نِش تہٕ تٔمۍ سُند خوف گژھہِ نہٕ میہ خوفزدہ کرُن:\n35. {پتہٕ} بہٕ کَرٕ کَتھ تہٕ أمِس کھوژٕ نہٕ۔ مگر {یہِ} چھُنہٕ میانہِ سٍتۍ تِتھۍ کَران۔ {یہِ چھُ...: ہیب۔ بہٕ چُھس نہٕ پانس سٍتۍ تِتھۍ کٔرتھ}","1. میون روح چھہ میانہِ زندگی نشہِ تنگ آمت۔ بہٕ تراوٕ پنٕنۍ شکایت پانس پیٹھ۔ بہٕ کَرٕ پننہ روح چہ تلخی منز کتھ۔ {تھکاوُن...: یا، ژٹِتھ ژٔٹِتھ ییلہ بہٕ زندٕ روزان چھُ}\n2.\\tبہٕ وَنُن خدایہ، میہ کٔر نہٕ مذمت۔ مے ہاو تہٕ ژٕ کتھ کٔرِتھ چُھکھ میہ سٍتـ̡ مُقابلہٕ۔\n3. کیا یہ چُھہ تۅہہِ خٲطرٕ خیر زِ ژے کٔرِو ظُلم کٔرِتھ، زِ ژے کٔرِو پننین اتھن ہٕنزِ کامہِ حقارت کٔرِتھ، تہٕ بدکارن ہٕندِس مشورس سٍتـ̡ چمکُن؟ {کٲم: ہیب۔ لیبر}\n4.\\tژیہ چھا مازچ نظر؟ یا ژیہ وچھکھ یتھہ پاٹھۍ انسان وچھان چھہِ؟\n5. {کیا تۅہہِ دۅہہ} چھا انسان سٕندِ دۅہہٕ ہٕندۍ پٲٹھۍ؟ {کیا چُھ} تُہند ؤری انسان سٕندِ دۅہہ،\n6. یُس ژے میانہِ گناہ ہُند پرژھہٕ گٲر کٔرِتھ، تہٕ میانہِ گۅناہ ژھانڈِو؟\n7. ژے چھے پتاہ زِ بہٕ چُھس نہٕ بدکار ۔ تہٕ {تتہِ} چُھہ نہٕ کانہہ تہِ یُس تُہندِ اتھہٕ سٍتۍ نجات دِتھ۔ {تو...: ہیب۔ یہ چھہ تۅہہِ علمس پیٹھ}\n8.\\tچانہِ اتھو بنوو میہ تہٕ بنوو میہ اندۍ پکھۍ۔ توتہِ چھکھ میہ تباہ کران۔ {ہیو...: ہیب۔ میہ کٔر دگ دگ دِنہٕ}\n9. یاد تھاوُن، بہٕ چھُس ژے التجا کران زِ ژے چھُکھ میہ میژِ ہٕندۍ پٲٹھۍ بنوومُت۔ تہٕ کیا ژٕ کٔرِکھ مےٚ دُبارٕ مٔژِس منٛز؟\n10.\\tژے چھُکھ نہٕ میہ دۄدٕ پٲٹھۍ، تہٕ پنیر ہٕندۍ پٲٹھۍ؟\n11.\\tژے چُھکھ میہ مٕلہٕ تہٕ ماز لٲگِتھ تہٕ أڈجہِ تہٕ رٔنگۍ لٔگِتھ لٔگِتھ ۔ {فینسڈ: ہیب۔ ہیجڈ}\n12. ژے دِژ مے زندگی تہٕ عنایت، تہٕ چانہِ زیارت کٔر میون روح رژھراوُن۔\n13.\\tتہٕ یِم {چیز} چھِو ژے پننِس دِلس مَنٛز ژوٗرِ تھوومٕژ: بہٕ چھُس پتاہ زِ یہِ {چُھ} ژے سٍتـ̡ ۔\n14.\\tاگر بہٕ گۅنہہ کٔرِتھ تہٕ ژے کٔرِکھ نہٕ میانہِ گناہ نِش بٔری۔\n15.\\tاگر بہٕ بدکار آسہِ، افسوس۔ تہٕ {اگر} بہٕ نیک آسہِ، {توتہِ} بہٕ کلہٕ تُلِتھ نہٕ۔ {بہٕ چُھس} پریشٲنی سٍتۍ بٔرِتھ۔ تێلہِ وچھ میٲنۍ عذاب۔\n16. امہ مۅکھہ چُھ ہُران۔ ژے چھکھ میہ اکھ زبردست شیر سٕندۍ پٲٹھۍ شکار کران: تہٕ بییہِ چھکھ ژے پانس میہ پیٹھ حیرت انگیز ہاوان۔\n17. تہٕ ژے کٔرِکھ میانہِ خلاف پنٕنۍ گواہ تازٕ تہٕ میانہِ پیٹھ پنُن غصہٕ ہُرراوُن۔ تبدیلیہٕ تہٕ جنگ {چھ} میٲنس خلاف۔ {گواہ: یعنی طاعون}\n18. تیلہِ کیازِ کٔر ژے میہ رحمہ منزہ نیبر؟ ہا کاش میہ اوس بھوت تروومُت، تہٕ کٲنسہ اچھ ٲس نہ میہ وچھمژ!\n19.\\tمیہ گژھہِ ہا تتھہ پاٹھۍ آسُن زِ میہ آسہ نہ۔ میہ گژھہِ رحم پیٹھہ قبرس تام نِنہ۔\n20. {کیا } چھُنہٕ میانہِ دۅہ کم؟ بند کرُن {تیلہِ، تہٕ} مے کُنہِ کُنہِ، تاکہ بہٕ رژھ\n21.\\tبہٕ گژھنہٕ برونہہ کُنہِ تہِ واپس، {حتیٰ کہ} تاریک تہٕ موتٕچ ژھایہِ ہٕندِس سرزمینس کُن۔\n22.\\tانہِ گٹہِ ہُند سرزمین، یُس انہِ گٹہِ ہُند تہٕ موتُک ژھایہ چھُ، کُنہِ تہِ ترتیبہٕ ورٲے تہٕ {ییتہِ}گاش {چھُ} انہِ گٹہِ ہٕندۍ پٲٹھۍ۔","1.\\tاَمہِ پتہٕ دِیُت زوفر نامتھِس جواب تہٕ وونُن،\n2.\\tلفظن ہندِ کثرت ہند جواب گژھہِ نہ دِنہ؟ تہٕ کتھ بٔرِتھ انسان گژھہِ جواز آسُن؟ {پور...: ہیب۔ چپنہٕ سٕندِ}\n3.\\tچانہِ اپُز پزِ انسان ژھوپہ رژھراوُن؟ تہٕ ییلہ ژیہ ٹھٹھہٕ کٔرِو، کیا کانہہ تہِ انسان کرِ نہٕ ژےٚ شرمندٕ؟ {اپُز: یا، آلات}\n4.\\tکیازِ ژے چُھہ وونمُت، میون نظریہ چُھہ پاک تہٕ بہٕ چُھس چانہِ نظرن منز پاک۔\n5.\\tمگر اے خدایہ کٔرِہ کتھ تہٕ ژے سٍتـ̡ وُپھ کھولِتھ تہٕ ژے سٍتـ̡ کُنہِ\n6. تہٕ یہ زِ سُہ کرِ ژےٚ حکمتٕکۍ راز ہاوان، زِ تِم چھِ دۄگنہٕ یُس چھُ! تێمہِ کِنۍ زانِو زِ خدا چُھ تۅہہِ سٍتـ̡ تہندِ بدکاری کھوتہٕ کم {مستحق} حٲصل کران۔\n7.\\tکیا ژیہ ژھانڈِتھ خدایہ ژھانڈِتھ؟ کیا ژٕ ہیککھا قادر مطلق سُند کمال تام لٔبتھ؟\n8. {یہِ} چُھہ آسمانس ہیوٗ تھوٚد۔ ژیہ کیا ہیکہِ کٔرِتھ؟ جہنم کھوتہٕ زیادٕ سرٛوٚن؛ ژیہ کیا ہیکہِ پتاہ ٲستھ؟ {یوتاہ تھد...: ہیب۔ جنتٕچ بلندی}\n9. امچ پیمائش {چُھ} زمینہٕ کھوتہٕ زیٹھ تہٕ سمندرٕ کھوتہٕ زیادٕ وسیع ۔\n10.\\tاگر سُہ ژٔٹِتھ ژٔٹِتھ بند کٔرِتھ یا یکوٹہ جمع گژھِ، تیلہِ کُس ہیکہِ تس رُکاوٹ کٔرِتھ۔ {کَٹ...: یا، کٔرِو تَبدیٖل} {رکاوٹ...: ہیب۔ سہ پھیُر؟}\n11.\\tتکیازِ سُہ چُھ بکار انسانس زانان: سُہ چُھ بدکاری تہِ وُچھان۔ کیا سُہ چُھ نہٕ تیلہٕ {یہ} پیٹھ غور کران؟\n12.\\tبیکار انسان آسہِ عقلمند، حالانکہ انسان گژھہِ جنگلی گَرِ ہٕندِس کۅکرس ہٕندۍ پٲٹھۍ۔ {بیکار: ہیب۔ خٲلی}\n13.\\tیێلہِ ژے پَنُن دِل تیار کٔرِو، تہٕ پَنُن اَتھٕ أمِس کُن پھٔہلٲوِو۔\n14.\\tیێلہِ بد کاری تہِ آسہِ تۅہہِ دوٗر تہٕ بد کاری گژھہِ نہ پننین خیمن مَنٛز روزُن۔\n15.\\tتیلہِ کٔرِو تُہۍ پنُن بُتھ بے داغ تُلِتھ۔ آ، ژیہ گژھہِ ٹھہراونہ آمت، تہ گژھہِ نہ کھوژُن:\n16.\\tکیازِ ژے گژھہِ {پنُن} مصیبت مٔشِد، {تہٕ} یاد تھاوُن {یہ} یُس آبہٕ {یُس} ژلان چھُ:\n17.\\tتہٕ تُہٕنز وٲنسہِ آسہِ دوپہرٕ کھۅتہٕ صاف ۔ ژیہ گژھہِ صبحکۍ پاٹھۍ چمک۔ {واضح گژھہِ...: ہیب۔ ہیرِ کُن وۅتھُن}\n18.\\tتہِ روزِ تۅہہ محفوظ، تکیازِ وۅمید چھیہ۔ آ، ژیہ کٔرِو پانس اندۍ پکھۍ، تہٕ ژیہ کٔرِو پنُن آرام رژھراونہٕ۔\n19.\\tتہِ گژھہِ ژیہ بٔرِتھ تہٕ کانہہ تہِ کرِ نہ ژیہ خوف۔ آ، واریاہ کرِ تۅہہِ سٍتـ̡ سوچہٕ۔ {بناو سوٹ...: ہیب۔ پنُن بُتھِس کٔرِو}\n20.\\tمگر بدکارن ہٕنزِ أچھ گژھن ناکام تہٕ تِم گژھن نہٕ ژلنہٕ، تہٕ تِہٕنز وۅمید گژھہِ بھوت سٕندِ تراونہٕ سٍتـ̡ ۔ {تِم کرِ...: ہیب۔ تِمن نِش گٔژھ ژٔلِتھ ژٔلِتھ} {دِنہٕ...: یا، شاہ ہُند پھپھ}","1. تہٕ ایوب دیت جواب تہٕ وونُن،\n2. کانہہ شک چھُنہٕ مگر تُہۍ چھِو عوام، تہٕ حکمت گژھہِ توے سٍتـ̡ مرُن۔\n3.\\tمگر میہ تہِ چھہ تۅہہ تہِ سمجھان۔ بہٕ چھُس نہٕ ژےٚ کھۄتہٕ کمتر: آ، یِتھۍ چیزن ہٕنز کُس چھُنہٕ خبر؟ {سمجھ: ہیب۔ اکھ دل} {بہٕ چُھس...: ہیب۔ بہٕ چُھس نہٕ ژےٚ کھوتہٕ کم گژھان} {کُس...: ہیب۔ یِمن سٍتۍ چھُنہٕ یِتھٕ کٔرِتھ؟}\n4.\\tبہٕ چُھس پننِس ہمساین سُند طنز کرنہٕ آمُت، یُس خدایہ سُند پکار کران چُھ، تہٕ سُہ چُھ أمِس جواب دِوان: نیک سٍتـ̡ چُھہ اَسُن کٔرِتھ ہُران۔\n5.\\tیُس کھۅر کھسنہ خاطرہ تیار آسہِ، سہ چھہ شمعہ ہیو یُس پننہِ خیالس منز حقارت کران چھہ۔\n6.\\tڈاکوَن ہٕندِ خیمہ چِھہ روزان، تہٕ یِم خدایہ سٍتـ̡ اشتعال دِوان چِھہ تِم چِھ محفوٗظ۔ یمۍ سٕندِس اتھس منز خدا چُھ {وافر پٲٹھۍ} انان۔\n7.\\tمگر وۅنۍ پرژھ درندن تہٕ تِم ہیچھناوٕنۍ۔ تہٕ ہوہٕکۍ جاناوار، تہٕ تِم وَنَن ژےٚ:\n8. یا زمینس سٍتـ̡ کتھ کرٕن، تہٕ سُہ کرِ تۅہہِ ہیچھناوُن، تہٕ سمندرٕچ گاڈٕ کرِ تۅہہِ سٍتـ̡ اعلان۔\n9. کُس چُھ نہٕ پتاہ زِ یِمن سارِنٕے مَنٛز چُھ خداوند سٕندِ اَتھن یہِ کورمُت؟\n10. یمۍ سٕندِس اتھس منز چُھہ پریتھ جاندار سُند روح تہٕ سارِنٕے انسانہٕ سُند سان۔ {روح: یا، زندگی} {سٲری ...: ہیب۔ انسان سُند سورے ماز}\n11.\\tکَن چھُنہٕ لفظن ہٕنز کوشش کران؟ تہٕ ٲسس چُھ تٔمۍ سُند ماز؟ {ٲس: ہیب۔ تالو }\n12. قدیم {is} حکمت سٍتۍ؛ تہٕ دۅہن ہٕندِس طویلس منز سمجُن۔\n13.\\tأمِس سٍتـ̡ چُھہ حکمت تہٕ قوت، أمِس سٍتـ̡ مشورٕ تہٕ فہم ۔ {سۭتۍ...: یعنی خدایس سۭتۍ}\n14.\\tوُچھو سُہ پھُٹِتھ تہٕ یہِ ہیکہِ نہٕ دُبارٕ تعمیر کٔرِتھ: سُہ چُھ أکِس انسانس بند کٔرِتھ، تہٕ یێلہِ ہیکہِ نہٕ کانہہ یلہٕ ٲسِتھ۔ {up: Heb. اَپَن}\n15.\\tوچھ سُہ آب رُکٲوِتھ تہٕ تِم چھِ خشک گٔژھان، تہٕ سُہ تہِ چھُ تِم نیبر کڈان تہٕ تِم چھِ زمینہِ ہٕندِس سٍتـ̡ ؤلِتھ دِوان۔\n16.\\tأمِس سٍتـ̡ طاقت تہٕ دانایی: دھوکہٕ دِنہٕ وول تہٕ دھوکہٕ دِنہٕ وول {چُھ} أمِس۔\n17. سُہ چُھ مشیرن خراب کٔرِتھ نِوان تہٕ قاضین بیوقوف بناوان۔\n18.\\tسُہ چُھ بادشاہن ہُند بندھن یلہٕ تراوان، تہٕ تِمن ہٕندِس کمرس گٔنڈِتھ گٔنڈِتھ۔\n19.\\tسُہ چُھ شہزادن برباد کٔرِتھ نِوان تہٕ طاقتور سُند تختہ الٹان۔\n20. سُہ چُھ امانت دار سٕنز کتھ دور کٔرِتھ، تہٕ بُزرگ سٕنز سمجھ نِش نِوان۔ {تقریر...: ہیب۔ وفادارن ہٕندِس لب}\n21. سُہ چُھ شہزادن پیٹھ حقارت تراوان، تہٕ طاقتور سُند طاقت کمزور کران۔ {کمزور...: یا، مضبوط سُند کمرہ یلہٕ کرُن}\n22.\\tسُہ چُھ انہِ گٹہِ منزٕ سرٛوٚن چیز دریافت کران، تہٕ موتُک سایہ گاش دِنہٕ خٲطرٕ انان۔\n23. سُہ چُھ قومن ہُند اضافہ کران، تہٕ تمن تباہ کران: سُہ چُھ قومن بڑاوان، تہٕ تمن دُبارٕ دِوان۔ {straiteneth: Heb. لیڈیتھ اِن}\n24.\\tسُہ چُھ زمینہٕ کِس لُکن ہُند دِل نِوان تہٕ تِمن بیابانن مَنٛز پھیران دِوان {یتہِ نہٕ کانہہ وتھ آسہِ}۔\n25.\\tتِم چھِ گاشہٕ ورٲے انہِ گٹہِ منز گٔژھان، تہٕ سُہ چُھ تِمن {a} شرابہٕ {انسان} ہٕندۍ پٲٹھۍ۔ {سٹگر: ہیب۔ وانڈر}","1.\\tلو، میانہِ اچھ چھیہ یہ سورے {یہ} وچھمژ، میانہِ کنن بوز تہ سمجھ۔\n2.\\tژیہ کیا چھیہ پتاہ، {یۅہے} میہ تہِ چھیہ پتاہ زِ بہٕ چھُس نہ ژے کھوتہ کمتر آسان۔\n3. یقینا بہٕ کرٕ خدایس سٍتۍ کتھ کرنہٕ، تہٕ بہٕ چُھس خدایس سٍتۍ استدلال کرُن یژھان۔\n4.\\tمگر تم چھہِ اپُز بناوان تہ تم چھہِ سٲری طبیب یُس نہ کانہہ قدر چھہِ۔\n5. کاش ژیہ کٔرِو پَنُن سکون! تہٕ یہ گژھہِ تہنز دانشمندی آسٕنۍ۔\n6.\\tوۅنۍ بوز میون استدلال تہ بوز میانہِ وٹھن ہنز التجا بوز۔\n7. کیا تُہۍ کٔرِو خدایہِ سٕندِ خٲطرٕ بدکار کتھ کرنہٕ؟ تہٕ أمِس خٲطرٕ دھوکہ دہی سان کتھ کٔرِتھ؟\n8. کیا تُہۍ کٔرِو تٔمۍ سُند شخص قبول؟ کیا تُہۍ کٔرِو خدایہِ سٕندِ خٲطرٕ مقابلہٕ؟\n9. کیا یہ چھا جان زِ سہ گژھہِ تۅہہِ ژھانڈنہِ؟ یا یتھہ پاٹھۍ اکھ انسان بییِس پیٹھ ٹھٹھہٕ کران چھُ، کیا تۅہہ چھِو أمس ٹھٹھہٕ کران؟\n10.\\tسُہ کرِ یٔقیٖنی طور تۅہہِ ملامت اگر ژوٗرِ پٲٹھـ̡ نفرن ہُند قبوٗل کٔرِو۔\n11. کیا تٔمۍ سٕنزِ عظمتس کرِ نہٕ تۅہہ خوف؟ تہٕ تٔمۍ سُند خوف چھُ ژےٚ پیٹھ؟\n12.\\tچانۍ یاداشت چھیہ رژھ پٲٹھۍ، چانۍ لاش چھیہ میژِ ہندس جسمس منز۔\n13.\\tپَنُن رٔٹِتھ رٔٹِتھ تھاوُن، یُتھ بہٕ کَتھ کٔرِتھ، تہٕ یِمن ہُند کُنہِ کُنہِ تہِ کُنہ {ہولڈ...: ہیب۔ میہ نش گژھ ژھۄپہٕ}\n14.\\tبہٕ کیازِ چُھس پنُن ماز پننین دندن منز رٹان تہٕ پنُن زُو پننِس اتھس منز تراوان؟\n15. یودوے سُہ میہ مارِ، توتہِ کرٕ بہٕ تس پیٹھ بھروسہ: مگر بہٕ کرٕ تس برونہہ کنہِ پنٕنۍ وتھ قٲیم۔ {برقرار تھاوُن: ہیب۔ ثٲبت کٔرِو، یا، دلیل کٔرِو}\n16.\\tسُہ تہِ گژھِ میٲنۍ نجات تہِ، تکیازِ منافق گژھہِ نہٕ تس برونہہ کُن یِنہٕ۔\n17.\\tمیون کلام تہٕ میون اعلان بوزو پننیو کنو سٍتۍ۔\n18. وُچھِو وُن، مے چُھس {my} کامہِ ہُند حُکُم دِژمُت۔ میہ چھیہ پتاہ زِ بہٕ گژھہِ جٲیز۔\n19.\\tکُس {چُھ} سُہ {یُس} میانہِ نِش درخواست کرِ؟ فی الحال اگر بہٕ پننہ زبان تھپھ کٔرتھ، بہٕ تراوٕ بھوت۔\n20.\\tمیہ کٔرِتھ کٔرِو نہ میہ دۅشوے کتھہِ: تیلہ کٔرٕ نہ بہٕ ژے نِش پنُن پان ژوٗر۔\n21.\\tپَنُن اَتھٕ کٔرِو میہ نِش دور تہٕ پنُن خوف گژھہِ نہٕ میہ خوف۔\n22. تیلہِ کرو ژے بلاو، تہٕ بہٕ کٔرٕ جواب: یا بہٕ کتھ کرٕن، تہٕ ژے دِیُس جواب دِیُن۔\n23.\\tکٲتیاہ {چھِ} میٲنۍ بدکار تہٕ گۅناہ ؟ میہ کرو میون گناہ تہٕ پنُن گۅناہ زانن۔\n24.\\tژے کیازِ چھکھ پنُن بُتھ ژوٗرِ تھاوان تہٕ میہ دُشمن ہٕندِ خٲطرٕ دِژمُت؟\n25.\\tکیا ژیہ پھُٹراوُن پنہٕ وُن یُس یور کُن پکناوان چھُ؟ تہٕ کیا ژٕ کٔرِکھ خشک کُنہِ\n26.\\tتکیازِ ژے چُھکھ میٲنس خلاف تلخ کتھ لیکھان تہٕ میانہِ جوانی ہٕندِس بدکارس سٍتـ̡ بناوان چھُ۔\n27.\\tژے چھکھ میٲنۍ کھۅر تہِ سٹاکس منز تھپھ کٔرتھ، تہٕ میانین سارنٕے وتن پیٹھ نظر تراوان۔ ژے کٔر میانین کھورٮ۪ن پیٹھ اکھ نشان۔ {وچھو...: ہیب۔ مشٲہدٕ} {ہیلز: ہیب۔ روٹس}\n28.\\tتہٕ سُہ چُھ أکِس گٔژِھس چیزٕکۍ پٲٹھۍ کھٮ۪وان یُس کیم کھٮ۪نہٕ یوان چھُ۔","1. مرد {یعنی} زنانہِ سٍتۍ پٲدٕ سپدُن {چُھ} کینہہ دۅہہ، تہٕ مصیبت سٍتۍ بٔرِتھ۔ {کینٛہہ...: ہیب۔ دۅہن ہند کم}\n2. سُہ چُھ پوشہٕ ہٕندۍ پٲٹھۍ، تہٕ ژٹنہٕ آمُت: سُہ تہِ چُھ ژھایہِ ہٕندۍ پٲٹھۍژلان، تہٕ چُھہ نہٕ جٲری روزان۔\n3. تہٕ کیا ژٕ چھکھ یتھس شخصس پیٹھ پنٕنۍ نظر کھولان تہٕ مے پانس سٍتۍ فیصلہ کٔرتھ؟\n4. ناپاک منزٕ کُس ہیکہِ صاف {چیز} کٔرِتھ؟ اکھ نہٕ۔ {ہیکن...: ہیب۔ دِنہٕ}\n5.\\tتٔمۍ سٕندِس دۅہس مُقرر سپدِتھ، تٔمۍ سٕندِس ریتن ہُند تعداد ژے سٍتـ̡ چُھہ تٔمۍ سٕندِس حدس مُقرر کٔرِتھ یُس نہٕ سُہ ہێکہٕ پٲٹھـ̡ پۯاونہٕ آمُت۔\n6.\\tأمِس نِش پھیرو، یُتھ سُہ آرام کرِ، یوتام نہٕ سُہ کرایہ دار سٕندِ حثیتہٕ پنُن دۅہ پورٕ کرِ۔ {باقی: ہیب۔ بند کرُن}\n7. تکیازِ کُلِچ وۅمید چھیہ زِ اگر یہ ژٹنہٕ ییہ، سہ گژھہِ بییہ پھۅلُن، تہ امچ نرم لنجہ گژھہِ نہ ختم۔\n8.\\tیێلہِ زَن اَمیُک موٗل چھُ زمینہِ مَنٛز پرٛون تہٕ اَمیُک ذخیرٕ چھُ زٔمیٖنہٕ مَنٛز مران۔\n9.\\t{توتہِ} آبہٕ چہِ خوشبو سٍتۍ چھُ یہِ کُلِس ہٕندۍ پٲٹھۍ کُلۍ نیران۔\n10.\\tمگر انسان چھہ بھوت تراوان، تہ سہ کتہِ چھہِ؟ {فضول...: ہیب۔ کمزور چھُ، یا ژٹنہٕ آمُت}\n11.\\tیێلہِ سمندرٕ منزٕ آب چھُ ختم سپدان، تہٕ سٔہلاب چھُ سٔلِتھ خشک سپدان:\n12.\\tتێلہِ چُھ انسان بٔنِتھ تہٕ وۅتھان چُھہ نہٕ: یوتام نہٕ آسمانہٕ بێیہِ، تِم گژھن نہٕ بیدار سپدِتھ تہٕ نِندرِ منزٕ بیدار سپدِ۔\n13. اے ژے کٔرِکھ میہ قبرِ منز ژوٗرِ تھاوُن، یێلہِ ژٕ مے اکھ مُقرر وقت مقرر کرُن، تہٕ مے کرٕ یاد!\n14.\\tاگر کانہہ انسان مرُن، کیا سُہ زندٕ روزُن؟ میانہِ مقرر وقتٕکۍ سارِنٕے دۅہن روزٕ بہٕ انتظار، یوٚت تام میانہِ تبدیلی یِنہٕ۔\n15.\\tژے کٔرِو بلاوُن، تہٕ بہٕ کٔرٕ ژے جواب دِنہٕ: ژے آسہٕ پننین اتھن ہٕنزِ کامہِ ہٕنز خواہش۔\n16.\\tوۅنۍ چُھہ ژے میانین قدمن ہُند شمار کران: کیا ژٕ چُھکھ نہٕ میانہِ گۅنہٕ وُچھان؟\n17.\\tمیون گناہ چھُ أکِس ٹھیلس منز بند کرنہٕ آمُت، تہٕ ژے کٔر میٲنۍ بدکاری ژٹان۔\n18.\\tتہِ پٔزۍ پٲٹھـ̡ یُس پہاڑ پیوٚو سُہ چُھہ کُنہِ تہِ کُنہِ جایہ ہٹاونہٕ آمُت۔ {cometh...: Heb. fadeth}\n19. آب چُھ کنن لاگان تہٕ ژے چُھہ زمینہِ ہٕنزِ گردِ سٍتـ̡ واش کٔرِتھ واش کٔرِتھ۔ تہٕ توے چھکھ انسان سٕنز وۅمید تباہ کٔرِتھ۔{واشسٹ...: ہیب۔ اوور فلوایسٹ}\n20.\\tتُہۍ چُھہ أمِس خٕلاف ہمیشہٕ خٲطرٕ غٲلب، تہٕ سُہ چُھہ نیران: تہٕ ژے چھُکھ تٔمِس بُتھ بدلاوان، تہٕ سُہ سوزان چھُ۔\n21.\\tتٔمۍ سٕندِ نیچوۍ چھِ عزت دِنہٕ یوان، تہٕ سُہ چُھ نہٕ پتاہ تھاوان۔ تہٕ تِم چھِ کم کرنہٕ آمٕتۍ، مگر سُہ چُھ نہٕ تِمن ہُند احساس کران۔\n22. مگر تٔمۍ سُند ماز گژھہِ دگ تہٕ تس اندر گژھہِ تسُند روح ماتم کرنہٕ۔","1.\\tاَمہ پتہٕ دِژ الیفاز تیمانیتس جواب تہٕ وونُن،\n2. کیا دانشمند شخص بیکار علم بولُن، تہٕ مشرقی واو سٍتۍ پنُن پیٹ بٔرِتھ؟ {بیکار...: ہیب۔ ہواہُک علم}\n3. کیا تس پزیا غیر منفعتی کتھہِ سٍتۍ استدلال کرُن؟ یا تِمن تقریرن سٍتۍ یِمن سٍتۍ سُہ کانہہ خیر ہیکہِ نہٕ کٔرِتھ؟\n4. آ، ژے چھکھ خوف دور کران، تہٕ خدایہ سٕندِ برونہہ کُن دعا کرُن روکُن۔ {کاسٹسٹ...: ہیب۔ کَرنہٕ آمُت} {دُعا: یا، تقریر}\n5.\\tتکیازِ چُھہ چُھہ پننہِ بدکاری ہُند اظہار کران، تہٕ ژے چُھکھ چالاکی سٕنز زبان ژاران۔ {Uttereth: Heb. ہیچھناوُن}\n6. تُہٕندِس وَتھٕ سٍتـ̡ چُھہ تۅہہِ سٍتـ̡ مذمت کران، تہٕ بہٕ چُھس نہٕ تۅہہِ سٍتـ̡ گوٲہی دِوان۔\n7.\\t{آرٹ} ژیہ گۅڈنیُک انسان {یُس} اوس زامُت؟ کِنہ ژیہ اوسکھ بالن برونہہ کنہِ بناونہٕ آمُت؟\n8.\\tکیا ژیہ بوزمُت خدایہِ سُند راز؟ تہٕ کیا تُہۍ چھِو پننِس پانس سٍتۍ حکمت رٔٹتھ؟\n9.\\tژیہ کیا چھیہ پتاہ زِ اسہِ چھیہ نہ پتاہ۔ {کیا چُھ} ژیہ سمجھان، یُس {چُھ} اسہِ منز چُھنہٕ؟\n10.\\tاسہِ سٍتـ̡ چھِ دۅشوے سُرِ کلہٕ دار تہٕ واریاہ بُزرگ مرد، یُس تہندِس مٲلہِ سٍتـ̡ واریاہ بٔڈۍ چھُ۔\n11. کیا خدایہ سُند تسلی چھا ژے سٍتـ̡ لۄکٕٹۍ؟ ژیہ چھا کانہہ راز؟\n12. چانہِ دِل کیازِ چُھہ ژےٚ ژےٚ نِوان؟ تہٕ چانۍ أچھ کیاہ چھِ أچھ أچھ کران،\n13.\\tیُتھ زِ ژے کٔرِو پنُن روح خدایہ سٍتـ̡ پھیُرِتھ، تہٕ یِتھٕ کُنہِ کلامَس پى۪ٹھہٕ نیرُن؟\n14.\\tانسان کیا چھہ یُس صاف آسُن؟ تہٕ {یُس} زنانہِ ہُند زامُت چُھ، زِ سُہ گژھہِ نیک آسُن؟\n15.\\tوچھو سُہ چُھنہٕ پننین سنتن پیٹھ کانہہ بھروسہٕ تھاوان۔ آ، آسمان چھہ نہ تس نظرِ منز صاف۔\n16.\\tکوتاہ زیادٕ مکروہ تہٕ ناپاک انسان چُھ، یُس بدکاری آبہٕ ہیو چیوان چُھ؟\n17. بہٕ ہاوٕ ژے ہاو، بوزو۔ تہٕ سُہ {یُس} مے وُچھمُت چُھس بہٕ اعلان کٔرِتھ؛\n18.\\tکُس دانشمندو چھہ پننین مٲلن نشہِ وننہ آمت تہ ژوٗرِ تھوومُت چھُ:\n19. یٔمِس کُنی زمین دِنہٕ آیہ، تہٕ تِمن منز اوس نہٕ کانہہ اجنبی گزران۔\n20.\\tبدکار چھُ سارِنٕے دۅہن دَگ سٍتـ̡ دَگ کَران، تہٕ ؤرین ہُند تعداد چھُ ظٲلم سٕندِ خٲطرٕ پوشیدٕ آسان۔\n21.\\tتسٕندِس کنن منز چُھ اکھ خوفناک آواز: خوشحالی منز گژھہِ تباہ کرن وول أمِس پیٹھ واتہِ۔ {اکھ خوفناک...: ہیب۔ خوفچ آواز}\n22.\\tسُہ چُھہ نہٕ یقین کران زِ سُہ گژھہِ انہِ گٹہِ منزٕ واپس، تہٕ تلوار ہُند انتظار چُھ کران۔\n23.\\tسُہ چُھ روٹی خٲطرٕ نیبر کُن پھیران، {ونان}، کتہِ چُھہ یہِ؟ تس چھیہ پتاہ زِ انہِ گٹہِ ہند دۅہ چھہ تمۍ سندِ اتھس پیٹھ تیار۔\n24. مصیبت تہٕ اذیت کرِ أمِس خوف۔ تِم گژھن أمِس خٕلاف غٲلب، یُس جنگہٕ خٲطرٕ تیار بادشاہ چھُ۔\n25. تکیازِ سُہ چُھ خدایس خلاف پنُن اتھہٕ بڑاوان، تہٕ خدایس خلاف چُھ پنُن پان مضبوط بناوان۔\n26.\\tسُہ چُھ أمِس کُن ژلان {حتی} گردنہٕ پیٹھ، پننین بکلرن ہٕندِس موٚٹِس باسس پیٹھ:\n27.\\tتکیازِ سُہ چُھ پنُن بُتھ موٹنہٕ سٍتـ̡ تھپھ کٔرِتھ، تہٕ چُھہ پَنٕنـ̡ پٲٹھـ̡ چربی ہٕندِس کُلِس سٍتـ̡ کٔ\n28. تہٕ سُہ چُھ ویران شہرن مَنٛز روزان، {تہٕ} تِمن گھرن مَنٛز روزان یِمن منز نہٕ کانہہ انسان روزان چُھ، یِم ڈھیر بننہٕ خٲطرٕ تیار چھِ۔\n29. سُہ گژھِ نہٕ امیر، نہ روزِ تٔمۍ سُند مال روزُن، تہٕ نہ روزِ سُہ زمینس پیٹھ امہِ سٕندِس کمالس زیٹھراوُن۔\n30. سُہ گژھِ نہٕ انہِ گٹہِ منزٕ نیرُن۔ شعلہٕ گژھہِ تٔمۍ سٕنزِ لنجہِ خشک تہٕ سُہ گژھہِ ٲسٕچ شہس سٍتـ̡ ژٔلِتھ۔\n31.\\tیُس دھوکہ دِنہٕ آمُت آسہِ، سُہ گژھہِ باطل پٲٹھـ̡\n32.\\tیہ گژھہِ تٔمۍ سٕندِس وقتس برونہہ مکمل کرنہٕ یُن، تہٕ تٔمۍ سٕنز شاخ گژھہِ نہٕ سبز آسٕنۍ۔ {مکمل: یا، کٹ آف}\n33.\\tسُہ کٔرِن پنُن پوٚت انگور بیلہٕ ہٕندۍ پٲٹھۍ، تہٕ پَنُن پوش تراوِ زیتون۔\n34.\\tمنافقن ہٕنزِ جماعت گژھہِ ویران تہٕ نار گژھہِ رشوت خوری ہٕندِس خیمہ سٍتـ̡ کھالنہٕ۔\n35.\\tتِم چھِ شرارتُک تصور کران، تہٕ باطل پٲدٕ کران تہٕ تِہُند یٔڈ چھُ دھوکہ دِوان۔ {باطل : یا، بدکاری}","1. اَمہِ پتہٕ دِژ ایوب جواب تہٕ وونُن،\n2.\\tمیہ چھیہ یژھہ واریاہ کتھہ بوزمژ: بدبخت تسلی دِنہٕ وٲلۍ۔ {بدبخت: یا، پریشان}\n3.\\tفضول لفظن ہند خاتمہ گژھہِ؟ یا ژیہ کیا چُھہ حوصلہٕ دِوان زِ ژیہ جواب دِیُن؟ {بیکار...: ہیب۔ ہوا ہٕکۍ لفظ}\n4.\\tبہٕ تہِ ہیوٚک تۅہہ یتھہ پاٹھۍ کتھ کٔرتھ: اگر چانۍ روح میانہِ جایہ آسہِ، بہٕ ہا ژے خلاف لفظ جمع کٔرتھ، تہٕ ژے کُن کلہ ہلاوان۔\n5.\\t{مگر} میہ کٔر ژیہ پننہ ٲسس سیتۍ مضبوط، تہ وٹھ پھیرن سیتۍ گژھہِ ژیہ ژیہ غم۔\n6.\\tبہ بہ چھس کتھ کران، میون غم چھہ نہ کم سپدان: تہ {اگرچہ} میہ کیا چھہ رژھرتھ؟ {کیا...: ہیب۔ میہ نش کیا چُھ نیران؟}\n7.\\tمگر وۅنۍ چُھس میہ تنگ کورمُت: ژے کٔر میون سورے صحبت۔\n8. تہٕ ژے چُھہ میہ گُرِ سٍتـ̡ بٔرِتھ {یُس} گواہ چُھہ {میٲنس خلاف} تہٕ میانہِ لۅتہٕ سٍتـ̡ چُھہ میٲنس بُتھِس گوٲہی دِوان۔\n9.\\tسُہ چُھس پننِس قہر سٍتـ̡ ژٔٹِتھ ژٔٹِتھ دِوان، یُس میہ سٍتـ̡ نفرت کران چُھہ: سُہ چُھہ میہ دندٕ سٍتـ̡ دندٕ دِوان۔ میون دُشمن چھہ میہ کُن نظر تیز کران۔\n10.\\tتِمو چُھہ میہ پنہٕ نِس ٲسِس سٍتـ̡ دِژمُت۔ تِمو چھُ میہ گالِس پیٹھ ملامت کٔرِتھ تھپھ کٔرمٕژ۔ تِمو چھِ پانس میہ خلاف جمع کٔرۍمٕتۍ۔\n11. خداین دیت میہ بدکارن نِش حوالہٕ، تہٕ کوٚرُن میہ بدکارن ہٕندِس اتھس مَنٛز۔ {ہاتھ...: ہیب۔ میہ چھہ بند کٔرتھ}\n12.\\tبہٕ اوسُس آرام سان مگر تٔمۍ پھُٹرٲو میہ پھُٹراوُن: تٔمۍ تہِ رٔٹِتھ تہٕ ژٔٹِتھ تہٕ لٔگِتھ دِژُن میہ پننہِ نشانہٕ خٲطرٕ۔\n13.\\tتٔمۍ سٕندِ تیر انداز چھِ میہ اندۍ گٔژھان، سُہ چھُ میٲنۍ لگام ژٔٹِتھ ژٔٹِتھ تہٕ دِوان نہٕ۔ سہ تروو میون گال زمینس پیٹھ۔\n14.\\tسُہ چُھس میہ پھُٹراوان تہٕ سُہ چُھ میہ پیٹھ دیو ہٕندۍ پٲٹھۍ۔\n15.\\tمیہ چُھس پننِس مسلس پیٹھ بۄٹہٕ پلو سِیومُت، تہٕ کورُن پنُن سینگ گردِ منز ناپاک۔\n16.\\tمیون بُتھ چھہ روُن سٍتۍ بدبودار تہٕ میٲنس ٹٲرِس پیٹھ چھُ موتُک سایہ۔\n17.\\tمیانہِ اتھس منز چھہ نہ {کُنہِ} ناانصافی مۅکھہٕ: تہِ چھُ میٲنۍ دُعا {خالص}۔\n18.\\tاے زمین، میٲنۍ خونس تہٕ میانہِ فریاد گژھہِ نہٕ کانہہ جاے۔\n19.\\tتہِ وُچھِو، میون گواہ {چُھ} آسمانس منز، تہٕ میون ریکارڈ {چُھ} تھزرس پیٹھ۔ {پیٹھ: ہیب۔ تھدٮ۪ن جاین منز}\n20. میانۍ یار چھہِ میہ حقارت کران: {مگر} میانہِ اچھ چھیہ خدایس کُن {اشہ وسان}۔ {میہ کٔرِو حقارت کٔرِتھ: ہیب۔ میہ چھہ میہ کُنہِ\n21.\\tاے یُس انسان خدایہ سٍتـ̡ کُنہِ انسانس سٍتـ̡ دُعا کٔرِتھ، یێلہِ پٲٹھـ̡ انسان پننِس ہمساین سٍتـ̡ دُعا کٔرِتھ! {ہمسایہ: یا، دوس}\n22.\\tییلہ کینہہ ؤری یِن، تیلہِ گژھہِ بہٕ تتھ وتہِ {ییتہِ} بہٕ واپس۔ {کینہہ ...: ہیب۔ ؤری تعداد}","1.\\tمیون دم چھہ کرپٹ، میون دۅہ چھہ ختم، قبر چھیہ میانہِ خاطرہ تیار۔ {شاہ...: یا، روح چُھ خرچ گومُت}\n2. {کیا اَتہِ} چھَنہٕ مےٚ سٍتۍ طنز کَرنہٕ آمُت؟ تہٕ کیا میانہِ أچھ چھے نہٕ تِمن ہٕندِس اشتعالس منز جٲری؟ {جٲری: ہیب۔ لاج}\n3.\\tوۅنۍ لوٚگ، میہ تھاو پانس سیتۍ ضمانتس منز۔ کُس {چھُ} سُہ {یُس} مےٚ سۭتۍ اَتھٕ مارِ؟\n4.\\tکیازِ ژے چھُکھ تِہُند دِل سمجھنہٕ نِش ژوٗرمُت، تێمہِ مۄکھٕ کٔرِو نہٕ تِمن ہٕندِس دِلس سٍتـ̡ تھپھ کٔرِتھ۔\n5.\\tیُس پننین دوستن ہنز خوشامد کرِ، سہ گژھہِ پننین شُرین ہٕنزِ نظر تہِ ناکام سپدِ۔\n6. تٔمۍ بنوو مے تہِ لُکن ہُند ضمنی کلام ۔ تہٕ امہ برونہہ اوسس بہٕ ٹیبریٹ ہٕندۍ پٲٹھۍ۔ {برونہہ: یا، تمن برونہہ}\n7.\\tمیانہِ اچھ تہِ چھیہ غم کنۍ ژھایہ تہ میانہِ سٲری ارکان چھہِ ژھایہِ ہٕندۍ پٲٹھۍ۔ {میٲنۍ ارکان: یا، میٲنۍ خیالات}\n8.\\tاتھ پیٹھ گژھہِ سیدِ سیود انسان حیران تہ بے گناہ کرِ منافقس خلاف پانس ہنگامہ آرایی کرنہ۔\n9. نیک تہِ گژھہِ پننہِ وتہِ پیٹھ تھپھ کٔرِتھ، تہٕ یُس صاف اتھہٕ آسہِ سُہ گژھہِ مضبوط تہٕ مضبوط۔ {be...: Heb. طاقت کٔرِو شٲمِل}\n10.\\tمگر یێلہِ تۅہہ سارِوٕے سٍتـ̡ واپس، تہٕ یێلہِ وُنـ̡ یێلہِ بہٕ چُھس نہٕ ژے منزٕ {اَکہ} دانا {انسان} لبنہٕ یِوان۔\n11.\\tمیانہِ دۅہ گٔیہ پتھ کال، میون مقصد چھہ ختم گومت، {حتیٰ کہ} میانہِ دِلکۍ خیال۔ {خیالات: ہیب۔ ملکیت }\n12.\\tیم چھہِ رٲژ دۅہس منز بدلاوان: گاش چھہ انہِ گٹہِ کنۍ ژھوٚٹ۔ {مختصر: ہیب۔ نزدیک}\n13.\\tاگر میہ انتظار کرُن، قبر چھیہ میون مکانہ: میہ چھہ انہِ گٹہِ منز پنُن بستر۔\n14.\\tمیہ چھہ کرپشنس وونمُت، ژے چھکھ میون مول تہ میانہِ بینہِ۔ {ونان: ہیب۔ روُن، یا، بلاو}\n15. تہٕ وۅنۍ کتہِ چھیہ میٲنۍ وۅمید ؟ یوٚت تام میانہِ وۅمید چھِ، یہ کُس وُچھِ؟\n16.\\tتِم گژھن کھۅنہِ ہٕندِس سلاخس کُن، ییلہ {سانہ} رٔلِتھ رٔٹِتھ رٔلِتھ رٔٹِتھ رٔٹِتھ۔","1.\\tاَمہ پتہٕ دیت بلداد شُہیت سُند جواب تہٕ وونُن\n2.\\tکتِس کالس لگہِ تۅہہ کُنہِ لفظس ختم کٔرِتھ؟ مارک، تہٕ پتہٕ کرو أسۍ کتھ۔\n3. اسہِ کیازِ چھہِ درندہ ماننہ یوان، {تہٕ} تہٕ تۅہہِ نظرِ منز بدنام ماننہٕ آمٕتۍ؟\n4. سُہ چُھ پننِس شَرارتہٕ سٍتـ̡ ژٔٹِتھ ژٔٹِتھ: کیا ژےٚ خٲطرٕ گژھہٕ زمین تراونہٕ؟ تہٕ کٔنہِ پننہِ جایہِ نِش ہٹاونہٕ؟ {پانہٕ: ہیب۔ تٔمۍ سُند روح}\n5. آ، بدکار سُند گاش گژھہِ ژھیتہٕ تہٕ تٔمۍ سٕندِ نارٕچ چنگاری گژھہِ نہٕ چمکٕنۍ۔\n6.\\tگاش گژھہِ تٔمۍ سٕندِس خیمَس مَنٛز تاریک تہٕ تٔمۍ سٕنز شمع یِیہِ أمِس سٍتـ̡ ژھیتہٕ کرنہٕ۔ {موم بتی: یا، چراغ}\n7.\\tتٔمۍ سٕندِس طاقتٕکۍ قدم گژھن دباونہٕ یِن، تہٕ تٔمۍ سُند پنُن مشورٕ گژھہِ أمِس دِنہٕ۔\n8.\\tتکیازِ سُہ چُھ پننیو قدمو سٍتـ̡ جالس منز تراونہٕ یوان، تہٕ سُہ چُھ جالس پیٹھ پکان۔\n9.\\tگِنِس کھورِ رٔٹِتھ تہٕ ڈاکو گژھہِ أمِس خٕلاف غٲلب۔\n10.\\tجال {is} آو أمِس خٲطرٕ زمینس منز تراونہٕ، تہٕ وتہِ منز چُھ أمِس خٲطرٕ اکھ جال۔ {لیڈ: ہیب۔ پوشیدٕ}\n11.\\tدہشت کرِ أمِس پریتھ طرفہٕ خوفزدہ تہٕ دِیہِ أمِس کھورِ کھٔسِتھ۔ {ڈرایو: ہیب۔ بکھرُن}\n12. تٔمۍ سُند طاقت گژھہِ فاقہٕ کٔرِتھ تہٕ تباہی گژھہِ تٔمِس سٍتـ̡ تیار۔\n13.\\tیہِ گژھہِ پننہِ ژمہِ ہٕندِس طاقتس کھٮ۪نہٕ: {حتیٰ کہ} موتُک گۄڈنیُک زامُت تہِ کرِ تٔمۍ سٕندِس طاقتس کھٮ۪وان۔ {طاقت: ہیب۔ بارز}\n14. تٔمۍ سُند اعتماد گژھہِ تٔمۍ سٕندِس خیمہ منزٕ ختم کرنہٕ، تہٕ سُہ گژھہِ تس دہشت کِس بادشاہس نِش اننہٕ۔\n15.\\tیہ روزِ تٔمۍ سٕندِس خیمہ خانس مَنٛز، کیازِ {یہ} چُھہ نہٕ تٔمۍ سٕندِس بستی منز کانہہ تہِ: گندھ گژھہِ تٔمۍ سٕندِس بستی منز پھٔہلِتھ۔\n16.\\tتٔمۍ سٕندِ موٗل گژھن بۅنہ کنہِ خشک کرنہٕ تہٕ ہیرِ کُن یِن تٔمۍ سٕنز لٔر ژٹنہٕ۔\n17.\\tتٔمۍ سُند یاداشت گژھہِ زمینہِ سٍتـ̡ ختم تہٕ سڑکہِ منز گژھہِ نہٕ أمِس کانہہ ناو۔\n18.\\tسُہ گژھہِ گاشہٕ سٍتـ̡ اندھیرِس مَنٛز کڑنہٕ یُن، تہٕ دُنیاہس نِش کڈنہٕ یُن۔ {یہ...: ہیب۔ تِم کرِ أمِس چلاون}\n19. أمِس آسہِ نہٕ پننِس لُکن مَنٛز نیچو تہٕ نہ بابتٕر تہٕ نہ روزِ تٔمِس مکانس مَنٛز کانہہ تہِ باقی۔\n20.\\tیِم یِم أمِس پَتہٕ یِنہٕ وٲلِس دۅہہٕ یِمن ہٕندِس دۅہہٕ سٍتـ̡ حٲران گٔیہِ، یِتھٕ پٲٹھۍ یِم برونہہ کُن گٔیہِ۔ {گٔیہِ...: یا، روزان أمِس سٍتۍ} {ٲس...: ہیب۔ تھپھ کٔرِتھ ہارر}\n21.\\tیِتھۍ چھِ بدکارن ہٕندِ مکانہٕ، تہٕ یۅہے جاے چھے یُس خدایہ سُند زانان چُھہ نہٕ۔","1. اَمہِ پتہٕ دِژ ایوب جواب تہٕ وونُن،\n2. ژیہ کوتاہ تام میانہِ روح ژٔٹِتھ تہٕ لفظو سٍتۍ پھُٹراوُن؟\n3.\\tیِمن دَہن لٹہِ کٔر ژے میہ ملامت کٔرِتھ: ژیہ چھُنہٕ شرم زِ ژے چھِو میانہِ خٲطرٕ پنُن پان عجیب بناوان۔ {بناو...: یا کٔرِو میہ خلاف سختی کرُن}\n4.\\tتہِ گژھہِ پزۍ پاٹھۍ غلطی کرمژ، میون غلطی چھہ پانس سیتۍ روزان۔\n5.\\tاگر پزۍ پاٹھۍ ژیہ میانہِ خلاف پانس بٔرتھ، تہٕ میانہِ خلاف میانہِ ملامت کٔرِو:\n6.\\tوۅنۍ زان زِ خداین چھُ میہ پتھر کٔرِتھ تہٕ کورُن میہ پننہِ جالہ سٍتـ̡ گھیرِ۔\n7.\\tوچھ، بہٕ چُھس غلط کِنۍ فریاد دِوان، مگر بہٕ چُھس نہٕ بوزنہٕ یوان: بہٕ چُھس بَڑِ وُچھان، مگر {اَتہِ} چُھنہٕ کانہہ فیصلہٕ۔ {غلط: یا، تشدد}\n8.\\tتٔمۍ چُھس میانہِ وتہِ تار لگٲومٕژ یُس بہٕ ہیوٚک نہٕ نیرِتھ، تہٕ تٔمۍ کٔر میانین وتن مَنٛز انہِ گوٚٹ۔\n9.\\tتٔمۍ کٔر میہ میٲنۍ شان نِش نِش تہٕ تاج تُلُن میٲنس کلہٕ پیٹھ۔\n10.\\tتٔمۍ کٔر میہ پریتھ طرفہٕ تباہ تہٕ بہٕ گۆو تہٕ میٲنۍ وۅمید چھیہ کُلِس ہٕندۍ پٲٹھۍ۔\n11.\\tتٔمۍ تہِ چُھس میہ خلاف پنُن قہر دِژمُت، تہٕ سُہ چُھس پانس سٍتـ̡ پنہٕ نـ̡ دُشمن منزٕ اکھ مانان۔\n12. تٔمۍ سُند فوج آو اَکہٕ وٹہٕ، تہٕ کٔرِن میٲنس خیمہ اندۍ ڈیرٕ۔\n13.\\tتٔمۍ کٔر میانین بٲے میہ نِش دور، تہٕ میٲنۍ وٲقف چھِ پٔزۍ پٲٹھۍ میہ نِش دور۔\n14. میٲنۍ رشتہٕ دار گٔیہِ ناکام، تہٕ میٛٲنۍ مانوس یارو گٔیہِ مے مٔشِد۔\n15.\\tیِم میانِس گرس منز روزان چھِ، تہٕ میانہِ دٲرۍ، چھِس میہ اکھ اجنبی مانان: بہٕ چُھس تِہندِ نظرِ منز اکھ اجنبی ۔\n16.\\tمیہ بُلوو پنُن خادم، تہٕ تٔمۍ دِژ نہٕ کانہہ جواب۔ میہ کٔر أمس پننہ ٲسس سیتۍ گُزٲر۔\n17.\\tمیانہِ زنانہِ ہٕندِ خٲطرٕ چھُ میون شاہ عجیب، حالانکہ بہٕ اوسُس شُرین ہٕندِ خٲطرٕ پننہ جسمہٕ خٲطرٕ التجا کٔرمٕژ۔ {میٲنۍ ...: ہیب۔ میون پیٹ}\n18.\\tآ، لۅکٹۍ شُرۍ ٲسۍ میہ حقارت کران۔ بہٕ ووٚتھ، تہٕ تِمو کٔر میٲنس خلاف کتھ۔ {نوجوان...: یا، بدکار}\n19.\\tمیانین سارِنٕے باطنی یارن کٔر میہ نفرت: تہٕ یِمن میہ محبت کران چھِ، تم چھہِ میہ خلاف بٔنِتھ۔ {میانۍ...: ہیب۔ دی مین آف ماے سیکرٹ}\n20.\\tمیون اڈجہ چھہ میٲنس مسلس تہ مازس سیتۍ ژٹان تہ میہ چھہ پننین دندن ہندِ کھالہِ سیتۍ ژلان۔ {تہٕ کُن: یا، یتھ کٔن}\n21.\\tمیہ پیٹھ رحم کرُن، اے میٲنۍ دوستو۔ تکیازِ خدایہ سند اتھہ چھہ میہ اتھہ روٚٹمت۔\n22.\\tژیہ کیازِ چھکھ میہ خدایہ سٍتـ̡ ستاوان، تہٕ میانہِ مازس سٍتـ̡ چُھہ نہٕ مطمئن؟\n23.\\tکاش میٲنۍ کتھ آسہ وۅنۍ لیکھنہٕ آمٕژ! اوے زِ تم ٲسۍ اکس کتابہِ منز چھاپنہٕ آمتۍ۔ {اوہ...: ہیب۔ کُس دِیہِ وغیرہ}\n24.\\tزِ تِم آیہ شیشتٕرِ قلمہٕ سٍتۍ کھٔنِتھ تہٕ کٔنہِ ہمیشہٕ خٲطرٕ کٔرِتھ!\n25.\\tکیازِ بہٕ چُھس پتاہ زِ میون نجات دِنہٕ وول چُھ زندٕ، تہٕ {یہ} سُہ گژھہِ پٔتمہِ دۅہہٕ زمینس پیٹھ کھڑا روزُن:\n26.\\tتہٕ {اگرچہ} میانہِ ژمہِ {کیمہ} یِہ {جسم} تباہ کٔرِتھ، توتہِ چھُس بہٕ پننِس مازس منز خدایہ وُچھان: {تہٕ...: یا، ییلہ بہٕ بیدار سپدِ، یودوَے یہ جسم تباہ گژھہِ، توتہِ میانہِ مازٕ منز}\n27. یُس بہٕ پانس وُچھِتھ تہٕ میٲنۍ أچھ وُچھِن، تہٕ بییِس نہٕ۔ {اگرچہ} میانہِ لگام چھیہ پانس اندر کھیوان۔ {بیاکھ: ہیب۔ اکھ اجنبی} {اگرچہ...: یا، میانۍ لگام چھیہ میہ اندر شدید خواہشس سٍتۍ کھیوان (تمہِ دۅہہک خاطرہ} {اندر...: ہیب۔ میٲنس سینس منز}\n28.\\tمگر تۅہہ پزِ ونُن، اسہِ کیازِ چھہِ تس ستاوان، یہ وچھتھ زِ میہ منز چھہ امیک مول میلان۔ {وُچھِو...: یا، تہٕ میٲنِس مَنٛز کُس موٗل چھُ لَبنہٕ یِوان؟}\n29.\\tتلوارِ نشہِ گژھہِ کھوژُن: تکیازِ تلوارِ ہُند عذاب دِنہٕ یُن، یُتھ زِ تۅہہِ گژھہِ زٲنِتھ زِ اکھ فیصلہٕ چھُ۔","1.\\tاَمہِ پتہٕ دِیُت زوفر نامتھِس جواب تہٕ وونُن،\n2.\\tلہذا چھہ میانہِ خیالہ میہ جواب دِنس پیٹھ مجبور کران، تہ {امہِ} خاطرہ چھُس بہٕ جلدی کران۔ {بہٕ چُھس بناوان...: ہیب۔ میٲنۍ جلدی چھیہ میہ منز}\n3.\\tمیہ بوز پننہِ ملامت ہُند چیک تہٕ میانہِ فہم ہُند روح چھُ میہ جواب دِنُک سبب بنان۔\n4.\\tژیہ چھکھ یہ پرانہِ زمانہ پتاہ، ییلہ انسان زمینس پیٹھ تھاونہ آمت اوس،\n5.\\tزِ بدکار سنز فتح چھیہ مختصر تہ منافق سنز خوشی چھیہ کینژس کالس تہِ؟ {مختصر: ہیب۔ نزدیکی پیٹھ}\n6. یودوَے تٔمۍ سُند کلہٕ آسمانس تام کھسِتھ تہٕ تٔمۍ سُند کلہٕ چھُ اوٚبرن تام واتان۔ {اوبر: ہیب۔ کلاؤڈ}\n7. {توتہِ} سُہ گژھہِ ہمیشہٕ خٲطرٕ پننہِ گُرِ ہٕندۍ پٲٹھۍ، یِمو أمِس وُچھمُت چھُ تِم وَنُن زِ سُہ کتہِ چُھہ؟\n8.\\tسُہ گژھہِ خوابکۍ پٲٹھۍ، تہٕ ییہ نہ لبنہٕ: آ، سہ گژھہِ رٲژ ہٕندِس وژنس منز ژلنہٕ۔\n9.\\tاچھ تہِ یُس وُچھمُت آسہِ سُہ تہِ وُچھِتھ نہٕ وُچھُن؛ نہ گژھہِ تس وۅنۍ کانہہ جاے وچھان۔\n10. تٔمۍ سٕندِ شُرۍ گژھن غریبن خوش کرنٕچ کوٗشش، تہٕ تٔمۍ سٕندِ اتھہٕ کرِ تِہُند مال واپس۔ {تٔمۍ سٕندِ شُرۍ...: یا، غریب کرِ پننین شُرین پیٹھ ظلم}\n11. تٔمۍ سٕنزِ أڈجہِ چھے جوانی ہٕندِس گۅنہٕ سٍتـ̡ بٔرِتھ، یُس أمِس سٍتـ̡ رٔٹِتھ گٔژھِتھ روزِ۔\n12.\\tیێلہِ زَن بد کاری آسہِ ٲسِس مٔدٕر، {اگرچہ} سُہ چھُ سُہ پننہِ زبانہِ تل ژوٗرِ تھاوان۔\n13.\\t{اگرچہ} سُہ ترٲوِتھ تہٕ تراوُن نہٕ۔ مگر یہ تھوو وُنہِ تہِ پننس ٲسس منز:{اندر...: ہیب۔ تٔمۍ سٕنٛدس تالس منٛز}\n14.\\t{توتہِ} چھُ تٔمۍ سٕندِس ماز مَنٛز پھیُراونہٕ آمُت، {یہِ} چھُ أمِس اندر آسُن ہُند گال۔\n15.\\tتٔمۍ چُھ دولت نِنہٕ آمُت، تہٕ سُہ دِیہِ دُبارٕ اُلٹی: خدا کٔرِن تِم پننہِ یٔڈ منزٕ کٔڈِتھ۔\n16.\\tسُہ چُھس زہر چوسُن: سُہ مارِ أمِس زبردست۔\n17. سُہ وُچھِ نہٕ دریاو، سٔہلاب، ماچھ تہٕ تھنہٕ ہٕندِ نالہٕ۔ {سیلاب...: یا، سٹریمنگ بروکس}\n18.\\tیُس أمِس محنت کٔرِتھ سُہ کرِ سُہ بحال تہٕ سُہ کرِ نہٕ نِنہٕ: سُہ کرِ نہٕ تٔمِس مُطٲبِق تہٕ سُہ گژھِ نہٕ خۅش سپدُن۔ {امس...: ہیب۔ تٔمۍ سٕنٛدِ تبادلُک مادٕ}\n19.\\tکیازِ تٔمۍ چھُ غریبن پیٹھ ظلم کورمُت تہٕ غریبن ترٲومُت۔ {کیازِ} تٔمۍ چھُ تشددٕ سان اکھ مکانہٕ نِش نِمُت یُس نہٕ تٔمۍ بنوومُت اوس۔ {مظلوم: ہیب۔ کرشڈ}\n20.\\tیقینا گژھہِ نہ تس پننِس یٔڈ منز خاموشی محسوس، سُہ گژھِ نہٕ تتھ سٍتۍ نجات دِنہٕ یُس تس یژھان۔ {محسوس: ہیب۔ زانہ}\n21. تٔمۍ سُند ماز گژھہِ نہٕ کانہہ تہِ باقی۔ لہذا گژھ نہٕ کانٛہہ تہِ انسان پنُن مال ژھانڈنہٕ۔ {کانٛہہ تہِ...: یا، تٔمۍ سٕنٛدِ مازٕ خٲطرٕ گژھِ نہٕ کانٛہہ تہِ باقٕے}\n22.\\tپننہِ کٲفی ہٕندِس پورٕ سٍتـ̡ آسہِ سُہ مُشکِلَس مَنٛز: بدکارن ہُند پرٮ۪تھ کانہہ اتھہٕ گژھہِ أمِس پیٹھ۔ {بدکار: یا، پریشان}\n23.\\t{ییلہِ} سُہ پنُن یٔڈ بٔرِتھ آسہِ، {خدایہ} دِیہِ أمِس پیٹھ پنُن قہر تہٕ کھٮ۪نہٕ وِزِ دِیہِ أمِس پیٹھ برسان۔\n24.\\tسُہ ژلہِ شِشتٕرِ ہتھیار نِش ژلُن، {تہٕ} سٹیلٕچ کمان دِیہِ أمِس ٹاس دِنہٕ۔\n25.\\tیہ چھہ کڈنہ یوان تہ جسمہ منزہ نیبر نیران۔ آ، چمکدار تلوار چھیہ امۍ سنزِ گالہ منزہ نیران: تس پیٹھ چھہ دہشت {] ۔\n26.\\tسارِنٕے انہِ گٹہِ گژھہِ تٔمۍ سٕندِس خفیہ مقامس مَنٛز ژوٗرِ روزُن: یُس نار نہٕ دِنہٕ ییہِ أمِس دِنہٕ۔ سُہ گژھِ تٔمِس سٍتۍ بیمار یُس تٔمۍ سٕندِس خیمہ منز باقٕے آسہِ۔\n27.\\tآسمانس کرِ تٔمۍ سٕنزِ بدکاری ظٲہر۔ تہٕ زمین گژھہِ أمِس خٕلاف تھوٚد۔\n28.\\tتٔمۍ سٕندِس گرس ہُند اضافہٕ گژھہِ ختم تہٕ تٔمۍ سُند مال گژھہِ تٔمۍ سٕندِس قہر ہٕندِس دۅہس منز وسان ۔\n29. یہِ چُھ خدایہ سٕندِ طرفہٕ أکِس بدکار انسان سُند حصہٕ، تہٕ خدایہ سٕندِ طرفہٕ أمِس مُقرر کرنہٕ آمُت وراثت۔ {مُقرر...: ہیب۔ خدایہ سندِ طرفہٕ تٔمۍ سٕندِ حکمُک }","1. مگر ایوب دیت جواب تہٕ وونُن،\n2.\\tمیون کلام بوزو محنت سان تہ یہ گژھہِ چانۍ تسلی بخش۔\n3. بہٕ کٔرِو بہٕ کَتھ کَرٕن؛ تہٕ تمہ پتہ کٔر میہ کتھ، مذاق۔\n4. یوٚت تام میانہِ متعلق، {چھا} میٲنۍ شکایت انسانس سٍتۍ؟ تہٕ اگر یہِ آسہِ، تیلہِ کیازِ گژھہِ نہٕ میون روح پریشان؟ {پریشان: ہیب۔ ژھوٚٹ؟}\n5. میہ کٔرِو نشان زد تہٕ حیران گژھُن، تہٕ تھووُن {پنُن} اتھہٕ {پنٕنِس} ٲسس پیٹھ۔ {مارک...: ہیب۔ میہ کُن وچھ}\n6.\\tییلہ تہِ میہ یاد چھہ گژھان تہ میہ چھہ کھوژان تہ لرزہ لٔگتھ چھہ میٲنس مازس تھپھ کران۔\n7.\\tبدکار کیازِ چھہِ زندہ، بُزرگ سپدان، آ، طاقتس منز چھہِ طاقتور؟\n8.\\tتِہُند بیول چُھ تِمن سٍتـ̡ تہندِس نظرس سٍتـ̡ قایم سپدان تہٕ تِہٕندِس اولادس سٍتـ̡ چُھہ تِمن ہٕ\n9. تِہُند گرٕ چُھہ خوفہٕ نِش محفوظ، تہٕ نہ چُھہ تِمن پیٹھ خدایہِ سٕنز لٔرۍ۔ {محفوظ...: ہیب۔ امن}\n10.\\tتِہُند بیل چُھہ جنس تہٕ ناکام سپدان۔ تِہٕنزِ گاو چھے بَچھرٕ کٔرِتھ، تہٕ کٔرِتھ چھُنہٕ پنُن بَچھرٕ دِوان۔\n11.\\tتِم چھِ پَنٕنـ̡ لۄکٹـ̡ پٲٹھـ̡ پٲٹھـ̡ نژان تہٕ تِہٕندِس شُرِ نژان۔\n12.\\tتِم چھِ ٹمبرل تہٕ ہارپ رٹان تہٕ اعضاء چہِ آوازِ پیٹھ خوش گژھان۔\n13. تِم چھِ پنٕنۍ دۅہ دولتس مَنٛز گُزاران، تہٕ أکِس لمحس مَنٛز قبرس کُن گُزاران۔ {دولتس منز: یا، مرتھس منز}\n14. تێمہِ کِنۍ چھِ تِم خدایہِ سٍتـ̡ ونان زِ اسہِ نِش گژھ دور۔ تکیازِ أسۍ چھِنہٕ چانہِ طریقن ہُند علم یژھان۔\n15.\\tاللہ تعالیٰ کیا چھہ زِ اسہِ پزِ تسنز خدمت کرُن؟ تہٕ اگر أسۍ أمِس دُعا کٔرِو، اسہِ کیا فٲیدٕ گژھہِ؟\n16.\\tتِہُند خیر چُھنہٕ تِہندِس اتھس منز: بدکارن ہُند مشورٕ چُھ میانہِ نِش دور۔\n17.\\tبدکار سٕنز شَم کوتاہ چُھ ژھیوراونہٕ آمُت! تہٕ {کٲژاہ لٹہِ} چُھ تِمن پیٹھ تِہنز تباہی سپدان! {خدایہ} چھہ پننس غصس منز غم بٲگراوان۔ {موم بتی: یا، چراغ}\n18.\\tتِم چھِ ہوہس برونہہ کُن کُنہِ {کیریتھ: ہیب۔ ژوٗرِ}\n19.\\tخدا چُھ پننین بچن خٲطرٕ پنُن بدکار تراوان: سُہ چُھ أمِس بدلہٕ دِوان، تہٕ سُہ گژھہِ پتاہ۔ {تٔمۍ سٕنز بدکاری: یعنی تٔمۍ سٕنزِ بدکٲری ہُند سزا}\n20. تٔمۍ سٕنزِ أچھ وُچھن تٔمۍ سُند تباہی تہٕ سُہ گژھہِ خداتعالیٰ سٕندِ قہر سٍتـ̡ چُھ۔\n21.\\tتس پَتہٕ کُنہِ لُطفہٕ خٲطرٕ چُھ أمِس گَرَس مَنٛز، یێلہِ تٔمِس ریتن ہُند تعداد ژٹنہٕ ییہِ۔\n22.\\tکیا خدایس علم ہیچھناوُن؟ وُچھِتھ چُھ سُہ تِمن ہُند فیصلہ کران یِم تھدِ چھِ۔\n23.\\tاکھ چھہ پورٕ طاقتہٕ سٍتـ̡ مران تہٕ پوٗرٕ پٲٹھـ̡ آسُن تہٕ خاموشی سٍتـ̡ آسان۔ {امس...: ہیب۔ تٔمۍ سُند سٮ۪ٹھاہ طاقت، یا تٔمۍ سٕندِس کمالُک طاقت}\n24.\\tتٔمۍ سٕندِس سینس چھُ دۄدٕ سٍتۍ بٔرِتھ تہٕ أڈجہِ چھِ میرو سٍتۍ نم گٔمٕژ۔ {سینس: یا، دۄدٕ ڈل}\n25.\\tتہٕ بیاکھ چُھ پننہِ روحٕچ تلخی منز مران تہٕ زانہہ تہِ چُھ نہٕ خۅش سپدان۔\n26.\\tتِم گژھن گردِ منز ہِوُے لٔگِتھ تہٕ کٔرِن تِمن ؤلِتھ۔\n27.\\tوچھ، بہٕ چھُس تُہند خیال تہٕ تِمن آلاتن ہُند پتاہ یِم ژے میانہِ خلاف غلط تصور کران چھِ۔\n28.\\tتُہۍ چھِو ونان زِ شہزادٕ سُند گرٕ کتہِ چھُ؟ تہٕ بدکارن ہٕنز روزنٕچ جاے کتہِ چھِ؟ {رہائش...: ہیب۔ خیمہ خیمہ }\n29.\\tکیا تۅہہ پرژھ نہٕ تمن وتہِ نیران؟ تہٕ کیا تُہۍ چھِو نہٕ تِمن ہٕندِ نشانہٕ پتہٕ،\n30. زِ بدکار چُھ تباہی ہٕندِس دۅہس تام محفوظ؟ تِم یِن قہر کِس دۅہس تام اننہٕ۔ {شرارت: ہیب۔ شرارت}\n31.\\tکُس کرِ پننِس بُتھِس تام وتھ ہُند اعلان؟ تہٕ کُس کرِ أمِس بدلہٕ دِنہٕ؟\n32. توتہِ یِیہِ قبرس مَنٛز اننہٕ، تہٕ روزِ قبرس مَنٛز۔ {قبر: ہیب۔ قبر} {باقی ...: Heb. انبارس منز وچھو}\n33.\\tوادی ہٕندِس کۅکرِ ہٕندِ خٲطرٕ میٹھُر تہٕ پرٮ۪تھ کانہہ انسان گژھہِ أمِس پَتہٕ لٔگِتھ، یِتھٕ کٔنۍ أمِس برونہہ کُن بے شمار چھِ۔\n34. تیلہِ کِتھہ پٲٹھـ̡ چُھہ میہ بیکار تسلی دِوان، وُچھِتھ چُھہ تہندِس جوابس منز اپُز باقی؟ {اپز: ہیب۔ خلاف ورزی ؟}","1.\\tاَمہ پتہٕ دِژ الیفاز تیمانِین جواب تہٕ وونُن،\n2. کیا انسان ہیکہِ خدایہِ سٕندِ خٲطرٕ فٲیدٕ مند ٲسِتھ، یُس عقلمند آسہِ، سُہ ہیکہِ پانس خٲطرٕ فٲیدٕ مند ٲسِتھ؟ {یتھ کٔنۍ سُہ...: یا، اگر سُہ نفع بخش آسہِ، کیا تٔمۍ سٕنٛز اصل کامیٲبی چھا اتھ پیٹھ منحصر؟}\n3. کیا یہ چھا خدایہ سٕندِ خٲطرٕ کانہہ خوشی زِ ژٕ چُھکھ نیک ؟ یا {یہ} چُھہ {أمِس} حٲصِل کٔرِتھ، زِ ژے کٔرِو پنٕنۍ وتہٕ کٲمل؟\n4.\\tکیا سُہ دِیہ تۅہہِ ہٕندِ خوفہٕ سٍتـ̡ ملامت کرنہٕ؟ کیا سُہ ژےٚ سٍتـ̡ ژے سٍتـ̡ فٲصلس مَنٛز د\n5. {کیا چُھ} چُھہ نہٕ تُہند بدکار بٔڈ ؟ تہٕ تہنز بدکاری لامحدود؟\n6.\\tکیازِ ژے چھُکھ پننِس بٲیِس سٍتـ̡ بیکار عہد کورمُت، تہٕ کٔرِکھ ننگہٕ تِہٕندِس پلوس کٔڈِتھ۔ {ننگہ...: ہیب۔ ننگہِ ہند پلو}\n7. ژے چُھکھ نہٕ تھکہٕ مٕتِس چنہٕ خٲطرٕ آب دِژمُت، تہٕ ژے چُھکھ فاقہٕ مَنٛز روٹی رُکٲومٕژ۔\n8.\\tمگر طاقتور انسانس ٲس زمین۔ تہٕ عزت مآب انسان اوس اتھ منز روزان۔ {mighty...: Heb. مین آف آرم} {معزز ...: ہیب۔ نامور ، یا، شکلہٕ خٲطرٕ قبول کرنہٕ}\n9.\\tژے سوزۍ بیواہ خٲلی تہٕ بے باپَن ہٕندِ ہتھیار چھِکھ پھُٹمٕتۍ۔\n10.\\tتێلہِ چُھہ ژۅہہِ اندۍ پکھۍ پھیُر تہٕ اچانک خوف چُھہ ژیہ پریشان کران۔\n11.\\tیا انہِ گٹہِ، {یُس} ژیہ نہ وچھِتھ ہیکو۔ تہٕ آبٕچ کثرت چھِ ژےٚ ؤلِتھ۔\n12. کیا خدایہ چُھہ نہٕ آسمانس مَنٛز؟ تہٕ وُچھِو ستارن ہُند تھزر، تِم کوتاہ تھزر! {ستارن ہند تھزر: ہیب۔ ستارن ہند سربراہ}\n13. تہٕ تُہۍ چھِو ونان زِ خدایہ کِتھ کٔنۍ چُھ پتہٕ؟ کیا سُہ ہیکہٕ سیاہ اوبرٕ سۭتۍ فیصلہ کٔرتھ؟ {کتھہ پاٹھۍ: یا، کیا}\n14.\\tگٔنـ̡ اوٚبرٕ چُھہ أمِس سٍتـ̡ پردٕ ، یُس نہٕ وُچھان چُھہ ۔ تہٕ سُہ چُھ جنتٕکِس چکرَس مَنٛز پکان ۔\n15.\\tکیا ژے چھکھ پرانہِ وتہِ نشان زد کٔرمٕژ یُس بدکار انسان پکان چھُ؟\n16.\\tیُس زمانہٕ سٍتـ̡ ژٹنہٕ آمُت اوس، یێمِچ بُنیاد ٲس سٔہلاب سٍتـ̡ ژٔٹِتھ: {کُس...: حب۔ تہندِس بنیادس پیٹھ آو اکھ سٔلاب تراونہٕ}\n17.\\tیُس خدایس ووٚنمُت زِ اسہِ نِش گژھ تہٕ خدایہ کیا ہیکہِ تِمن خٲطرٕ کٔرِتھ؟ {for: or, to}\n18.\\tتوتہِ کٔر تِمن ہٕندِس گَرٕ سٍتـ̡ بٔرِتھ، مگر بدکارن ہُند مشورٕ چُھہ میہ نِش دور۔\n19.\\tنیک چھِ وُچھان تہٕ خۅش گژھان: تہٕ معصوم چھِ تِمن حقارت کٔرِتھ اسان۔\n20.\\tییلہ زن سانہِ مادہ ژٹنہ یوان چھہ نہ، مگر یمن ہند باقیات چھہ نار کھیوان۔ {مادہ: یا، جائیداد} {باقیات...: یا، تہنز عظمت}\n21. وۅنۍ کرو تس سٍتـ̡ پانس سٍتـ̡ وٲتِتھ، تہٕ سُہ روزُن سُکُن، اَتھ سٍتـ̡ گژھہِ تۅہہِ سٍتـ̡ خیر میلہِ۔ {سُہ: یعنی خدا}\n22. بہٕ چُھس ژے دُعا کٔرِتھ، شریعت تہٕ تٔمۍ سٕندِس دِلس مَنٛز تھاوُن تٔمۍ سٕندِس کلامَس مَنٛز۔\n23. یێلہِ ژے خدایس کُن واپس یِو، تێلہِ گژھہِ بد کاری پنہٕ نِس خیمہ نِش دور کٔرِتھ۔\n24. تیلہِ تھاوُن سۄنہٕ گردِ ہٕندۍ پٲٹھۍ، تہٕ اوفیرُک {سۄن} کٔرِو نالہٕ ہٕندِس پٲٹھۍ۔ {بطور گرد: یا، گردِ پیٹھ}\n25. آ، قادر مطلق آسہِ تُہند بچاو، تہٕ ژے آسہِ واریاہ رۄپہٕ۔ {دفاع: یا، سۄن} {کثرت...: ہیب۔ طاقتُک رۄپہٕ}\n26. تیلہِ گژھہِ ژیہ خدایس سٍتـ̡ خوشی حٲصل تہٕ پَنُن بُتھ تُلِتھ خدایہِ سٍتـ̡ ۔\n27.\\tتُہۍ کٔرِو أمِس سٍتـ̡ پنٕنۍ دُعا تہٕ سُہ کرِ تُہٕندِس سٍتـ̡ تہٕ پَنٕنـ̡ پۯاوٕنـ̡ ۔\n28. تہٕ کُنہِ چیزُک حکم تہِ کرُن، تہٕ سُہ گژھہِ تۅہہِ خٲطرٕ قایم کرنہٕ، تہٕ گاش گژھہِ تُہنزن وتن پیٹھ گاش۔\n29.\\tییلہ {انسان} ییہ تراونہٕ، تیلہِ گژھہِ تۅہہ ونان، {اتہِ چُھ} تھوٚد تھوٚد۔ تہٕ سُہ کرِ عاجز شخصس بچاو۔ {انکسار...: ہیب۔ یٔمِس أچھ کم آسہِ}\n30. سُہ کرِ معصومن ہُند جزیرٕ بچاوُن: تہٕ یہِ چُھہ تۅہہِ ہٕندِس اتھو سٍتـ̡ پاکیزگی سٍتـ̡ نجات دِنہٕ۔ {سُہ کرِ...: یا، معصوم کرِ جزیرٕ دِنہٕ}","1. اَمہِ پتہٕ دِژ ایوب جواب تہٕ وونُن،\n2.\\tاز تہِ چھیہ میٲنۍ شکایت تلخ: میون فالج چھہ میانہِ گڑبڑ کھوتہ زیادہ وزن۔ {سٹروک: ہیب۔ اتھہٕ}\n3. اوہ کاش میہ ٲس پتاہ زِ میہ کتہِ ہیکہِ سہ لٔبتھ! {یہ} بہٕ ہیکہ تٔمۍ سٕنزِ سیٹہِ پیٹھ یِتھ!\n4.\\tبہٕ کٔرِس أمِس برونہہ کُن کُن حُکُم کٔرِتھ، تہٕ بٔرِتھ بٔرِتھ دلیلہٕ۔\n5.\\tمیہ گژھہِ تم لفظ زانان یم میہ جواب دِیہِ، تہٕ سمجُن زِ سہ کیا کرِ میہ ونن۔\n6.\\tکیا سُہ کٔرِہ میہ خلاف پنٕنِس زبردست طاقتہٕ سٍتۍ درخواست؟ نَہ; مگر سہ تراوِ میہ منز {طاقت}۔\n7.\\tاتہِ ہیکہِ نیکوکارن أمِس سٍتـ̡ جھگڑہ کٔرِتھ۔ یِتھے پٲٹھۍ گژھِ بہٕ پننِس جج سٕندِ طرفہٕ ہمیشہٕ خٲطرٕ نجات دِنہٕ یُن۔\n8.\\tوچھو میہ برونہہ کُن پکان، مگر سہ {چھہ} چھہ نہ {تتہِ}۔ تہٕ پتھ کُن، مگر بہٕ چھُس نہٕ تس سمجھان:\n9.\\tکھوورِ اتھس پیٹھ ییتہِ سہ کٲم کران چھہ، مگر میہ چھہ نہ وچھان {سُہ}: سہ چھہ دچھنہِ اتھس پیٹھ ژورِ روزان، تہ میہ چھہ نہ وچھان۔\n10.\\tمگر سُہ چُھس زانان زِ بہٕ چُھس سٍتـ̡ پى۪ٹھ {یہ...: ہیب۔ یہ چھہ میہ سیتۍ\n11.\\tمیانہِ قدمن رٔٹتھ تہِ چھیہ میہ وتھ تھپھ کٔرمٕژ، تہٕ ووت نہ۔\n12. نہ چُھس بہٕ تٔمۍ سٕندِس چپنہٕ کِس حکمس نِش واپس گومُت۔ میہ چھہ پننہ ضروری {کھٮ۪نہ} کھوتہ زیادہ تمۍ سندِ ٲسک لفظ زیادہ احترام کران۔ {محترم: ہیب۔ ہٲوِتھ، یا، لیڈ اپ} {my...: یا، میون مقرر حصہ}\n13.\\tمگر سُہ {چُھ} أکِس {ذہنس منز}، تہٕ کُس ہیکہِ تس بدلٲوِتھ؟ تہٕ {یہ} تٔمۍ سُند روح کیا چُھ یژھان، حتیٰ کہ {یہ} تہٕ چُھ کران۔\n14.\\tتکیازِ سُہ چُھ میانہِ خٲطرٕ مقرر کرنہٕ آمُت سُہ انجام دِوان: تہٕ یِتھۍ واریاہ چیز چھِ أمِس سٍتـ̡ آسان۔\n15.\\tتێلہِ چُھس بہٕ تٔمۍ سٕنزِ موجودگی سٍتـ̡ پریشان گژھان: ییلہ بہٕ سوچان چُھس، بہٕ چُھس تس کھوژان۔\n16. تکیازِ خدایہ چُھ میون دِل نرم بناوان، تہٕ قادر مطلق چُھ مے پریشان کران:\n17.\\tکیازِ میہ اوس نہ انہِ گٹہِ برونہہ کنہِ ژٹنہ آمت، {تہِ} تہِ چھہ نہ تمۍ میٲنس بُتھس پیٹھ انہِ گٹہِ ژٹان۔","1.\\tوُچھُن وقت کیازِ چھُنہٕ خدایہ سٕندِس نِش پوشید، یِم أمِس زانان چھِ، تِم چھِنہٕ تٔمۍ سٕندِ دۅہ وُچھان۔\n2. {کیٚنٛہہ} چھِ اِشارٕ کَرنہٕ آمُت۔ تِم چھِ تشددٕ سان ریوڑ نِوان تہٕ کھٮ۪وان دِوان۔ {فیڈ...: یا، فیڈ تِم}\n3.\\tتِم چھِ بے باپ سُند گَرٕ ژٔلِتھ، تِم چھِ بیواہ سُند بیل گروی رٹان۔\n4.\\tتِم چھِ ضرورتمندَن وتہِ نِش پھیران: زمینہِ ہٕندِس غریبَس چھِ پانس اِکہٕ وٹہٕ ژوٗرِ تھاوان۔\n5.\\tوُچھِو، یِتھٕ پٲٹھۍ صحراہس منز جنگلی گَرٕ چھِ، تِم چھِ پننہِ کامہِ کُن نیران۔ شکارس خٲطرٕ وۅتھُن: بیابان {دِیُت} تِمن خٲطرٕ کھیٛن {تہٕ} تہٕ {تِہندِ} شُرین خٲطرٕ۔\n6.\\tتِم چھِ کھہَس مَنٛز تٔمۍ سُند مَکُل لُٹان۔ {مکایہ: ہیب۔ رَلاونہٕ آمُت مکایہ، یا، ڈریج} {تِم جمع کٔرِتھ...: ہیب۔ بدکار چھہ ونٹیج جمع کران}\n7.\\tتم چھہِ ننگہِ پلو ورٲے روزان زِ سردی منز چھہ نہ کانہہ پرد۔\n8.\\tتِم چھِ پہاڑن ہٕندِس روٗدس سٍتۍ اودٕر، تہٕ پناہ گاہ ہٕندِس محتاج آسنہٕ کِنۍ چھِ کٔنہِ کُ\n9.\\tتِم چھِ یِمن ہٕندِس سینس منزٕ بٔرِتھ تہٕ غریبن ہُند عہد کٔرِتھ۔\n10.\\tتِم چھِ پوشہٕ ورٲے ننگہٕ نیران، تہٕ تِم چھِ فاقہٕ نِش نِوان۔\n11.\\t{یُس} پننین دیوارن اندر تیٖل بناوان چھُ، {تہٕ} شرابہٕ دباونہٕ خٲطرٕ تہٕ ترش۔\n12.\\tانسان چِھ شہرٕ نیبر کُن کرٛٮ۪کھان تہٕ زخمیَن ہُند روح چُھ کرٛٮ۪کھان تہٕ توتہِ چُھ نہٕ خدایہ بیوقوفی دِوان۔\n13.\\tتِم چِھ تِمن منز یِم گاشس خلاف بغاوت کران چھِ۔ تِم چھِنہٕ اَمہِ کِس وَتہٕ پتاہ تہٕ نہ چھِ اَمہِ کِس وَتہٕ پٮ۪ٹھ روزان۔\n14.\\tگاشہ سٍتـ̡ وۅتھنہٕ وول قاتل چُھ غریبن تہٕ محتاجن ماران تہٕ راتس چُھ چور ہٕندۍ پٲٹھۍ۔\n15.\\tزناکار سٕنزِ أچھ تہِ چھے شفقُک انتظار کران تہٕ ونان زِ کانہہ تہِ أچھ چھے نہ میہ وُچھان: تہٕ چھُ تٔمۍ سُند بُتھ پوشہِ۔ {پوشہِ...: ہیب۔ خفیہ طور بُتھ تھاوُن}\n16.\\tانہِ گٹہِ منز چھِ تِم مکانہٕ کھٔنِتھ، {یِمَن} یِمو دۅہلہِ پانَس خٲطرٕ نشان زد کٔرِمٕتۍ: تِم چھِنہٕ گاش زانان۔\n17.\\tصبحس چھہ تمن ہندِ خاطرہ موتُک ژھایہ تہِ: اگر {کٲن} زانان چھہِ، تم چھہِ موتُک ژھایہ ہُند خوف۔\n18.\\tسُہ چُھ آبہٕ ہٕندۍ پٲٹھۍ تیز رفتار۔ تِہُند حصہٕ چُھ زمینس مَنٛز لعنت: سُہ چُھ نہٕ انگورن ہٕنز وتھ وُچھان۔\n19.\\tخشک سالی تہٕ گرمی چھہ شینہٕ آبس کھیوان: {یتھے پاٹھۍ چھہ}قبر {یِمو گۅناہ کٔرۍ}۔ {استعمال کٔرِتھ: ہیب۔ تشدد سان نِن}\n20. رحم گژھہِ أمِس مٔشِل؛ کیمہٕ کرِ أمِس مٔٹھۍ کھٮ۪وان۔ سُہ گژھِ نہٕ وۄنۍ یاد تھاونہٕ۔ تہٕ بدکاری گژھہِ کُلِس ہٕندۍ پٲٹھۍ پھُٹنہٕ۔\n21.\\tسُہ چُھ بد کار کٔرِتھ بنجر سٍتـ̡ التجا کران {یُس نہٕ برداشت کرِ} تہٕ بیواہ سٍتـ̡ چُھہ نہٕ نیکی کٔرِتھ۔\n22.\\tسُہ چُھ طاقتور تہِ پننہِ طاقتہٕ سٍتـ̡ پانس کُن کھینچ کوشش کران: سُہ چُھہ وۅتھان تہٕ کٲنسہ تہِ انسانس چُھہ زندگی ہُند پژھ آسان۔ {نہ...: یا چھہ نہ تس پننہِ زندگی پیٹھ بھروسہ کران}\n23.\\t{اگرچہ} یہ گژھہِ أمس دِنہٕ یُن، یتھ پیٹھ سُہ آرام کرِ۔ توتہِ چھیہ تمۍ سنز نظر تہنزِ وتہِ پیٹھ۔\n24.\\tتِم چھِ کینژَس کالس تھزراونہٕ آمٕتۍ، مگر گٔیہِ گٔژھِتھ تہٕ بٔنِتھ اننہٕ۔ تِم چھِ سارِنٕے {باقی} ہٕندۍ پٲٹھۍ وتہِ نِش نِنہٕ یوان، تہٕ مکایہٕ کین کنن ہٕندۍ پٲٹھۍژٹنہٕ یِوان۔ {گٔے گٔمٕتۍ: ہیب۔ چِھ نہٕ} {نِنہٕ آمُت...: Heb. بند کٔرِتھ}\n25.\\tتہِ اگر نہ ونہِ تہِ آسہِ، میہ کُس کرِ اپُز، تہٕ میانہِ کلامس کُس کرِ نہ کانہہ لایق۔","1.\\tاَمہ پتہٕ دیت بلداد شُہیت سُند جواب تہٕ وونُن\n2.\\tغلبہ تہٕ خوف چھُ أمِس سٍتـ̡ سٍتـ̡ سُہ پنہٕ نـ̡ تھزرس مَنٛز صلح کَران۔\n3. کیا تٔمۍ سٕندِ فوجن ہُند کانہہ تعداد چھُ؟ تہٕ کٔمس پیٹھ چُھ نہٕ تٔمۍ سُند گاش پٲدٕ گژھان؟\n4. تیلہِ کِتھہ پاٹھۍ ہیکہِ انسان خدایہ سٍتۍ انصاف کٔرِتھ؟ یا کِتھ کٔنۍ ہیکہِ سُہ صاف ٲسِتھ {یعنی} زنانہٕ سٕندِ سٍتـ̡ پٲدٕ سپدِتھ؟\n5.\\tزونہِ تام تہِ وچھو، تہ یہ چھہ نہ گاش دوان۔ آ، تارکھ چھِنہٕ أمۍ سٕنٛدِ نظرِ منٛز خالص۔\n6.\\tکوتاہ کم انسان، {یعنی} اکھ کیوم؟ تہٕ انسان سُند نیٚچُو، {یُس} اکھ کیمہٕ؟","1. مگر ایوب دیت جواب تہٕ وونُن،\n2. ژے کِتھہ کٔنۍ کٔر تٔمِس سٍتـ̡ یُس طاقتہٕ ورٲے چُھہ مدد کٔرمٕژ؟ {ژے} کِتھہ کٔنۍ چھکھ نٔر بچاوان {یُس نہٕ کانہہ طاقت چُھ}؟\n3.\\tژے کِتھہ کٔنۍ کٔرِتھ مشورٕ دِژمُت یٔمِس نہٕ کانہہ دانایی آسہِ؟ تہٕ ژیہ کِتھہ پاٹھۍ کور یہ چیز یُتھ چھہ تتھہ پاٹھۍ اعلان کورمُت۔\n4. ژے کٔمِس کٔرِتھ کٔرۍمٕتۍ؟ تہٕ کٔمۍ سُند روح آو ژے نِش؟\n5.\\tمردہ {چیز} چھہِ آبس تلہ کنہِ بنان تہ اتھ منز روزن وٲلۍ۔ {تہٕ دی...: یا، بسکینن سۭتۍ}\n6.\\tجہنم چھہ تس برونہہ کنہِ ننگہ، تہ تباہی چھیہ نہ کانہہ پرد۔\n7. سُہ چُھ شمالس کُن خٲلی جایہِ پیٹھ پھٔہلٲوِتھ، {تہٕ} چُھ زمینہٕ کُنہِ چیزس پیٹھ پھانسی دِوان۔\n8.\\tسُہ چُھ آبس پننِس گٔنِس اوٚبرس مَنٛز رٔٹان۔ تہٕ اوبُر چُھ نہٕ تمن تل کرایہٕ۔\n9.\\tسُہ چُھ پنُن تخت بُتھ تھپھ کٔرِتھ، {تہٕ} چُھ اَتھ پیٹھ پَنُن اوٚبر پھٔہلاوان۔\n10. تٔمۍ چُھ آبس حدو سٍتـ̡ گھیرِتھ، یوتام دۅہ تہٕ رات ختم سپدِ۔ {یوتام ...: ہیب۔ گاشہ کس اندس تام اندھیرے سٍتۍ}\n11.\\tآسمانٕکۍ ستون چھِ تھران تہٕ تٔمۍ سٕندِس ملامت سٍتـ̡ حیران گٔژھان۔\n12.\\tسُہ چُھ سمندرس پننہِ طاقتہٕ سٍتـ̡ تقسیم کران، تہٕ پننہِ فہم سٍتـ̡ چُھ سُہ مغرورَن سٍتـ̡ ماران۔ {فخر: ہیب۔ فخر}\n13.\\tپننہِ روحہٕ سٍتـ̡ چُھہ آسمانس سٍتـ̡ سجٲومُت۔ تمۍ سندِ اتھہ چھہ ٹیڑھ ناگ بنوومت۔\n14.\\tیِم چھِ تٔمۍ سٕندِس طریقس ہٕندِ حِصہٕ: مگر تٔمِس متعلق کوتاہ کم حصہٕ چُھ بوزنہٕ آمُت؟ مگر تٔمۍ سٕندِ طاقتُک گرج، کُس ہیکہِ سمجِتھ؟","1. بییہِ تھوو ایوب پنُن تمثیل جٲری، تہٕ وونُن، {جٲری: حب۔ اؠڈِٹ کَرنہٕ خٲطرٕ شٲمِل کَرنہٕ آمُ\n2. {یِتھ} خدا زندٕ چُھ، {یُس} چُھ میون فیصلہ نِیومُت۔ تہٕ قادر مطلق، {یٔمۍ میہ روح پریشان کورمُت]۔ {پریشان...: ہیب۔ میون روح بنیوو تلخ}\n3. سارِوٕے وقتس سٍتـ̡ چُھہ میون شاہ {چُھ} میٲنس مَنٛز، تہٕ خدایہِ سُند روح {چُھ} میٲنس نستہٕ مَنٛز۔ {روح...: یعنی سُہ شاہ یُس خداین دِژمُت}\n4.\\tمیانہِ وُٹھ گژھِ نہ بد کار کٔرِتھ تہٕ نہ میانہِ زبان کرِ دھوکہٕ۔\n5.\\tخدا نہ کرِ میہ تۅہہ جواز پیش کرُن: یوتام نہ بہٕ مران چھُس بہٕ پنُن دیانت پانس نِش ہٹاوُن۔\n6. میٲنۍ نیکی چُھس مُطٲبق تھپھ کٔرِتھ، تہٕ یێلہِ نہٕ یہِ تراوُن: یوتام بہٕ زندٕ چُھس نہٕ میون دِل ملامت کَران۔ {واریاہ زیٹھ...: ہیب۔ میانین دوہن پیٹھ}\n7. میون دُشمن گژھہِ بدکار تہٕ یُس میانہِ خلاف بدکار کھڑا گژھہِ۔\n8.\\tمنافق سٕنز وۅمید کیا چُھ، ییلہ خدایہ تٔمۍ سُند روح نِوان چُھ؟\n9.\\tییلہ تس مصیبت ییہ تیلہِ کیا خدایہ تسنز فریاد بوزناو؟\n10.\\tکیا سُہ کرِ خدایس سٍتـ̡ خۅد خۅش کرنہٕ؟ کیا سُہ چُھ ہمیشہٕ خدایس منگان؟\n11. بہٕ ہیچھناوٕ ژے خدایہ سٕندِ اتھہٕ سٍتۍ: {یہ} یُس {چُھ} خدایہ سٕندِس سٍتـ̡ چُھس نہٕ بہٕ ژوٗرِ تھاوُن۔ {by...: یا، اتھس منز آسُن، وغیرہ}\n12. وُچھو، تۅہہ سارِوٕے وُچھمُت {یہ}؛ تیلہِ کیازِ چھِو تۅہہ یِتھٕ پٲٹھۍ بےکار؟\n13. یہِ چُھ أکِس بدکار انسان سُند خدایہ سٍتـ̡ حصہٕ، تہٕ ظالمن ہُند میراث، {یُس} تِمن خدایہ سٕندِ طرفہٕ میلہِ۔\n14.\\tاگر تٔمۍ سٕندِ شُرۍ بٔڈِتھ گژھِ، تہٕ تٔمۍ سٕندِ اولادٕ گژھِ نہٕ روٹی سٍتـ̡ قمعیٖن کرنہٕ۔\n15. یِم أمِس نِش باقٕے روزان چھِ تِم گژھن مرنس مَنٛز دفن کرنہٕ یِن: تہٕ تٔمۍ سٕنزِ بیواہ گژھِ نہٕ روُن۔\n16. یودوَے سُہ رۄپہٕ رۄپہٕ رٔٹِتھ تہٕ میژِ ہٕندۍ پٲٹھۍپوش تیار کٔرِتھ۔\n17.\\tسُہ ہیکہِ تیار کٔرِتھ، مگر عادل لاگُن تہٕ معصوم کرِ رۅپہٕ بٲگراونہٕ۔\n18.\\tسُہ چُھ پَنُن مکانہٕ کیم سٕندِ پٲٹھۍبَناوان تہٕ یُس رٲچھ کرن وول بناوان چھُ۔\n19.\\tامیر گژھہِ بٔرِتھ، مگر سُہ گژھہِ نہٕ جمع کرنہٕ: سُہ چُھ پنٕنۍ أچھ کھولان، تہٕ سُہ چُھ نہٕ آسان۔\n20. تس چھہ آبس سیتۍ دہشت رٹان تہ رٲژ منز چھہ تس ژوٗرِ نوان۔\n21.\\tمشرِقی واو چُھ أمِس نِش نیران، تہٕ سُہ چُھ نیران، تہٕ یِتھٕ پٲٹھۍ چُھ سُہ پننہِ جایہِ نِش ژٔٹِتھ دِوان۔\n22.\\tکیازِ خدایہ کرِ تس پیٹھ تراوُن، تہٕ تراوِ نہٕ: سُہ گژھہِ پننہِ اتھہٕ نِش ژلُن۔ {وہ...: ہیب۔ ژلنس منز اوس سہ ژلان۔\n23.\\t{انسان} کرِ أمِس کُن اتھہٕ ژرِ پوٚپ، تہٕ أمِس کٔرِن أمِس پننہِ جایہِ نِش ہِش کٔرِتھ۔","1.\\tیقینا چھیہ رۅپہِ ہنز رگہ، تہ سۅنہِ خاطرہ چھیہ اکھ جاے {ییتہِ} تم ٹھہراونہ یوان چھہِ۔ {رگ: یا، میانۍ}\n2. شیشتُر چُھ زمینہٕ منزٕ کڈنہٕ یوان، تہٕ پیتل {چُھ} پگھلِتھ {نِش} کٔنہِ منز۔ {زمین: یا، گرد}\n3. سُہ چُھ انہِ گٹہِ ہُند خاتمہ کٔرِتھ، تہٕ سارِنٕے کمال ژھانڈان چھُ: انہِ گٹہِ ہٕنزِ کٔنہِ تہٕ موتُک سایہٕ۔\n4. سٔہلاب چُھ بسکینس سٍتـ̡ نیران۔ {آبہٕ تہِ} تہِ چھُ کھۄر مٔشِد: تِم چھِ خشک گٔمٕتۍ، تِم چھِ انسانو نِش دور گٔمٕتۍ۔\n5. {یوت} زمینہِ منزہ نیران چھہ تہ اتھ تلہ کنہِ چھہ نار نیران۔\n6.\\tاَمِچ کٔنہِ چھِ نیلم ہٕنز جاے تہٕ اَتھ مَنٛز چھِ سۄنہٕ سٕنز گرد۔ {گرد...: یا، سۄنہٕ خام دھات}\n7.\\t{اتہِ} چھیہ اکھ وتھ یتھ نہ کانہہ جاناوار زانان آسہِ، تہ یُس نہ گدھ سٕنزِ اچھ وچھمُت آسہِ:\n8.\\tشیر سٕندِ بچہٕ چُھ نہٕ اتھ لوٚگمُت، تہٕ نہ چُھ سٕہہ اَتھ کُن پٔکِتھ۔\n9. سُہ چُھ پَنُن پَنُن اَتھٕ کٔنہِ پَنِس کَنہِ پَنُن اَتھٕ سُہ چھُ پہاڑ موٗلہٕ سٍتۍ الٹان۔ {راک: یا، فلنٹ}\n10. سُہ چُھ کَنہِ پَنِس مَنٛز دریاو ژٹان۔ تہٕ تٔمۍ سٕنز أچھ چھِ پرٮ۪تھ کانہہ قیمتی چیز وُچھان۔\n11. سُہ چُھ سٔہلاب بہٕ وُچھنہٕ نِش رُکاوان۔ تہٕ {یُس چیز چھُ} چھُ، سُہ چُھ گاشس کُن انان۔ {اوور فلو: ہیب۔ روُن}\n12. مگر حکمت کتہِ میلہِ؟ تہٕ کتہِ چھیہ سمجھنچ جاے؟\n13.\\tانسان چھہ نہ امیک قیمت زانان۔ نہ چُھ یہٕ زندٕ زمینس منٛز لبنہٕ یوان۔\n14.\\tگہرایی چھہ ونان زِ یہ چھہ نہ میہ منز تہ سمندر چھہ ونان {یہ چھہ نہ} میہ سیتۍ تہِ۔\n15.\\tیہ ہیکہِ نہٕ سۄنہٕ خٲطرٕ حٲصل کٔرِتھ، تہٕ نہ گژھِ رۄپہٕ ہُند وزن کرنہٕ یُن۔ {یہ...: ہیب۔ اَمہ خٲطرٕ یِیہِ نہٕ اصل سۄنہٕ دِنہٕ}\n16.\\tامیک قدر ہیکہِ نہ اوفیر سٕندِس سونس سٍتۍ، قیمتی اونیکس سٍتۍ یا نیلم سٍتۍ کٔرِتھ۔\n17.\\tسون تہٕ کرسٹل ہیکہِ نہ اتھ برابر ٲسِتھ: تہٕ امیک بدلہٕ گژھِ نہٕ عمدہ سۄنہٕ سٕندِس جواہرس بدلہٕ۔ {جواہرات...: یا، برتن ہٕندِ}\n18.\\tمرجان یا موتٮن ہُند کانہہ ذکر گژھہِ نہٕ کرنہٕ یُن: تکیازِ حکمتُک قٲمتھ {چُھ} روبی پیٹھ۔ {مرجان: یا، راموتھ}\n19. ایتھوپیاہُک ٹوپاز گژھِ نہٕ اتھ برابر تہٕ نہ گژھِ امِچ قدر خالص سۄنہٕ سٍتۍ کرنہٕ۔\n20.\\tتیلہِ کتہِ چُھ حکمت؟ تہٕ کتہِ چھیہ سمجھنچ جاے؟\n21.\\tیہ وُچھِتھ چھُ سارِنٕے زندٕ وُچھِتھ تہٕ ہوہٕچ کۅکرِ نِش نِش تھاونہٕ آمُت۔ {ہوا: یا، جنت}\n22.\\tتباہی تہٕ موت چھُ ونان زِ اسہِ چھُ پننیو کنو سٍتۍ امچ شہرت بوزمٕژ۔\n23. خدا چُھ اَمہ وتہِ سمجُن، تہٕ سُہ چُھ اَمہ کِس جایہ زانان۔\n24. تکیازِ سُہ چُھ زمینہِ ہٕندِس اندس کُن وُچھان، {تہٕ} چُھ پورٕ آسمانس تل وُچھان۔\n25.\\tواو ہُند وزن بَناوُن۔ تہٕ سُہ چُھ آبس تول کران۔\n26.\\tییلہ تٔمۍ رودُک حکم تہٕ بجلی ہٕنز وتھ دِژ:\n27.\\tتێلہِ کیا تٔمۍ وُچھمُت تہٕ اعلان کٔرِتھ۔ تمۍ کٔر یہ تیار، آ، تہ ژھانڈن۔ {اعلان کٔرِو...: یا، نمبر کٔرِو}\n28.\\tتہٕ انسانس وۆنُن وُچھو، خداوند سُند خوف، یُس {چُھ} حکمت۔ تہٕ بدی نِش دور گژھُن {چُھ} فہم ۔","1. بییہِ تھوو ایوب پنُن تمثیل جٲری، تہٕ وونُن، {جٲری: حب۔ اؠڈِٹ کَرنہٕ خٲطرٕ شٲمِل کَرنہٕ آمُ\n2.\\tکاش میہ آسہِ {منز} ریتن پتھ کالہ، یتھے پاٹھۍ {منز} دۅہن {منز} خداین رژھراوان اوس۔\n3.\\tییلہ تمۍ سٕنز شمع میٲنس کلس پیٹھ چمک، {تہٕ ییلہ} تمۍ سٕندِس گاشس سٍتۍ بہٕ پکان انہِ گٹہِ منز۔ {موم بتی: یا، چراغ}\n4. یِتھٕ پٲٹھۍ بہٕ پننِس جوانی ہٕندِس دۅہَس مَنٛز، یێلہِ خدایہِ سُند راز میٲنِس خیمہ خانس پیٹھ اوس۔\n5.\\tییلہ خدایہ میہ سیتۍ اوس، {ییلہ} میانہِ شُرۍ ٲسۍ میہ سیتۍ وابستہ۔\n6.\\tییلہ میہ تھنہِ سیتۍ قدم واش کٔرۍ، تہٕ کٔنہِ کٔر میہ تیلٕکۍ دریاو۔ {میں: ہیب۔ میہ سۭتۍ}\n7.\\tییلہ بہٕ شہرہ کِنۍ گیٹس پیٹھ نیران اوسس، {ییلہ} میہ سڑکہِ منز پنٕنۍ سیٹ تیار!\n8.\\tنوجوانو وُچھ میہ تہ ژوٚپ پان تہ بُزرگ ووٚتھ، {تہٕ} ووٚتھُن۔\n9.\\tشہزادو کٔر کتھ کرنہٕ نِش پرہیز، تہٕ تھووُن پننِس ٲسس پیٹھ اتھہٕ۔\n10.\\tرئیسَن رٔٹِتھ رٔٹِتھ تہٕ تِہٕنزِ زبان ژٔٹِتھ گٔیہِ ٲسِس پیٹھ۔ {رئیس...: ہیب۔ رئیسن ہٕنٛز آواز ٲس ژوٗرِ}\n11.\\tییلہ کنن بوز، تیلہِ کٔر میہ برکت۔ تہٕ ییلہ أچھ وُچھ، تٔمۍ دِژ میہ گوٲہی:\n12.\\tکیازِ میہ دِژ غریب، یُس روُن اوس، تہٕ بے باپ تہٕ یٔمِس نہٕ أمِس مدد کرنہٕ خٲطرٕ کانہہ تہِ اوس۔\n13.\\tیُس مرنہٕ خٲطرٕ تیار اوس، سُہ آو میہ سٍتـ̡ دِل تہٕ مے دِژ بیواہ ہُند دِل خوشی سٍتـ̡ گٮ۪وُن۔\n14.\\tمیہ لٲگِتھ نیکی تہٕ اَمہ سٍتـ̡ لوٚگ میہ پوشہٕ تہٕ پوشہٕ ہٕندِس پٲٹھۍ۔\n15.\\tمیہ ٲس انہِ کُن اچھ تہ کھۅر ٲس میہ لنگڑس کُن۔\n16.\\tبہٕ اوسُس غریبن ہُند مول تہٕ وجہ {یُس} میہ پتاہ اوس نہٕ میہ ژھانڈان۔\n17.\\tتہٕ بہٕ کٔرِتھ بدکار سٕندِ دندٕ تہٕ تٔمۍ سٕندِس دندٕ منزٕ کٔڈِتھ ۔ {The jaws: Heb. جبڑ دندان، یا، گرائنڈرز} {تُلتھ: ہیب۔ کاسٹ}\n18.\\tاَمہ پتہٕ ووٚن بہٕ مَرٕ پننِس گرس منز، تہٕ بہٕ کٔرٕ دۅہ سیکہِ ہٕندۍ پٲٹھۍ۔\n19.\\tمیون مول اوس آبس پیٹھ پھٔہلِتھ تہ شبنم ٲس سارۍ رٲژ میٲنس لنجہِ پیٹھ۔ {پھٔلِو...: ہیب۔ کھولنہٕ آمُت}\n20.\\tمیون جلال اوس میہ منز تازہ، تہٕ میون کمان اوس میٲنس اتھس منز تازٕ۔ {تازٕ: ہیب۔ نٔو} {تجدید: Heb. تبدیل}\n21.\\tمیہ کٔر کُن کُن، تہٕ پرارُن تہٕ میانہِ مشورس پیٹھ ژھۄپہٕ۔\n22.\\tمیانہِ کلامٕ پتہٕ کٔر نہٕ تِمو دُبارٕ کتھ کرنہٕ۔ تہٕ میون کلام آو تمن پیٹھ۔\n23.\\tتہٕ تِم رودُن میانہِ خٲطرٕ پیار۔ تہٕ تمو کھول پنن بوش {as} پتہٕ رودٕ خٲطرٕ۔\n24.\\t{اگر} میہ تمن پیٹھ اسُن، تمن اوس نہٕ یقین {یہ}۔ تہٕ میانہِ بُتھِ ہُند گاش اوس نہٕ تِمو دِوان۔\n25.\\tمیہ کٔر تِہٕنزِ وَتھ ژٲرِتھ، تہٕ بیوٹھ سردار، تہٕ لشکرس مَنٛز بادشاہ سٕندِ حثیتہٕ روزُن، یُس ماتم کرن والٮ۪ن تسلی دِوان چھُ۔","1.\\tمگر وۅنۍ چھہِ میہ کھوتہ لۅکٹۍ لۅکٹۍ میہ طنز کران، یمن ہندۍ مول میہ پننین ریچھن ہندین ہونین سیتۍ رٔلتھ آسنس حقارت کران آسہِ۔ {لۅکٹ...: ہیب۔ میہ کھوتہ کم دۅہن ہند\n2. آ، کتہِ ہٮکہِ تِہٕندِس اتھن ہٕندِ طاقتُک {فٲید} کٔرِتھ، یٔمِس مَنٛز بُزرگ گٔیہِ؟\n3.\\tمحتاج تہٕ قحط کِنۍ {تِم ٲسۍ کُنہِ}۔ پرانہِ زمانس منز بیابانن منز ژلُن، ویران تہٕ فضول ۔ {کُنہِ: یا، رٲژ ہیو تاریک} {منز...: ہیب۔ پٔتمہِ رٲژ}\n4.\\tیمۍ کٔر کُلۍ کٔڈۍ کٔرِتھ تہٕ جونیپر موٗل ژٹان تہٕ تِمن ہٕندِس مازس خٲطرٕ۔\n5.\\tتِم کٔڈِتھ کٔڈِتھ {انسان} منز، (تِمو کٔر تِمن پَتہٕ ژوٗر ہٕندِس پٲٹھۍ)۔\n6.\\tوادی ہٕندِس گۅپھن منز روزُن، زمینہِ ہٕندِس گۅپھن منز روزُن تہٕ کٔنہِ پتھرن منز روزُن۔ {گۅپھ: ہیب۔ ہولز}\n7.\\tکُنہِ گۅپھ تلہ کنہِ آیہ تم جمع کرنہ۔\n8.\\t{تِم ٲسۍ بیوقوفن ہٕندِ شُرۍ، آ، پست نفرن ہٕندِ شُرۍ: تِم ٲسۍ زمینہٕ کھۅتہٕ بدکار۔ {بیس...: ہیب۔ مین آف نو نیم}\n9. تہٕ وۅنۍ چھُس بہٕ تِہُند بٲت، آ، بہٕ چھُس تِہُند ضمنی لفظ۔\n10. تِم چھِ مےٚ نفرت، تِم چھِ مےٚ نِش دور ژلان، تہٕ میٲنِس پھیکس پیٹھ تھوکُن نہٕ تراوان۔ {تہٕ ...: ہیب۔ تہٕ تھوکُن نہٕ رُکاونہٕ}\n11.\\tکیازِ تٔمۍ چھُ میٲنۍ رزِ یلہٕ کٔرمٕژ، تہٕ میہ دِژمُت، تِمو تہِ ترٲوۍ میہ برونہہ کُن لگام تہِ۔\n12.\\tمیانہِ دچھنہِ اتھس پیٹھ وۅتھان نوجوان۔ تِم چھِ میانہِ کھۅر ژٔٹِتھ تہٕ تِم چھِ میانہِ خلاف تِمن ہٕنزِ تباہی ہٕنزِ وتہٕ تُلان۔\n13. تِم چھِ میانہِ وَتہِ رَٹان، تِمو چھُ میٲنۍ آفت برونہہ کُن، تِمن چُھ نہٕ کانہہ مددگار۔\n14.\\tتِم آیہ {میہ پیٹھ} بٔڈۍ پھُٹِتھ {آبہٕ} منز: ویران گٔیہِ تِمو پان {میہ پیٹھ}۔\n15.\\tدہشت چھیہ میہ کُن پھیران: تِم چھِ میانہِ روحس واو ہٕندۍ پٲٹھۍ، تہٕ میانہِ خیریت چھِ اوٚبرٕکۍ پٲٹھۍ ژٔلان۔ {میون روح: ہیب۔ میون پرنسپل}\n16. تہٕ وۄنۍ چُھ میون روح میٲنس پیٹھ تراونہٕ آمُت۔ مصیبت ہٕندۍ دۅہ چھِ میہ رٔٹۍمٕتۍ۔\n17.\\tراتس منز چھیہ میانۍ اڈجہ ژلان تہ میانہِ اڈجہ چھیہ نہ آرام کران۔\n18.\\tمیانہِ بیمارِ ہٕندِس زورس سٍتۍ چھُ میون پلو بدلاوان: یہ چھُ میہ کوٹُک کالر ہیو گٔنڈان۔\n19.\\tتٔمۍ ترٛوو مے دَبَس مَنٛز، تہٕ بہٕ چھُس میٚژِ تہٕ رَژھ ہیوٗ بنیومُت۔\n20. بہٕ چُھس ژے کُن فریاد کران، تہٕ ژٕ چُھس نہٕ بوزان تہٕ ژٕ چُھس نہٕ میہ سٍتـ̡ وُچھان۔\n21.\\tژے چُھکھ میانہِ خٲطرٕ ظالم بنیومُت: پننہِ مضبوٗط اتھہٕ سٍتـ̡ چُھکھ پانس مُخٲلفت کٔرِتھ۔ {بنن...: ہیب۔ ظالم بنیومُت} {thy...: Heb. چانہِ اَتھٕچ طاقت}\n22. ژے چُھکھ مے ہوہس تام تُلان۔ ژے چُھکھ مے سوارِ سوارِ ہُند دِوان، تہٕ میون مال تحلیل کٔرِتھ۔ {مادہ: یا، حکمت}\n23.\\tکیازِ بہٕ چھُس پتاہ زِ ژے کٔرِکھ میہ {موت} تہٕ سارِنٕے زندٕ خٲطرٕ مقرر کرنہٕ آمُت مکانہٕ۔\n24.\\tبہٕ سُہ کرِ نہٕ قبرس کُن اتھہٕ پھٔہلِتھ، حالانکہ تِم تٔمۍ سٕنزِ تباہی منز رودِ۔ {قبر: ہیب۔ ہیپ}\n25.\\tمیہ روو نہ تس مۅکھہ یُس مصیبت اوس۔ کیا میون روح اوسا غریبن خٲطرٕ غم؟ {مصیبت منز: ہیب۔ ہارڈ آف ڈے؟}\n26.\\tییلہ میہ نیکی ژھانڈان اوس، تیلہِ آو بد تہ ییلہ میہ گاشس پیار، اتہِ آو اندھیر۔\n27.\\tمیانہِ یٔژ دۅہہ رُکٲوِتھ تہٕ آرام کٔرِتھ رُکٲوِتھ رُکٲوِتھ مُصیبتٕکۍ دۅہہٕ۔\n28. بہٕ گۆو آفتاب ورٲے ماتم کٔرتھ: بہٕ ووٚتھ تھوٚد، {تہٕ} بہٕ روو جمٲژ منٛز۔\n29. بہٕ چُھس ڈریگن ہُند بوے تہٕ راتہٕ مۄغلن ہُند سٲتھی۔ {راتہٕ مۄغل: یا، شترمرغ}\n30.\\tمیون مَسلہٕ چھُ کرٛیٚہُن، تہٕ میٲنۍ أڈجہِ چھِ گرمی سٍتۍ دزان۔\n31.\\tمیون ہارپ تہِ چھہ ماتم تہِ سپدان، تہ میون عضو چھہ تمن ہنزِ آوازِ منز یُس روان چھُ۔","1. میہ کور پننیو اچھو سٍتـ̡ اکھ عہد تیلہِ کیازِ پَزِ بہٕ أکِس نونہِ پیٹھ سونچُن؟\n2.\\tپیٹھمہِ پیٹھہ خدایہ سندِ کمہِ حصہٕ خٲطرٕ؟ تہٕ {کیا} اعلیٰ تعالیٰ سُند وراثت؟\n3.\\t{کیا }بدکارن ہنز تباہی چھیہ نہ؟ تہٕ بدکار کارن خٲطرٕ اکھ عجیب {سزا}؟\n4. کیا سُہ چُھ نہٕ میٲنۍ وتہٕ وُچھان، تہٕ میانین سارِنٕے قدمن گٔنزراوان چھُ؟\n5.\\tاگر بہٕ بےکار سٍتۍ پکان آسہِ، یا اگر میانہِ کھۅر دھوکہ دِنس منز جلدی کٔرمٕژ۔\n6. میہ گژھہِ برابر وزن، یُتھ خدایہ میانہِ دیانت زانہِ۔ {لیٹ...: ہیب۔ سُہ دِیُن میہ انصاف کِس ترازَس مَنٛز تولنہٕ}\n7.\\tاگر میون قدم وتہِ نِش پھیُر گومُت، تہٕ میون دِل میانین اچھن پَتہٕ پکان آسہِ، تہٕ اگر کانہہ داغ میانین اتھن پیٹھ ژٔٹِتھ آسہِ۔\n8.\\t{پتہٕ} دِیو میہ ووُن، تہٕ بیاکھ کھیوٚن۔ آ، میانہِ اولادٕ گژھن ختم کرنہٕ۔\n9.\\tاگر میانہِ دِل کُنہِ زنانہِ دھوکہٕ دِژمُت، یا {اگر} میہ آسہِ پننِس ہمساین ہٕندِس دروازس پیٹھ انتظار کورمُت۔\n10. {پتہٕ} میانہِ زنانہِ دِژ بییِس سٍتـ̡ رٔٹِتھ تہٕ باقٕے گٔژھن أمِس سٍتـ̡ نمُن۔\n11.\\tیہ {چُھ} اکھ سنگین جرم آ، یہِ {چھُ} اکھ ناانصافی {یُس ججَن ہٕندِ دٔسۍ سزا دِنہٕ یُن۔\n12.\\tتکیازِ یہ {چُھ} اکھ نار {یُس} تباہ کران چُھ، تہٕ میٲنۍ سارِنٕے اضافہٕ ختم کرِ۔\n13.\\tاگر میہ پننِس نوکرس یا پننِس نوکرس سٍتـ̡ حقارت کٔرِتھ، ییلہ تِمو میہ سٍتـ̡ بحث کٔرۍ۔\n14. تیلہِ کیا کرٕ بہٕ یێلہِ خدایہ وُتھ؟ تہٕ ییلہ سُہ یِنہٕ وِزِ بہٕ کیا جواب دِیہ؟\n15. یمۍ میہ رحمس منز بنوو سہ بنوو نہ؟ تہٕ کیا اسہِ اوس نہٕ رحمس منز کانہہ بناومُت؟ {کیا نہٕ اَکہ...: یا اوسا نہٕ اسہِ أکِس رحمس منز بناوان؟}\n16.\\tاگر میہ غریبس تہنزِ خواہشہِ نِش رُکٲوِمُت، یا بیواہ سٕنزِ نظرِ ہٕنز ناکامی آسہِ کٔرمٕژ۔\n17.\\tیا چُھس کُنہِ کھٮ۪نہٕ آمُت، تہٕ یِمن ہُند کھٮ۪نہٕ آمُت چھُ۔\n18.\\t(تکیازِ میانہِ جوانی پیٹھے اوس سُہ میانہِ سٍتـ̡ پرورش گومُت، بحیثیت مٲل سٍتـ̡ تہٕ مے چھے أمِس ماجہ ہٕندِس رحم پیٹھٕ رہنمٲیی کٔرمٕژ؛) {سُہ: یعنی بیواہ ہُند}\n19.\\tاگر میہ کانہہ پلو نہ آسنہ کِنۍ یا کانہہ غریب۔\n20. اگر نہٕ تٔمۍ سٕنزِ کمر میہ برکت دِژمٕژ آسہِ، تہٕ {اگر} سُہ آسہٕ نہٕ میانین دانٛدن ہٕنزِ اونگہٕ سٍتۍ گرم کرنہٕ آمُت۔\n21.\\tاگر میہ بے باپَس خلاف اتھہٕ تُلِمُت، ییلہ میہ دروازس منز پنُن مدد وُچھمُت:\n22. {پتہٕ} میون نٔر پیوٚو میٲنس پھیکس پیٹھ تہٕ میون نٔر پھُٹُن أڈجہِ پیٹھ۔ {بون: یا، چینلبون}\n23.\\tتباہی مۅکھہ خدایہ {اوس} میانہِ خاطرہ دہشت تہ تسنزِ عظمت کہ وجہ سٍتۍ ہیوٚک نہ میہ برداشت کٔرتھ۔\n24. اگر میہ سون پنُن وۅمید بنوو، یا جان سون ووٚنمُت، {ژے چھُس} میون اعتماد۔\n25.\\tاگر میہ خۅش گژھہِ تکیازِ میون دولت اوس واریاہ زیادہ، تہٕ امہ مۅکھہ زِ میون اتھہ اوس واریاہ زیادہ۔ {گٔٹۍ...: ہیب۔ واریاہ لٔب}\n26.\\tاگر میہ آفتاب وُچھان ییلہ یہ گاش آسہِ، یا زون گاشس منز پکان آسہِ۔ {آفتاب: ہیب۔ گاش} {منز...: ہیب۔ چمک}\n27.\\tتہٕ میون دِل چُھس ژوٗرِ پٲٹھۍ، نتہٕ چُھس میٲنس اتھس بوسہ دِژمُت: {میون ٲس...: ہیب۔ میانہِ اتھہ چھہ میٲنس ٲسس بوسہ دِژمُت}\n28.\\tیہ تہِ اوس اکھ گناہ {یُس قاضی سُند سزا دِنہٕ یُن} کیازِ میہ پزِ خدایہ سُند انکار کرُن۔\n29.\\tاگر بہٕ تس سٕنزِ تباہی پیٹھ خوش سپدان یُس میہ نفرت کران اوس، یا ییلہ بد کار لٔبِتھ تس پانس تھوٚد کٔرِتھ:\n30. نہ چُھس میہ پننِس روحس لعنت دِتھ گۅناہ کرنہٕ خٲطرٕ دِژمُت۔ {ٲس: ہیب۔ تالو }\n31.\\tیێلہِ میانہِ خیمہ ہٕندِس مردس ووٚن نہ، ہا ہا اسہِ آسہِ تٔمۍ سُند ماز! أسۍ ہیکَو نہٕ مُطمعیٖن ٲسِتھ۔\n32.\\tاجنبی اوس نہٕ سڑکہِ منز روزان: {مگر} میہ کھولۍ مسافرس خٲطرٕ پنُن دروازٕ۔ {مسافر: یا، وے}\n33.\\tاگر میہ آدم سٕندِ حثیتہٕ پنُن گناہ پننِس سینس منز ژوٗرِ تھٲوِتھ پنٕنۍ گناہ چھپاونہٕ یِوان: {آدم سٕندِس طریقس منز}\n34.\\tمیہ اوسا واریاہ بٔڈۍ ہجوم کھوژان، کِنہ خاندانن ہٕنزِ حقارت سٍتۍ اوسُس میہ خوفزدہ گومُت، زِ بہٕ اوسُس ژھۄپہٕ کٔرِتھ، {تہٕ} دروازٕ منزٕ نیبر نیران؟\n35.\\tاوہ یہ بوزِ میہ بوزان! وچھ میٲنۍ خواہش {یہِ} زِ خداتعالیٰ دِیہ میہ جواب، تہٕ {یہ} میٲنس مخٲلفن ٲس اکھ کتاب لیچھمٕژ۔ {میانۍ...: یا، میون نشانہ چھہ یہ زِ قادر مطلق چاہ}\n36.\\tیقینا بہٕ رٔٹِتھ یہ پننِس پھیکس پیٹھ، {تہٕ} پانس سٍتۍ تاج لٲگِتھ۔\n37. بہٕ کرٕ تس پننین قدمن ہُند تعداد اعلان۔ بحیثیت شہزادہ گژھہِ بہٕ تس نزدیک۔\n38.\\tاگر میانہِ زمینہِ میہ خلاف فریاد کرِ، یا یِتھٕ پٲٹھۍ چھِ اَمہ سٍتۍ شکایت کٔرِتھ۔ {شکایت: ہیب۔ وُن}\n39.\\tاگر میہ امکۍ پھل پونسہٕ ورٲے کھیوٚمُت، یا امکۍ مالکن ہٕنز جان ضایع کرمژ: {پھل: حب۔ طاقت} {مألک...: ہیب۔ امہ کین مالکن ہُند روح ختم گژھُن، یا دم نیرُن}\n40.\\tکٕنکہٕ بدلہٕ گٔژھِن کُلہٕ تہٕ وٕشکہٕ بدلہٕ کۅکر۔ ایوب سٕندِ کلامَن ہُند کلام چُھ ختم۔ {کاکل: یا، نویسم ویڈز}","1.\\tتێلہِ گۆو یِمو تریہ نفرو ایوب سُند جواب دِنہٕ بند، تکیازِ سُہ اوس پننین نظرن منز نیک ۔ {to...: Heb. جواب دِنہٕ پیٹھ}\n2. اَمہِ پَتہٕ گۆو رام سٕندِس رشتہ دارس سٍتـ̡ باراکیل بُزیت سٕندِس نیچوِس ایلیہو سُند قہر دِنہٕ: ایوب سٕندِس خلاف گۆو تٔمۍ سُند قہر دِنہٕ، تکیازِ تٔمۍ اوس خدایہ سٕندِ بدلہٕ پانس جواز دِوان۔ {پانہٕ: ہیب۔ تٔمۍ سُند روح}\n3. تٔمۍ سٕندٮ۪ن ترٮ۪ن یارن خلاف تہِ اوس تٔمۍ سُند غصہٕ دِنہٕ آمُت، تکیازِ تِمن اوس نہٕ کانہہ جواب مِلنہٕ آمُت، تہٕ {توتہِ} اوس ایوب سٕنز مذمت کٔرمٕژ۔\n4.\\tوۅنۍ اوس ایلیہو پیارُن یوٚت تام ایوب سٕندِ کتھ کٔرِتھ، تکیازِ تِم ٲسۍ أمِس کھۅتہٕ بٔڈۍ۔ {انتظار...: ہیب۔ متوقع نوکری لفظن منز} {elder: Heb. بٔڈۍ دۅہن خٲطرٕ}\n5.\\tییلہ ایلیہوہن وُچھ زِ {یِمَن} ترٮ۪ن نفرن ہٕندِس ٲسِس منز چُھنہٕ کانہہ جواب، تیلہِ گۆو تٔمۍ سُند شرارت۔\n6.\\tتہٕ برخیل بوزیت سٕندِ نیچو الیہو دِژ جواب تہٕ وونُن، بہٕ چُھس جوان تہٕ تُہۍ چھِو واریاہ بُزرگ۔ اَمہِ مۄکھٕ اوسُس بہٕ کھوژان، تہٕ ہمت ٲس نہٕ ژےٚ پنٕنۍ راے ہاونہٕ۔ {نوجوان: ہیب۔ کینہہ دۅہہ} {durst...: Heb. خوف}\n7. میہ ووٚن، دۅہن گژھہِ کتھ کرٕنۍ، تہٕ واریاہن ؤرین گژھہِ حکمت ہیچھناوٕنۍ۔\n8.\\tمگر انسانس منز چھہ روح تہ خداتعالیٰ سند الہام چھہ تمن سمجھ دوان۔\n9.\\tبٔڈۍ انسان چھہِ نہ ہمیشہٕ عقلمند آسان: نہ چھہ بُزرگ فیصلہ سمجھان۔\n10. تێمہِ کِنۍ ووٚن میہ بوزو۔ بہٕ تہِ ہاوٕ پنٕنۍ راے ۔\n11.\\tوچھ، میہ اوسس چانہِ کلامُک انتظار۔ میہ کٔر چانۍ وجوہات بوز، ییلہ ژیہ ژھانڈان زِ کیا چُھ ونُن۔ {وجہ: Heb. تفہیم} {کیا...: ہیب۔ لفظ}\n12. آ، بہٕ کٔر تۅہہِ سٍتـ̡ توجہ دِنہٕ، تہٕ وُچھو، {تَہہ} اوس نہٕ کٲنسہ تہِ یُس ایوب سٕندِس کلامُک جواب دِیُت:\n13. یێلہِ نہٕ تۅہہ ونُن زِ اسہِ چُھ حکمت لبنہٕ آمٕژ: خدا چُھ أمِس دِوان ، نہ کہ انسان۔\n14.\\tوۅنۍ چھہ نہ تمۍ میانہِ خلاف پننین لفظن ہند اشارہ کوٚرمت، تہ نہ کرِ میہ تہندس کلامس سیتۍ جواب۔ {ہدایت: یا، حکم دِنہٕ}\n15.\\tتِم گٔے حٲران، تِمو دِژ نہٕ بییہ کانہہ جواب: تِمو ترٲو کتھ کرنہٕ۔ {دٔچھُن...: ہیب۔ تقریر ہٹٲوِتھ پانَس نِش ہٹٲوِ}\n16.\\tییلہ میہ انتظار کور، (تکیازِ تِمو کٔر نہٕ کتھ کرنہٕ، مگر کھڑا رودُن، {تہٕ} دِژ نہٕ مزید جواب؛)\n17.\\t{میہ ووٚن}، بہٕ کرٕ پننہ راے تہِ جواب، بہٕ تہِ کرٕ پنٕنۍ راے ہاوان۔\n18.\\tکیازِ بہٕ چُھس مادٕ سٍتـ̡ بٔرِتھ، میٲنِس اندر چُھہ روح میہ مجبور کران۔ {معاملہ: ہیب۔ لفظ} {روح...: ہیب۔ اسپرٹ آف ماے بیل}\n19.\\tوچھ، میون اڈ {چھُ} شرابُک ہیوٗ {یُس} چھُنہٕ کانہہ وَنُن۔ یہِ چُھ نَوین بوتلن ہٕندۍ پٲٹھۍ پھٹنہٕ خٲطرٕ تیار۔ {ہاتھ...: ہیب۔ چُھ نہٕ کھولنہٕ آمُت}\n20.\\tبہٕ کَرٕ کَتھ، یُتھ بہٕ تازٕ گٔژھِتھ: بہٕ کَرٕ پنُن وُٹھ تہٕ جواب دِنہٕ۔ {be...: Heb. سانس کٔرِو}\n21.\\tبہٕ چھُس دُعا کران زِ بہٕ کٔرِو نہٕ کٲنسہ تہِ انسان سُند شخص قبول، تہٕ نہ دِیُن بہٕ انسانس خوشامد کٔرِتھ۔\n22.\\tکیازِ بہٕ چھُس نہ چاپلوسی ہُند لقب دِنہٕ یُن۔ {یتھہ پاٹھۍ کٔرِتھ} میون بناون وول نِیہِ جلدے میہ نِتھ۔","1. اَمہِ مۄکھہٕ چُھس ایوب، بہٕ چُھس ژے دُعا کران، میٲنۍ کلام بوزُن، تہٕ میانہِ سارِنٕے کلامَن بوزُن۔\n2.\\tوُچھ، وۅنۍ چھُ میہ بوش کھولمُت، میانہِ زبان چھیہ ٲسس منز کتھ کٔرمٕژ۔ {میٲنس ٲسس منٛز: ہیب۔ میٲنس تالس منٛز}\n3.\\tمیانہِ کتھہِ آسہِ میانہِ دِلچ سیدھی تہ میانہِ وٹھ گژھہِ واضح پاٹھۍ علم بیان کرنہ۔\n4. خدایہِ سٕندِ روحن چُھ مے بنوومُت، تہٕ قادر مطلق سٕندِ شہس دِژ مے زندٕ۔\n5.\\tاگر ژیہ میہ جواب دِتھ ہیکو، میانہِ برونہہ کنہِ تھوٚد۔\n6.\\tوچھو، بہٕ چُھس خدایہ سٕنزِ جایہِ تہِ چانہِ مرضی مُطٲبق بنیومُت: بہٕ تہِ چُھس میژِ سٍتـ̡ بنیومُت۔ {خواہش: ہیب۔ ٲس} {تشکیل: Heb. کٹ}\n7. وچھ میٲنۍ دہشت ژیہ نہ ژیہ خوفزدہ تہ نہ گژھہِ میون اتھہ ژے پیٹھ بوب۔\n8.\\tیقینا چُھہ ژے میانہِ بوزنس منز کتھ کٔرمٕژ، تہٕ مے بوزمُت {چانہِ} لفظن ہٕنز آواز، {ونان}، {بوزُن: عبرانی۔ کَن}\n9. بہٕ چُھس بے گناہ ورٲے پاکیزہ، بہٕ چُھس {بہ} معصوم۔ نہ چھہ میہ منز کانہہ بدکاری۔\n10. وُچھِو سُہ میانہِ خلاف موقعہٕ میلان تہٕ سُہ چُھس مےٚ پَنُن دُشمن مانان۔\n11.\\tسُہ چُھ میانہِ کھۅر سٹاکس منز تراوان، سُہ چھُ میانہِ سارِنٕے وتہٕ مارکیٹ۔\n12.\\tوچھو ژیہ چھہ نہ اتھ منز انصاف کران: بہٕ دیہ ژیہ جواب زِ خدا چھہ انسانہ کھوتہ بوڈ ۔\n13.\\tژیہ کیازِ چھکھ تس خلاف کوشش کران؟ تکیازِ سُہ چُھ نہٕ پننین معاملن ہُند حساب دِوان۔ {سُہ دِیُت...: ہیب۔ سُہ چُھ نہٕ جواب دِوان}\n14. تکیازِ خدا چُھ اکہِ لٹہِ کتھ کران، ہاں دۄیہِ لٹہِ، {توتہِ چُھہ انسان نہٕ یہِ سمجھان۔\n15.\\tخوابس منز، رٲژ ہٕندِس وژنس منز، ییلہ انسانن سٍتـ̡ گۆو نندر پیوان چُھ، بسترس پیٹھ نندر منز؛\n16.\\tتێلہِ چُھ سُہ انسانن ہٕندِس کَن کھولان تہٕ تِمن ہٕنزِ تعلیمہِ پیٹھ مہر تراوان، {سُہ...: ہیب۔ سُہ چُھ ظٲہر کران، یا، پردہ دِوان}\n17.\\tیُتھ زِ سُہ کرِ انسان نِش غرور ژوٗرِ۔ کٲم}\n18.\\tسُہ چُھ پنُن روح گۅڈٕ نِش بچاوان تہٕ تلوار سٍتـ̡ ختم گژھنہٕ نِش بچاوان ۔ {ختم گژھنہٕ پیٹھ: ہیب۔ پاس کرنہٕ نِش}\n19.\\tأمِس چُھ بسترس پیٹھ دگ تہٕ أڈجن ہٕندِس بٔڑِس سٍتـ̡ دگ دِنہٕ آمُت:\n20.\\tیُتھ تٔمۍ سٕنزِ زندگی ہٕندِس روٹی سٍتـ̡ نفرت، تہٕ تٔمۍ سٕنزِ روحُک لذیذ ماز۔ {ڈینٹی...: ہیب۔ خواہش ہُنٛد ماز}\n21. تٔمۍ سُند ماز چُھ کھٮ۪نہٕ آمُت، یُس نہٕ وُچھنہٕ یِوان۔ تہٕ تٔمۍ سٕنٛزٕ أڈجہِ ٲس نہٕ نیبر نیران وچھنہٕ۔\n22. آ، تٔمۍ سُند روح چُھ قبرس نزدیک، تہٕ تٔمۍ سٕنز زندگی چُھ تباہ کرن والن نزدیک۔\n23.\\tاگر تس سٍتـ̡ کانہہ پیغامبر آسہِ، ساسن منز اکھ ترجمہ، یُس انسانس سٍتـ̡ تٔمۍ سٕنز پاکیزگی ہاونہٕ خٲطرٕ آسہِ۔\n24.\\tتێلہِ چُھ سُہ أمِس مہربان تہٕ وَنُن زِ أمِس کٔرِو کھۅنہٕ نِش بچاوُن: مے لوٚب رُدٕ ۔ {اکھ تاوان: یا، اکھ کفارہ}\n25.\\tتٔمۍ سُند ماز گژھہِ شُرِ سٕندِ کھۅتہٕ تازٕ آسُن: سُہ گژھہِ پننہِ جوانی ہٕندِس دۅہس مَنٛز واپس: {شُرۍسٕندِ: ہیب۔ بچپن}\n26. سُہ کرِ خدایہ سٕنز دُعا تہٕ سُہ کرِ أمِس سٍتـ̡ احسان تہٕ سُہ کرِ پننِس بُتھِس خۅش سٍتـ̡ وُچھان، تکیازِ سُہ کرِ انسانس پَنٕنـ̡ نیکی دِنہٕ۔\n27.\\tسُہ چُھ انسانس کُن نظر تھاوان، تہٕ {اگر کانہہ تہِ} ونان چُھ، مے چُھ گۅناہ کورمُت، تہٕ یُس صحیح اوس، تہٕ اَمہ سٍتـ̡ چُھہ نہٕ مےٚ فٲیدٕ دِنہٕ آمُت۔ {سُہ...: یا، سُہ وُچھِتھ انسانس کُن وُچھِتھ وَنُن}\n28.\\tسُہ کرِ پنُن روح کھۅنہٕ نِش بچاوُن، تہٕ تسٕنزِ زندگی وُچھِ گاش۔ {سُہ...: یا، أمۍ چھُ میون روح بیترِ تہٕ میٲنۍ زندگی بچٲومٕژ}\n29. یِم سارِنٕے {چیز} چِھ خدایہ سٕندِ سٍتـ̡ اکثر انسانس سٍتـ̡ کٲم کران، {اکثر: ہیب۔ دۄیہِ لٹہِ تہٕ تریہ لٹہِ}\n30.\\tپَنُن روح گۅڈٕ منزٕ واپس انُن، زندٕ سٕندِ گاشہٕ سٍتـ̡ روشن کرنہٕ خٲطرٕ۔\n31.\\tاے ایوب، بوزو میانہِ کتھہِ سٍتـ̡ پَنُن سکون، تہٕ بہٕ کَرٕ کَتھ\n32.\\tاگر ژیہ کانہہ کتھ ونُن چُھ، تیلہِ کٔرِو میہ جواب: کتھ کرُن، تکیازِ بہٕ چُھس چانہِ جواز پیش کرُن یژھان۔\n33.\\tاگر نہٕ تیلہِ کٔرِو میانہِ کتھہِ سٍتـ̡ بوزن: پَنُن رٔٹِو تہٕ بہٕ ہیچھناوٕ ژے حکمت۔","1.\\tامہِ علاوہ دیت ایلیہو جواب تہ وونُن،\n2.\\tمیٲنۍ کتھ بوزو، اے عقلمند {انسان}؛ تہٕ کٔرِو میہ کُن بوزُن، یُس علم تھاوان چھُ۔\n3.\\tکُن چھہ لفظن ہنز کوشش کران، یتھہ پاٹھۍ ٲسس ماز چکھان چھہ۔ {ٲس: ہیب۔ تالو }\n4. اسہِ کرو پننین فیصلن ہند انتخاب کرُن: اسہِ گژھہِ پانس منز معلوم زِ {اصل} کیا چُھ۔\n5. کیازِ ایوب چُھس ووٚنمُت، بہٕ چُھس نیک تہٕ خداین چُھ میون فیصلہ نِش نِمُت۔\n6. کیا بہٕ پزیا پننِس حقس خلاف اپُز روزُن؟ میون زخم {چُھ} چھُ بے عیب بغٲر لاعلاج۔ {میون زخم: ہیب۔ ماین تیر}\n7. کُس انسان چُھہ ایوب ہیو چُھ، یُس آبہٕ ہٕندۍ پٲٹھـ̡ چُھہ چُھہ؟\n8. یُس بدکار کارن سٍتـ̡ رٔلِتھ چُھہ تہٕ بدکارن سٍتـ̡ پکان چُھ۔\n9.\\tتکیازِ تٔمۍ چُھ ووٚنمُت زِ انسانس چُھہ نہٕ کانہہ فٲیدٕ زِ سُہ گژھہِ خدایہ سٍتـ̡ خۅش سپدُن۔\n10. تێمہِ کِنۍ کٔرِو میانہِ کُن بوزو، اے سمجھدار لوگو: خدایہ سٕندِ نِش گژھہِ بد کاری کرٕنۍ۔ تہٕ {خداتعالیٰ سٕندِس} سٍتـ̡ {زِ سُہ کرِ بدکار کرُن}۔ {مرد...: ہیب۔ مین آف ہارٹ}\n11.\\tانسان سٕنزِ کامہِ خٲطرٕ کرِ سُہ أمِس حوالہٕ، تہٕ پرٮ۪تھ أکِس انسانس دِیہِ تٔمِس طریقس مطٲبق۔\n12. آ، یقینا خدایہ کرِ نہ بدکار تہ نہ کرِ خدایہ بدکار فیصلہٕ۔\n13. أمِس کٔمۍ دِژ زمینس پیٹھ ذمہ داری؟ یا کٔمۍ چھُ پوٗرٕ دُنیا دِژمُت؟ {پورٕ: ہیب۔ یہ سورُے؟}\n14.\\tاگر سُہ پنُن دِل انسانس کُن تھوو، {اگر} سُہ پنُن روح تہٕ شاہ پانس سٍتـ̡ جمع کرِ۔ {مرد: ہیب۔ سُہ }\n15. سٲری ماز گژھہِ اکوٹہ ختم تہٕ انسان گژھہِ دُبارٕ گردِ بٔنِتھ۔\n16.\\tاگر وُنہِ تہِ سمجھ آسہِ، یہ بوزو: میانہِ کلامٕچ آواز بوزو۔\n17.\\tیُس حقس سٍتـ̡ نفرت کرِ، سُہ تہِ کرِ حکومت؟ تہٕ کیا تُہۍ کٔرِو تٔمِس انصاف کِس سٍتـ̡ مذمت کٔرِتھ؟ {گورنمنٹ: ہیب۔ پابند کٔرِتھ؟}\n18.\\t{کیا یہ چھا مناسب} بادشاہس ونُن، {ژٕ چھُکھ بدکار}؟ {تہٕ} شہزادن خٲطرٕ، {تُہۍ چھِو} بے دین؟\n19.\\t{أمِس کوتاہ کم چُھ} یُس نہٕ شہزادن ہٕندِس شخصس قبول کران چُھ، تہٕ نہ امیرن غریبن کھوتہٕ زیادٕ اہمیت دِوان۔ تکیازِ یم سٲری چھہِ تمۍ سندِ اتھن ہنز کٲم۔\n20. أکِس لمحس منز گژھن تِم مَرٕن، تہٕ لُکھ گژھن نصف رٲژ پریشان تہٕ گٔژھِتھ گٔژھِن، تہٕ طاقتور یِن اتھہٕ ورٲے نِنہٕ۔ {طاقتور...: ہیب۔ تِم نِن طاقتور}\n21.\\tتکیازِ تٔمۍ سٕنزِ نظر چھے انسان سٕنزِ وتہِ وُچھان، تہٕ سُہ چُھ پنٕنـ̡ سارِنٕے وُچھان۔\n22. {اتہِ} چُھہ نہٕ انہِ گوٚٹ تہٕ نہ موتُک سایہٕ، یتہِ بدکاری ہٕندِس کارکُن پنُن پان ژوٗرِ روزِ۔\n23.\\tکیازِ سُہ کرِ نہ انسانس پیٹھ {حقہٕ کھوتہٕ زیادٕ}۔ زِ سُہ پزِ خدایس سٍتـ̡ انصاف کٔرِتھ۔ {دٲخل گژھُن: ہیب۔ گو}\n24.\\tسُہ کرِ بے شمار طاقتور نفرن ٹُکرٕ ٹُکرٕ تہٕ باقین ہٕنزِ جایہ تراوُن۔ {نمبر: ہیب۔ تلاش}\n25.\\tتێلہِ چُھ سُہ تِمن ہٕندِس کامہِ ہُند پتاہ تہٕ سُہ چُھ رٲژ تِمن ہُند اِشارٕ دِوان، یێلہِ تِم تباہ گٔیہِ۔ {تباہ: ہیب۔ کرشڈ}\n26.\\tسُہ چُھ یِمن بد کار سٕندِ پٲٹھـ̡ دِوان۔ {کھولو...: ہیب۔ وُچھن والٮ۪ن ہٕنٛز جاے}\n27.\\tکیازِ تِمو پھیرۍ أمِس نِش تہٕ تٔمۍ سٕندِس کُنہِ تہِ وتہِ پیٹھ غور کرُن: {سُہ: حب۔ أمِس پتہٕ}\n28. یُتھ زن تِم غریبن ہٕنز فریاد أمِس نِش واتناوان تہٕ سُہ بوزِ مُصیبت زدہ سٕنز فریاد بوزان۔\n29.\\tییلہ سُہ خاموشی دِوان چُھ، تیلہِ کُس ہیکہِ پریشٲنی پٲدٕ کٔرِتھ؟ تہٕ ییلہ سُہ بُتھ ژوٗرِ تھاوان چھُ، تیلہِ کُس ہیکہِ تس وُچھِتھ؟ چاہے یہ کُنہِ قومس خٕلاف کرنہٕ یُن، یا صرف کٲنٛسہِ انسانس خٕلاف:\n30.\\tزِ منافق گژھہِ نہٕ بادشاہ، یُس نہ عوامس پھنسنہٕ یِن۔\n31.\\tیِہ چُھہ خدایہ سٍتـ̡ وَننہٕ آمُت، بہٕ چُھس نہٕ زیادٕ رُکاونہٕ آمُت:\n32.\\t{یُس میہ وچھان چُھس نہٕ ژے ہیچھناوُن: اگر میہ بدکار آسہِ، بہٕ کرٕ نہٕ بییہ کانہہ تہِ۔\n33.\\t{کیا یہ گژھہِ تۅہہِ ذہنس مطٲبق؟'' سُہ دِیہِ اَمیُک بدلہٕ، چاہے تُہۍ انکار کٔرِو، یا چاہے ژےٚ ژٲرِو۔ تہٕ بہٕ نہٕ: لہذا کتھ کٔرِو یُس ژے زانان چھُ۔ {مطٲبق...: ہیب۔ ژے سٍتۍ؟}\n34.\\tسمجھ دار گژھن میہ ونُن، تہٕ اکھ دانشمند گژھہِ میانہِ کتھہِ بوزُن۔ {of...: ہیب۔ دِلُک}\n35. ایوب چُھ علمہٕ ورٲے کتھ کٔرمٕژ، تہٕ تٔمۍ سٕندِ کلامَن ٲس عقلہٕ ورٲے کتھ کٔرمٕژ۔\n36.\\tمیانہِ خواہش چھیہ یہ زِ ایوب گژھہِ ٲخرس تام آزماونہٕ یُن کیازِ بدکار نفرن ہٕندِ جوابن سٍتۍ گژھہِ ٲخرس تام کوشش کرنہٕ۔ {میانۍ...: یا، میون مول، ایوب گژھہِ آزماونہٕ}\n37.\\tیێلہِ سُہ چُھ پننِس گۅناہ سٍتـ̡ بغاوت ہُند اضافہ کران، سُہ چُھ اسہِ مَنٛز ژرِ پٲٹھـ̡ تہٕ خدایس خلاف پنٕنـ̡ کلام بڑاوان۔","1.\\tالیہو وۆن بییہِ کتھ تہٕ وونُن،\n2.\\tژیہ چھا یہ صحیح، {یہ} ژے ووٚنمُت، میٲنۍ راستبازی چھیہ خدایہ سندِ کھوتہ زیادٕ؟\n3.\\tتکیازِ ژے ووٚن، اَمہ سٍتـ̡ کیا فٲیدٕ واتہِ؟ {تہٕ}، میہ کیا فٲیدٕ میلہِ، {اگر بہٕ پننہِ گۅنہٕ نِش پاک گژھہِ}؟ {اگر...: یا، میانہِ گۅناہ کھوتہ زیادہ}\n4. بہٕ کٔرٕ ژےٚ تہٕ تُہٕندِس سٲتھیَن تہٕ ژےٚ سٍتـ̡ جواب۔ {جواب...: ہیب۔ پننین لفظن کُن واپس}\n5.\\tآسمانس کُن وُچھِو، تہٕ وُچھِو؛ تہٕ وُچھِو اوٚبرٕ {یُس} ژے کھۅتہٕ تھوٚد چھُ۔\n6. اگر تہۍ گۅنہگار چھِو، تۅہہ کیا چُھہ تس خلاف کران؟ یا {اگر} تۅہہِ ہٕندِس گناہ سٍتـ̡ زیادٕ گٔیہِ، تُہۍ کیا چُھہ أمِس سٍتـ̡ کٔرِتھ؟\n7.\\tاگر ژیہ نیک بٔنِتھ چھِو، تۅہہ کیا دِیُت أمِس؟ نتہٕ تس کیا چُھ تُہند اتھہٕ حٲصل کران؟\n8. تُہٕنزِ بدکٲری ہٕندِس انسانس ہٕندِس سٍتـ̡ تکلیف دِنہٕ یێلہِ۔ تہٕ تُہٕنزِ نیکی ہێکہِ انسان سٕندِس نیٚچوِس فٲیدٕ حٲصِل کٔرِتھ۔\n9.\\tظلمن ہٕندِس بہتٔر سٍتـ̡ چِھ تِم {مظلومن} وُنـ̡ دِوان: تِم چِھ طاقتور سٕندِ نرِ سٍتـ̡ فریاد دِوان۔\n10. مگر کانہہ تہِ چُھ نہٕ ونان، کتہِ چُھہ خدا میون بناون وول یُس رٲژ بٲتھ دِوان چُھ؛\n11.\\tکُس چُھ اسہِ زمینہٕ کِس درندَو کھۅتہٕ زیادٕ ہیچھناوان تہٕ اسہِ اسمانہٕ کِس جاناوارو کھۅتہٕ زیادٕ عقلمند بناوان؟\n12.\\tتتہِ چِھ تِم روان مگر بدکار سٕندِ غرور کِنۍ چُھہ نہٕ کانہہ تہِ جواب دِوان۔\n13.\\tیقینا خدایہ بوزِ نہٕ بکواس تہٕ نہ کرِ خدایہ سُند خیال تہِ۔\n14.\\tیودوَے تہٕ ژے وُچھِو نہٕ أمِس وُچھان، {توتہِ} چھُ أمِس برونہہ کُن فیصلہٕ۔ لہذا کرو تس پیٹھ بھروسہٕ۔\n15.\\tمگر وۅنۍ کیازِ {یہ} چھہ نہ {توتہ}، سہ چھہ پننس شرارتس منز آمت۔ توتہِ چُھ نہٕ سُہ زانان {یہِ} سُہ چُھ نہٕ زیادٕ انتہٲیی سٍتـ̡ زانان: {أمِس چُھ: یعنی، خدایہِ چُھ} {سُہ چُھ زانان: یعنی، ایوب چُھ زانان}\n16. تێمہِ کِنۍ چُھ ایوب بیکار پَنُن بوش کھولان۔ سُہ چُھ علمہٕ ورٲے لفظن ضرب کران۔","1.\\tایلیہو تہِ وون برونہہ کُن تہ وونُن،\n2.\\tمیہ رژھ تہ بہٕ ہاوٕ ژے زِ {میہ چُھ} وُنیُک تام خدایہ سندِ طرفہٕ کتھ کرُن۔ {میہ چُھ...: ہیب۔ خدایہ سندِ خاطرہ چھہِ وُنہِ تہِ لفظ}\n3. بہٕ کرٕ پنُن علم دوٗر پیٹھٕ حٲصِل تہٕ کَرٕ پننِس خالقس سٍتـ̡ نیکی منسوب کرنہٕ۔\n4.\\tپٔزۍ پٲٹھۍ میانہِ کلامٕہ {sól} گژھِ نہٕ غلط آسُن: یُس علمس مَنٛز کامل آسہِ {سُہ چُھ} توے سٍتـ̡ سٍتـ̡ ۔\n5.\\tوُچھو، خدایہ چُھہ طاقتور، تہٕ سُہ چُھہ نہٕ قوتس مَنٛز طاقتور تہٕ حکمتس سٍتـ̡ حقارت کران۔ {حکمت: ہیب۔ دِل}\n6. سُہ چُھ نہٕ بدکارن ہٕنز زندگی رژھراوان بلکہ چُھ غریبن حق دِوان۔ {غریب: یا، مُتٲثِر}\n7. سُہ چُھ نہٕ پَنٕنـ̡ پۯاونہٕ یِوان، بٔلکہِ چُھہ بادشاہن سٍتـ̡ تختس پیٹھ۔ آ، سُہ چُھ تِمن ہمیشہٕ خٲطرٕ قٲیم کران، تہٕ تِم چھِ بلند۔\n8.\\tتہٕ اگر {تِم} زنجیرن منز بندٕ آسن، {تہٕ} گژھن مصیبت ہٕنزِ رسن منز رٔٹِتھ۔\n9. پَتہٕ چُھ سُہ تِمن ہٕنزِ کٲم تہٕ تِمن ہٕنزِ زیادتی ہاونہٕ آمٕژ یِمن ہٕنز زیادٕ گٔمٕژ چھِ۔\n10. سُہ چُھ تِمن ہٕندِس کَن تہِ یلہٕ دِوان تہٕ حکم دِوان زِ تِم چھِ بدکاری نِش واپس یِنُک حُکُم دِوان۔\n11.\\tاگر تِم اطاعت کٔرِتھ تہٕ خدمت کٔرِن، تِم گُزٲرِن پنٕنۍ دۅہ خوشحالی تہٕ پنٕنۍ ؤری خوشی مَنٛز۔\n12. مگر اگر تِم اطاعت نہ کٔرِن، تِم گژھن تلوار سٍتـ̡ مارٕن، تہٕ تِم گژھن زانکٲری ورٲے مرن۔ {ختم: ہیب۔ گزرُن}\n13.\\tمگر دِلس منز چھِ منافق غصہٕ دِوان: تِم چھِنہٕ وُچھان ییلہ سُہ تِمن پابند کران چھُ۔\n14.\\tتِم چھِ جوانی مَنٛز مران تہٕ تِہٕنز زندگی چھے ناپاک سٍتـ̡ آسان۔ {تِم...: ہیب۔ تہند روح چُھ} {ناپاک: یا، سدومائٹس}\n15.\\tسُہ چُھ غریبن پننِس عذابس منز نجات دِوان، تہٕ ظلمس منز تہندِس کَن کھولان۔ {غریب: یا، مُتٲثِر}\n16.\\tیتھے پاٹھۍ آسہِ ہے سُہ ژیہ ژیہ کُنہِ وسیع جایہ منزہ نیبر کڈِتھ، ییتہِ نہٕ کانہہ سختی آسہِ۔ تہٕ یُس تہندس میزس پیٹھ تھاونہ یُن آسہِ سُہ گژھہِ چربی سٍتۍ بٔرِتھ آسُن۔ {یہ...: ہیب۔ باقی ٹیبل}\n17.\\tمگر ژے چُھہ بدکارن ہُند فیصلہ پورٕ کورمُت: فیصلہ تہٕ انصاف چُھہ ژے رٔٹِتھ {ژے}۔ {رٔٹِو...: یا، پَزِ تُہٕندِس تھپھ کَرُن}\n18.\\tکیازِ {اَتہِ} غصہٕ چُھ، {خبردار} گژھہِ نہٕ سُہ ژے نِش نِنہٕ یِنہٕ سٍتـ̡ تۅہہِ ہٕندِس دَرٕ سٍتـ̡ نِش نِنہٕ: تیلہٕ ہیکہِ نہٕ تُہہِ بٔڈ فدٕ دِتھ۔ {ڈیلیور...: ہیب۔ ژیہ پھیُر پھیُر}\n19. کیا سُہ چُھہ تُہٕندِس دولتس ہُند احترام کٔرِتھ؟ {نہ}، نہ سۄن، نہ طاقتٕچ تمام قوت۔\n20. رٲژ ہٕنز خواہش نہٕ کرٕن، ییٚلہِ لُکھ پننہِ جایہِ ژٹنہٕ ییہِ۔\n21.\\tبدکاری ہُند خیال تھاوُن نہٕ، یێلہِ چُھہ ژے مصیبت بجایہ ژٲرمُت۔\n22.\\tوچھو، خدا چُھ پننہِ طاقتہٕ سٍتـ̡ تٔمِس سٍتـ̡ کُس ہیچھناوان چُھ؟\n23.\\tأمِس کُس چُھ أمِس وَتھ ہُند حکم دِژمُت؟ یا کُس ہیکہِ ؤنِتھ، ژے چھُکھ بدکار کورمُت؟\n24.\\tیاد تھاوُن زِ تٔمۍ سٕنزِ کامہِ ہُند بٔڈۍ بناوُن، یُس انسان وُچھان چھُ۔\n25.\\tپریتھ انسان ہیکہِ یہ وچھتھ۔ انسان ہیکہِ دوٗر وُچھِتھ {یہ}۔\n26.\\tوچھو، خدا {چُھ} عظیم، تہٕ أسۍ چھِنہٕ پتاہ، تہٕ نہ ہیکو تٔمۍ سٕندِس ؤرین ہُند تعداد ژھانڈنہٕ یِتھ۔\n27. تکیازِ سُہ چُھ آبہٕ کِس قطرس لۄکٕٹۍ بناوان: تِم چھِ اَمہ کِس بخارٕ مُطٲبق روٗد وسان۔\n28.\\tیُس اوٚبرُن چھُ انسانس سٍتـ̡ وُچھان۔\n29.\\tتہِ ہیکہِ {کُنہِ} اوٚبرُک پھٔہلُن سمجِتھ، {یا} تٔمۍ سٕندِس خیمہ کِس شورس سٍتـ̡ سٍتـ̡ سمجِتھ؟\n30. وچھ سُہ چُھ اتھ پیٹھ پنُن گاش پھٔہلاوان، تہٕ سمندرٕچ بونہٕ کِس بونہٕ کِس حصس منز چھُ۔ {بونہٕ: ہیب۔ روٹس}\n31. تِکیازِ تِمو سٍتـ̡ چُھ سُہ عوامس سٍتـ̡ انصاف کران۔ سُہ چُھ واریاہ زیادٕ ماز دِوان۔\n32.\\tاوٚبرٕ سٍتـ̡ چُھ سُہ گاشس ؤلِتھ دِوان۔ تہٕ حکم دِوان زِ {اوٚبر} سٍتـ̡ یُس درمِیان یِوان چُھہ {اوٚبر} سٍتـ̡ چمکُن۔\n33.\\tاَمہ ہُند شور چھُ اَتھ مُتلِق ہاوان تہٕ چاروِ تہِ چھُ بخارس متعلق۔ {بخارات: ہیب۔ سُہ یُس ہیوٚر چُھ}","1.\\tاتھ پیٹھ تہِ چھہ میون دل تھر تھران تہ پننہِ جایہ نیبر نیران۔\n2.\\tتمۍ سنزِ آوازِ ہند شور بوزو تہ یہ آواز {یُس} ٲس منزہ نیران۔ {بوزو...: ہیب۔ بوزِو بوزُن}\n3. سُہ چُھ اتھ پورٕ آسمانس تل ہدایت کران، تہٕ پنٕنۍ بجلی زمینہٕ کس اندس تام۔ {بجلی: ہیب۔ گاش} {اختتام: ہیب۔ ونگس}\n4.\\tاَمہِ پَتہٕ چھُ اَکھ آواز گرٛٮ۪وان: سُہ چھُ عالی شان سٕنزِ آوازِ سٍتۍ گرٛٮ۪زان۔ تہٕ ییلہ تٔمۍ سٕنز آواز بوزنہٕ ییہِ سُہ روزِ نہٕ تِمن روزُن۔\n5. خدا چُھ پننہِ آوازِ سٍتـ̡ حیرت انگیز پٲٹھـ̡ گرٛٮ۪ز۔ بٔڈ کتھ چھیہ سہ کران، یُس نہ أسۍ سمجِتھ ہیکان۔\n6.\\tتکیازِ سُہ چُھ شینس ونان زِ ژے گژھ زمینس پیٹھ۔ یتھے پاٹھۍ چھہ لۅکٹۍ رود، تہ تمۍ سندِ طاقتہ کس زبردست رودس تام۔ {یتھے پٲٹھۍ...: ہیب۔ تہٕ روٗد کِس روٗدس تام، تہٕ تٔمۍ سٕندِ طاقتہٕ کِس روٗدس کُن}\n7. سُہ چُھ پرتھ انسان سُند اَتھٕ بند کران۔ تاکہ سٲری انسان گژھن تٔمۍ سٕنز کٲم زانن۔\n8.\\tامہ پتہ چھہ جانور گۅپھن منز گژھان تہ پننہِ جایہ روزان۔\n9.\\tجنوبہ منزہ چھہ واو نیران: تہ شمالہِ پیٹھہ سردی۔ {جنوب: ہیب۔ چیمبر} {شمال: ہیب۔ بکھرِتھ واو }\n10. خدایہ سٕندِ شہس سٍتـ̡ چُھہ ٹھنڈ دِنہٕ آمُت: تہٕ آبُک کھجر چُھہ دِنہٕ آمُت۔\n11.\\tتہِ چھہ سہ گٔنِس اوٚبرس تھپھ کٔرتھ: سہ چھہ پنن چمکدار اوبرہ پھہلٲوتھ: {تسُن...: ہیب۔ تٔمۍ سٕنٛدِ گاشک اوبر}\n12.\\tتہٕ یہِ چُھ تٔمۍ سٕندِ مشورٕ سٍتـ̡ پھیران زِ تِم ہیکن یُس تہِ أمِس دُنیاہس مَنٛز دُنِیاہُک حُکُم دِوان چھُ۔\n13. سُہ چُھ یہِ یِنُک سبب بناوان، چاہے اصلاح خٲطرٕ، یا پننہِ زمینہٕ خٲطرٕ، یا رحمتہٕ خٲطرٕ۔ {تصحیح: ہیب۔ اکھ راڈ}\n14. اے ایوب سٕندِس کُنہِ کامہِ سٍتـ̡ رٔٹِتھ روزُن، تہٕ خدایہ سٕنزِ حیرت انگیز کامہِ پیٹھ غور کرُن۔\n15.\\tژیہ چھا پتاہ زِ خداین کٔر تِمن ہُند گاش دِژمُت؟\n16.\\tژیہ چھا اوٚبرن ہُند توازن، تٔمۍ سٕنزِ حیرت انگیز کٲم یُس علمس منز کامل چھُ؟\n17.\\tتۅہہِ کِتھہ پاٹھۍ چھہِ گرم ییلہ سہ جنوبس سٍتۍ زمینہِ ژھۅپہ کٔرِتھ؟\n18.\\tژیہ کیا تس سٍتـ̡ آسمانس پھٔہلٲوِتھ، {یُس} مضبوط، {تہٕ} پگلہٕ شیشہ ہٕندۍ پٲٹھۍ؟\n19.\\tاسہِ ہیچھناوُن زِ أسۍ کیا وَنُن أمِس سٍتـ̡ {کیازِ} أسۍ ہیکو نہٕ انہِ گٹہِ ہٕندِ وجہ سٍتۍ {پننہِ کلام} حکم دِتھ۔\n20.\\tتس گژھہِ ونُن زِ بہٕ کتھ کرُن؟ اگر کانہہ انسان کتھ کرِ، یقینا گژھہِ سُہ نِنہٕ یُن۔\n21.\\tتہٕ وُنہِ چُھہ {انسان} سُہ روشن گاش وُچھان یُس اوٚبرن مَنٛز {چُھ} چُھہ، مگر واو چُھ وُچھان تہٕ تِمن پاک کٔرِتھ۔\n22. شُمالہٕ کِس سٍتـ̡ چُھ سُہ سٍتـ̡ خوفناک عظمت۔ {منصفانہ...: ہیب۔ سۄنہٕ}\n23.\\tخداتعالیٰ سٍتـ̡ چھُ نہٕ أسـ̡ سُہ لٔبِتھ: {سُہ چُھ} طاقتس مَنٛز، تہٕ فٲصلس مَنٛز تہٕ انصافس مَنٛز بہترین: سُہ کرِ نہٕ مصیبت۔\n24. تَمہِ کِنۍ چھُ انسان أمِس کھوژان: سُہ چُھنہٕ کٲنٛسہِ تہِ دِل دِل دِلُک احترام کران۔","1. تێلہِ دِژ خداوند ایوب سُند جواب تہٕ وونُن،\n2.\\tیہ کُس چھہ یُس علمہ ورٲے لفظو سیتۍ مشورس سیاہ کران چھہِ؟\n3.\\tپَنٕنۍ کمر رٔٹِتھ کٔرِو أکِس مردٕکۍ پٲٹھۍ۔ تکیازِ بہٕ کرٕ ژے منگ، تہٕ ژے کٔرٕ میہ جواب۔ {جواب...: ہیب۔ مے کٔرِو زان}\n4.\\tییلہ میہ زمینچ بنیاد ترٲومژ ٲس تہ ژیہ کتہِ ٲس؟ اعلان کرُن، اگر ژیہ سمجھ آسہِ۔ {ہسٹ...: ہیب۔ زانن واجنہِ تفہیم}\n5.\\tاگر ژیہ پتاہ چھیہ، امکۍ پیمانہ کٔمۍ چھہِ تھوومُت؟ یا اتھ پیٹھ کٔمۍ چُھ لٲنہٕ پھٔہلٲومٕژ؟\n6. امچ بنیاد کتھ پیٹھ چِھ مضبوط کرنہٕ آمٕژ؟ یا ییٚمۍ کٔر امِچ کوُنٕچ کٔنۍ ترٛٲومٕژ؛ {بنیاد: ہیب۔ ساکٹس} {فاسٹن: ہیب۔ ڈوبنہٕ خٲطرٕ بناونہٕ آمُت؟}\n7. ییلہ صبحک ستارہ اکوٹہ گیو، تہٕ خدایہ سٕندِ سارِنٕے نیچو کٔر خوشی خٲطرٕ کرٛٮ۪کھ؟\n8.\\tیا {کُس} چھہ سمندرس دروازو سیتۍ بند کٔرتھ، ییلہ سہ پھٹان چھہِ، {یتھہ پاٹھۍ} چھہ سہ رحمہ منزہ نیبر نیران۔\n9.\\tییلہ میہ اوٚبرُک پلو تہٕ گٔنۍ گٔنۍ گٔیہِ اَمہ خٲطرٕ لٔٹِتھ بٔنِتھ،\n10.\\tتہٕ اَمہ خٲطرٕ کٔرِن میون حکم {جاے}، تہٕ کٔرِن بند تہٕ دروازٕ، {بریک...: یا، اتھ پیٹھ میون فرمان قٲیم}\n11.\\tتہٕ وونُن، وُنہِ تہِ گژھہِ ژیہ یِنہٕ، مگر امہِ پتہٕ گژھہِ نہٕ: تہٕ یتہِ گژھہِ چانۍ فخر لہرٕ رُکاونہٕ؟ {thy...: Heb. چانہِ لہرن ہند فخر}\n12. کیا ژے چُھہ پننیو دۅہہٕ پیٹھٕ صبحُک حکم دِژمُت۔ {تہٕ} دۅہ سپرنگس پننہ جاے زانان۔\n13.\\tیُتھ زِ یہِ گژھہِ زمینہِ ہندِس اندس پیٹھ رٔٹِتھ، یُتھ بدکار ییہ اَمہ منزٕ ژٔلِتھ ژٔلِتھ؟ {اختتام: ہیب۔ ونگس}\n14.\\tیہ چھہ میژِ ہندۍ پاٹھۍ پھیرنہ یوان۔ تہٕ تِم چھِ پلو پٲٹھۍ کھڑا آسان۔\n15. تہٕ بدکارن نِش چُھ تِہُند گاش رُکاونہٕ آمُت، تہٕ تھدِ نٔر گژھہِ پھُٹاونہٕ۔\n16.\\tژے چھکھ سمندرٕ کِس چشمس منز ژٔلِتھ؟ یا ژیہ چھکھ گہرایی ژھانڈنس منز پکان ؟\n17. کیا ژےٚ خٲطرٕ چھَا موتٕکۍ دروازٕ کھولنہٕ آمٕتۍ؟ کِنہ ژے وچھکھ موتُک ژھایہِ دروازہٕ؟\n18.\\tژیہ چھا زمینہِ ہُند وسعتہٕ وچھمُت؟ اعلان کرو اگر ژیہ یہ سورے پتاہ چھیہ۔\n19.\\tگاش کتہِ چھہ {کتہِ} وتھ روزان؟ تہٕ {یِتھٕ کٔن} انہِ گٹہِ، کتہِ {چُھ} امچ جاے،\n20.\\tتہ ژیہ یہ اتھ بندس تام نِن، تہٕ یہ زِ ژیہ گژھہِ امہِ کِس مکانس تام وتہِ زانان؟ {باؤنڈس تام: یا، ایٹ، وغیرہ}\n21.\\tژیہ چھا پتاہ، کیازِ تۅہہ اوس تمہِ وقتہ زامُت؟ یا {کیازِ} چُھہ تُہند دۅہن ہُند تعداد {چُھ} بٔڈ؟\n22.\\tژیہ ژیہ ژیہ شینہٕ کِس خزانس منز ژاو ؟ یا ژے وُچھمُت ژیلہٕ ہُند خزانہٕ،\n23. یُس مے مصیبت ہٕندِس وقتس منز، جنگ تہٕ جنگہٕ کِس دۅہس خلاف محفوظ تھوومُت چھُ؟\n24.\\tگاش کمہِ وتہِ چھہ ژٹنہ یوان، {یُس} مشرقی ہوا زمینس پیٹھ پھہلاوان چھہِ؟\n25. یٔمۍ چُھ آبہٕ وَسنہٕ خٲطرٕ آبہٕ وَتھ تقسیم کٔرمٕژ، یا بجلی ہٕنزِ وَتھ چھِ۔\n26.\\tزمینس پیٹھ روٗد تراوُن، {یتہِ} کانہہ انسان {چُھ} بیابانس منز، یتھ منز {اَن} کانہہ انسان چُھنہٕ۔\n27. ویران تہٕ فضلہٕ {زمین} مطمئن کرنہٕ خٲطرٕ؛ تہٕ نرم جڑی بوٹی ہٕنٛز کلی نیرنہٕ خٲطرٕ؟\n28. کیا روٗد چھا مول؟ یا شبنم قطرہ کٔمۍ پیدہ کٔرۍ؟\n29. کٔمۍ سٕندِ کوکھ منزٕ آو شین؟ تہٕ جنتُک ہوُر ٹھنڈ، کٔمۍ چُھ یہٕ جنس کورمُت؟\n30.\\tآب چھہ کنہِ ہندۍ پاٹھۍ ژوٚپمت تہ سوٚنُک بُتھ چھہ لٔگِتھ۔ {is...: Heb. نِنہٕ آمُت}\n31.\\tژیہ ہیککھا پلیاڈس ہٕندِس میٹھۍ اثرس بند کٔرِتھ، یا اورین ہٕندِس بینڈس یلہٕ ترٲوِتھ؟ {Pleiades: یا، ستھ ستارہ: Heb. Cimah} {اورین: ہیب۔ سیسل؟}\n32. کیا ژٕ ہیککھا مزاروت پننِس موسمس منز پٲدٕ کٔرِتھ؟ یا کیا ژٕ ہیککھا آرکٹورسس پننین نیچوین سۭتۍ رہنمٲیی کٔرتھ؟ {مزاروتھ: یا، باہ نشانہٕ} {گائیڈ: ہیب۔ تِمن رہنُمٲیی کٔرِو}\n33.\\tکیا ژیہ چھکھ جنتٕکۍ احکام زانان؟ کیا ژٕ ہیککھا زمینس منٛز امچ سلطنت قٲیم کٔرتھ؟\n34. کیا ژٕ ہیککھا پنٕنۍ آواز اوٚبرَس تام تُلِتھ، یُتھ آبٕچ کثرت ژےٚ ؤلِتھ؟\n35.\\tکیا ژے ہیککھا بجلی سوزِتھ، یُتھ تِم گژھِتھ، تہٕ ژے ؤنِتھ، یِتھے أسۍ چھِ؟ {یتہِ...: ہیب۔ اسہِ وچھو؟}\n36.\\tباطنی حصس منز کٔمۍ چھہ حکمت تراومژ؟ یا کٔمۍ چھُ دِلس سمجھ دِژمُت؟\n37.\\tدانشس منز کُس ہیکہِ اوٚبرن گنزرٲوِتھ؟ یا کُس ہیکہِ جنتٕچ بوتلہٕ روزِتھ، {روزُن: ہیب۔ وجہ}\n38.\\tییلہ گردِ سختی گژھہِ، تہٕ کۅکرِ یکوٹہ رٔٹِتھ ژٔٹِتھ چھِ؟ {بڑان...: یا، چُھ مٔرِس منز تبدیل: ہیب۔ چُھ تراونہٕ آمُت}\n39. کیا ژٕ کٔرِکھ شیرٕ سٕندِ خٲطرٕ شِکار؟ یا جوان شیرن ہنز بھوک پورٕ، {بھوک: ہیب۔ دی لائف}\n40.\\tییلہ تِم {تِہندِ} گۅپھن منز روزان چھِ، {تہٕ} چھِ پردٕ روزان تہٕ انتظار کٔرِتھ؟\n41.\\tکُس چُھ کۅکرِ سُند کھٮ۪ن دِوان؟ ییلہ تٔمۍ سٕندۍ شُرۍ خدایس نِش فریاد کران چھِ، تِم چھِ مازٕچ کمی کِنۍ پھیران ۔","1.\\tژیہ چھا پتاہ زِ کنہِ کُنہِ کُنہِ جنگلی ژھاوٕل نیران چھِ؟ {یا} کیا ژیہ نشان زد کٔرِتھ ییلہ ہینڈ کٔرِتھ چھِ؟\n2. کیا تُہۍ ہیکوا تِم ریتھ گنزرٲوِتھ یِم تِم پوٗرٕ کران چھِ؟ یا ژیہ چھا پتاہ زِ تم کُس وقت ییلہ تم نیران چھہِ؟\n3. تِم چھِ پَنُن پان نَمان، تِم چھِ پَنٕنہِ بچہٕ نیران، تِم چھِ پنٕنۍ غم کڈان۔\n4.\\tتِہٕندِس بچہٕ چِھس خۅش گَژھان، تِم چھِ مَکٲے سٍتۍ بَڑان۔ تِم چھِ نیران، تہٕ تِمن نِش چھِنہٕ واپس۔\n5. کٔمۍ چھُ جنگلی گَرٕ آزاد کٔرِمُت؟ یا جنگلی گَرٕ ہٕندۍ بند کٔمۍ چھِ یلہٕ ترٛٲومٕتۍ؟\n6.\\tیمۍ سُند مکانہ میہ بیابان تہٕ بنجر زمینہٕ بنوومت چھُ۔ {بیرن...: ہیب۔ نوٗنہٕ جایَن}\n7. سُہ چُھ شہرٕچ بٔڑِس بٔڈِس حقارت کران، نَہ چُھ سُہ ڈرایورٕ سٕندِس فریادس سٍتـ̡ نظرِ تھاوان۔ {ڈرایور: ہیب۔ ایکسیکٹر سُند}\n8.\\tپہاڑن ہُند سلسلہ چُھ تٔمۍ سُند مرگہٕ تہٕ سُہ چُھ پرٮ۪تھ سبز چیزس ژھانڈان۔\n9. کیا یونیکورن آسہٕ تۅہہِ ہٕنٛز خدمت کرنہٕ خٲطرٕ تیار، یا تُہٕنٛدِس کۅنگہٕ سٍتـ̡ روزِتھ؟\n10.\\tژیہ ہیککھا یونیکورنس پننس بینڈس سیتۍ گٔنڈتھ کٔرتھ؟ نتہٕ سُہ کرِ ژےٚ پتہٕ وادین ہُند شکار؟\n11.\\tکیا ژیہ کٔرِو تس پیٹھ بھروسہ، کیازِ تٔمۍ سُند طاقت {چُھ} بٔڈ؟ یا کیا ژٕ چھکھ پنٕنۍ محنت أمس پیٹھ تراوان؟\n12. کیا ژٕ کٔرِو أمِس پژھ کٔرِتھ، زِ سُہ اَنِہ تُہٕندِس بُلِس منز؟\n13.\\tمورن ہٕندِس پکھس کٔرِتھ؟ یا شترمرغس پکھہٕ تہٕ پکھہٕ؟ {پکھہ تہٕ ...: یا، سٹارک تہٕ شترمرغن ہٕندۍ پکھہٕ}\n14.\\tیُس پنہٕ نِس ٹھوٗل زمینس مَنٛز تراوان چھُ، تہٕ تِمن گردِ مَنٛز گرم کٔرِتھ،\n15.\\tتہِ چھہ یہ فراموش کران زِ کھۅر گژھہِ تمن پھُٹراوُن، نتہ جنگلی جانور کرِ تمن پھُٹراوُن۔\n16.\\tسۅ چھیہ پننین جوانن سٍتـ̡ سختی کٔرمٕژ، گویا {تِم ٲسۍ نہٕ تٔمِس̡ سٕندِس سٍتـ̡ سٍتـ̡ بێکار۔\n17.\\tکیازِ خداین چُھ أمِس حکمتہٕ نِش محروم کورمُت، تێلہِ چُھہ نہٕ أمِس فہم دِژمُت۔\n18.\\tییلہ سۅ پانس تھزرس پیٹھ تھوٚد کٔرِتھ، سۅ چھیہ گُرِ تہٕ تٔمۍ سٕندِس سوارِ سٍتۍ حقارت کران۔\n19.\\tژیہ دِژ گُرِ طاقت؟ ژیہ چھکھ تٔمۍ سٕنزِ گردن گجگرٕ سٍتۍ پلو دِژمُت؟\n20. کیا ژٕ ہیککھا أمِس ٹڈِکۍ پٲٹھۍ خوفزدہ کٔرِتھ؟ تٔمۍ سٕنزِ نستہِ ہُند شان چھُ خوفناک۔ {خوفناک: ہیب۔ دہشت گردی}\n21.\\tسُہ چُھ وادی مَنٛز پکان تہٕ پَنٕنِس طاقتس مَنٛز خوش گَژھان: سُہ چُھ مسلح نفرن سٍتـ̡ مِلنہٕ خٲطرٕ نیران۔ {سُہ چُھس پَکہٕ دِوان: یا، تٔمۍ سٕندِ کھۅر کھَننہٕ} {ہتھیار بند...: ہیب۔ دی آرمر}\n22. سُہ چُھ خوفس ٹھٹھہٕ کران، تہٕ چُھ نہٕ خوفزدہ گژھان۔ نہ چُھ سُہ تلوار نِش پتھ کُن۔\n23.\\tلۅتہٕ چُھس أمِس کُن گڑبڑ کٔرِتھ، چمکدار نیزٕ تہٕ ڈھال۔\n24.\\tسُہ چُھ زٔمیٖنہٕ سٍتـ̡ تہٕ غصہٕ سٍتـ̡ گِلہٕ کٔرِتھ، نۂ تہٕ چُھہ أمِس پژھہٕ زِ یہِ چُھہ بُرٕچ آواز۔\n25.\\tسُہ چُھ بُرٕس مَنٛز وَنُن، ہا، ہا۔ تہٕ سُہ چُھ دور تام جنگہٕ، کپتانن ہٕنز گرج تہٕ کرٛٮ۪کہٕ ہٕنز خوشبو۔\n26.\\tکیا باز چھُ پننہِ عقلہٕ سٍتۍ وُڑان، {تہٕ} پنٕنۍ پَکھہٕ جنوبس کُن پھٔہلٲوِتھ؟\n27.\\tکیا عقاب چُھہ تۅہہِ ہٕندِس حُکمس سٍتـ̡ کھسنہٕ یوان، تہٕ بَناوُن پنُن گُرٕ تھزرس پیٹھ؟ {at...: Heb. تۅہہِ ہٕندِس ٲسس سٍتۍ}\n28.\\tسُہ چُھ کنہِ پتھرس پیٹھ، کنہِ کُنہِ کُنہِ تہٕ مضبوٗط جایہِ پیٹھ روزان تہٕ روزان۔\n29.\\tاتہِ پیٹھہ چھہ سۅ شکارس ژھانڈان، {تہِ} چھیہ امۍ سنزن اچھن دور وچھان۔\n30.\\tتٔمۍ سٕندِ شُرۍ تہِ چھِ خون چوسان: تہٕ یَتہِ مقتول {چھِ}، تتہِ چھِ سۅ {چھِ}۔","1. امہِ علاوٕ دیُت خداوند ایوب سُند جواب تہٕ وونُن،\n2. یُس اللہ تعالیٰ سٍتـ̡ بحث کرُن چُھہ سُہ کرُن؟ یُس خدایہ ملامت کرِ، سُہ گژھہِ امیک جواب دِنہٕ۔\n3. اَمہِ پَتہٕ دِیُت ایوب رب سُند جواب تہٕ وونُن،\n4.\\tوُچھ، بہٕ چُھس بدکار ۔ بہٕ کیا دِیہٕ ژےٚ جواب؟ بہٕ تھوو پننس ٲسس پیٹھ اتھہ۔\n5. اکہ لٹہِ کتھ کٔرمٕژ۔ مگر بہٕ دِیہ نہ جواب: آ، دۅیہ لٹہِ۔ مگر بہٕ کٔرٕ نہٕ برونٹھ کُن۔\n6. پتہٕ دیُت خداوند ایوب سُند جواب تہٕ وونُن،\n7.\\tپَنٕنۍ کمر رٔٹِتھ تہٕ بہٕ کٔرٕ ژے نِش منگان تہٕ ژٕ کٔرٕ میہ سٍتـ̡ اعلان۔\n8.\\tکیا ژیہ تہِ کٔرِکھ میون فیصلہ منسوخ کٔرتھ؟ کیا ژٕ کٔرِکھ مےٚ مذمت، یُتھ ژٕ نیک بٔنِتھ؟\n9. کیا تۅہہ چھوا خدایہ ہیو نٔرۍ؟ کِنہ ژیہ ہیککھا امس ہش آوازِ سٍتۍ گجگڑاو؟\n10.\\tپان سجاوُن وۅنۍ {سٍت} عظمت تہٕ عظمت۔ تہٕ پنُن پان کٔرِو شان تہٕ خوبصورتی سٍتـ̡ سٍتـ̡ سٍتـ\n11.\\tپننہِ قہر ہُند غصہٕ کٔرِو نیبرِم، تہٕ وُچھِو پرٮ۪تھ کانہہ مغرور تہٕ أمِس ذلیل کٔرِتھ۔\n12.\\tپریتھ کٲنسہِ وُچھِو {یعنی} فخر، {تہٕ} کٔرِو أمِس بٔنِتھ۔ تہٕ بدکارن ہٕنزِ جایہِ لٔگِتھ۔\n13.\\tیِم تھٲوِو یکوٹہ گردِ منز ژوٗر۔ {تہٕ} چھِ تِمن ہٕندِس بُتھِس ژوٗرِ پٲٹھۍ۔\n14. تیلہِ کٔرٕ بہٕ ژے تہِ اقرار زِ تُہند پنُن دچھُن اتھٕ ہیکہِ ژےٚ بچٲوِتھ۔\n15.\\tوُچھو وُنہِ بہیموت، یُس میہ ژے سٍتۍ بنوو۔ سُہ چُھ گاسہٕ کھٮ۪وان۔ {بہیموتھ: شاید کُنہِ قٕسمُک اکھ معدوم جانور}\n16.\\tوۅنۍ چھُ تسُند طاقت {چھُ} تٔمۍ سٕندِس کمرس منز، تہٕ تٔمۍ سُند طاقت {چُھ} تٔمۍ سٕندِس اڈِ ہٕندِس نافس منز۔\n17.\\tسُہ چُھ پنٕنۍ لٔٹ دیودارٕکۍ پٲٹھۍنژان: تٔمۍ سٕندٮ۪ن کنن ہٕندِ لٔٹِتھ چھِ۔ {یہ...: یا، سہ بِہتھ تھوٚد}\n18. تٔمۍ سٕنزِ أڈجہِ ہٕندِس مضبوٗط پیتلٕکۍ ٹُکر۔ تمۍ سنزِ اڈجہِ چھیہ ششتٕرٕچ سلاخن ہٕندۍ پٲٹھۍ۔\n19. سُہ چُھ خدایہ سٕندِ وتہِ ہُند سردار: یُس أمِس بنوومُت چُھ، سُہ ہیکہِ پَنٕنـ̡ تلوار تٔمِس نِش واتناوِتھ۔\n20. یقینا پہاڑ چھِ أمِس کھٮ۪ن دِوان، ییتہِ مٲدانٕکۍ سٲری جانور گِنٛدان چھِ۔\n21.\\tسُہ چُھ ژھایہِ دار کُلٮ۪ن تلہ کُلِس منز، نِلہٕ تہٕ کُلِس منز۔\n22.\\tژھایہِ دار کُلۍ چھہِ تس ژھایہ دِوان۔ بروک ہٕکۍ وِلو چھِ أمِس اندۍ پکھۍ گٔژھان۔\n23.\\tوچھو سُہ چُھہ اکھ دریاو چیوان، {تہٕ} چُھہ نہٕ جلدی کٔرِتھ: سُہ چُھ یقین کران زِ سُہ ہیکہِ اردن پننِس ٲسس منز کھٔلِتھ۔ {سُہ چُھ چِھ: ہیب۔ سُہ چُھ ظُلم کران}\n24.\\tسُہ چُھ یہِ أچھو سٍتـ̡ نَس نِش ژٔٹِتھ ژٔلان۔ {سُہ...: یا کانہہ ما نِیہ أمس نظرِ منز، نتہٕ کٔرِن أمس نَس گِن؟}","1. کیا ژٕ ہیکوا ہُک سٍتۍ لیویتھن کٔڈِتھ؟ یا تٔمۍ سٕنزِ زبان رَزِ سٍتۍ {یُس} ژے تراوُن؟ {لیویتھن: شاید کُنہِ قٕسمُک اکھ معدوم جانور} {کُس...: ہیب۔ ژیہ کُس چُھہ ژیہ ژٔٹۍ؟}\n2.\\tژیہ ہیککھا تمۍ سنزِ نس منز ہُک تھپھ کٔرتھ؟ نتہ کٔرِتھ کٔرِتھ کٔرِتھ کٔرِتھ؟\n3. کیا سُہ کرِ تۅہہِ واریاہ دُعا؟ کیا سُہ کرٕ ژےٚ نرم {لفظ}؟\n4. کیا سُہ کرٕ تۅہہِ سٍتـ̡ معاہدٕ؟ کیا ژٕ چھکھ سُہ ہمیشہٕ خٲطرٕ نوکر مانان؟\n5.\\tکیا ژیہ چھکھ أمس سٍتۍ {جاناوارس} سٍتۍ گِندُن؟ یا کیا ژٕ کٔرِکھ أمِس پنٕنٮ۪ن کورٮ۪ن ہٕندِ خٲطرٕ بند؟\n6.\\tصحابہ کیا تٔمِس سٍتـ̡ ضیافت کٔرِتھ؟ کیا تِم کٔرِن أمِس سوداگرن منٛز تقسیٖم؟\n7. کیا ژٕ ہیککھا تٔمۍ سٕندِس مسلس خاردار ششتر سٍتۍ بٔرِتھ؟ یا تٔمۍ سُند کلہٕ گاڈٕ نیزٕ سۭتۍ؟\n8. أمِس پیٹھ تھاو پنُن اتھہٕ، جنگ یاد تھاوُن، مزید کرُن نہٕ۔\n9.\\tوچھو، أمِس سٕنز وۅمید چھے بیکار: أمِس وُچھِتھ تہِ گژھہِ نہٕ کانہہ تہِ دِنہٕ؟\n10.\\tکانہہ تہِ چھہ نہ تیوت خوفناک زِ تس ہنگامہ کرُن: تیلہ کُس ہیکہِ میانہِ برونہہ کنہِ کھڑا گژھتھ۔\n11. کُس چُھ مے رُکٲومُت، یُس بہٕ چُھس ادا کرُن؟ یُس تہٕ چُھس پورٕ آسمانس تل چُھ، سُہ چُھ میٲنۍ ۔\n12.\\tبہٕ کٔرٕ نہ تٔمۍ سٕندِس حصس تہٕ نہ تٔمۍ سٕندِس طاقتس تہٕ نہ تٔمۍ سُند خوبصورت تناسب۔\n13. کُس ہیکہِ تٔمۍ سٕندِس پلوُک بُتھ دریافت کٔرِتھ؟ {یا} کُس ہیکہِ پنن دوٚگن لگام ہیتھ {أمس} یِتھ؟ {سۭتۍ: یا، اندر}\n14.\\tکُس ہیکہِ تمۍ سندِ بُتھِ ہندۍ دروازہ کھولِتھ؟ تمۍ سندِ دند چھہِ خوفناک اندۍ پکھۍ۔\n15.\\t{تٔمِس} پیمانہٕ {چھُ} تٔمۍ سُند فخر، بند کرُن {یِتھٕ پٲٹھۍ} اکھ نزدیکی مُہر۔ {پیمانہٕ: ہیب۔ ڈھالٕکۍ مضبوٗط ٹُکرٕ}\n16.\\tاکھ چھہ بییِس تیوت نزدیک، زِ یمن درمیان ہیکہِ نہ کانہہ ہوا یِتھ۔\n17.\\tتِم چھِ اَکھ أکِس سٍتـ̡ رٔلِتھ، تِم چھِ یِمن ہٕندِس سٍتـ̡ ژٔٹِتھ ہیکو نہٕ۔\n18.\\tتسٕنزِ نیسِنگہٕ سٍتۍ چھُ گاش چمکان، تہٕ تٔمۍ سٕنزِ أچھ چھِ صُبحٕچ ٹٲرۍ ہٕندۍ پٲٹھۍ۔\n19.\\tأمِس ٲسِس منزٕ دزان شمعہٕ نیران، {تہٕ} چھُ نارٕچ چنگاری نیران۔\n20.\\tتسٕنزِ نستہِ منزٕ چھُ دوٚکھ نیران، یُس کُنہِ وُپھ یا کۅکرِ ہُند {نیبر} چھُ۔\n21.\\tتٔمۍ سٕندِس شاہس چُھ ژلہٕ دِوان، تہٕ تٔمۍ سٕندِس ٲسس منزٕ چُھ نار نیران۔\n22.\\tتٔمۍ سٕندِس گردنس منز چُھ طاقت روزان، تہٕ غم چُھ أمِس برونہہ کُن خوشی مَنٛز بدلان۔ {چُھ خوشی منز تبدیل گومُت: ہیب۔ خوشی}\n23.\\tتٔمۍ سٕندِس مازٕکۍ ٹُکرٕ چھِ پانہٕ وٲنِتھ رٔلِتھ: تِم چھِ پانَس مَنٛز مضبوٗط۔ تم ہیکن نہٕ منتقل کٔرتھ۔ {فلیکس: ہیب۔ فالنگس}\n24. تٔمۍ سُند دِل چُھ کنہِ ہیوٗ مضبوٗط۔ آ، تیوتاہ سختی یوتاہ نیتھر {مِل سٹون} ہیو مشکل۔\n25.\\tییلہ سُہ پانس تھوٚد کران چُھ، طاقتور چھِ کھوژان: پھُٹنہٕ کِنۍ چھِ تِم پان پاک کران۔\n26.\\tیُس تلوار أمِس کُن لٔگِتھ آسہِ، سُہ ہیکہِ نہٕ تھپھ کٔرِتھ: نیزٕ، ڈارٹ، تہٕ نہ ہیبرجین۔ {ہیبرجین: یا، بریسٹ پلیٹ}\n27. سُہ چُھ ششتٕرُک گاسہٕ مانان، {تہٕ} پیتلُک پٲٹھۍ۔\n28.\\tتیر ہیکہِ نہ تس ژلِتھ ژلِتھ: سُہ چھُ أمِس سٍتۍ کُنہِ\n29.\\tڈارٹ چھہ کُنہِ\n30.\\tتیزدار کٔنِس تلہ کنہِ: سُہ چُھ دلدَس پیٹھ تیزۍ نوکدار چیز پھٔہلاوان۔ {تیز پتھر: ہیب۔ برتن ہٕندۍ تیز ٹُکر}\n31.\\tسُہ چُھہ سمندرس بانہٕ ہٕندۍ پٲٹھۍ، سُہ چُھ سمندرس مرہم ہٕندۍ پٲٹھۍ۔\n32. سُہ چُھ أمِس پَتہٕ چمکاونہٕ خٲطرٕ وَتھ بناوان۔ {اَکہ} چھُ سونچان سرٛوٚن {to be} hoary\n33.\\tزمینس پیٹھ چھہ نہ تس ہیو یُس بے خوف بناونہ آمت چھہ۔ {خوف ورٲے چھہ بناونہ آمت: یا، پنن پان کرو بے خوف}\n34. سُہ چُھ سارِنٕے تھدِ {چیز} وُچھان: سُہ چُھ سارِنٕے مغرور بچن ہُند بادشاہ۔","1. اَمہِ پَتہٕ دِیُت ایوب خداوند سُند جواب تہٕ وونُن،\n2.\\tمیہ چھیہ پتاہ زِ ژیہ ہیکہِ پریتھ کانہہ {چیز} کٔرِتھ، تہٕ {یہ} ہیکہِ نہٕ ژے نِش کانہہ تہِ خیال رٔٹِتھ۔ {کانہہ تہِ خیال ہیکہِ نہٕ ٲسِتھ...: یا، تُہند خیال ہیکہِ نہٕ رُکاوٹ کٔرِتھ}\n3. سُہ کُس چُھ یُس علمہٕ ورٲے مشورٕ ژوٗرِ تھاوان چُھ؟ تَمہِ کِنۍ چُھس مے وَنُن زِ بہٕ چُھس نہٕ سمجھان۔ میانہِ خاطرہ سیٹھا حیرت انگیز، یُس نہ میہ پتاہ اوس۔\n4.\\tبوزو، بہٕ کٔرِس ژے منگہٕ، تہٕ بہٕ کَرٕ ژے سٍتـ̡ کَرٕنـ̡ تہٕ کَرٕ ژے سٍتـ̡ کَرٕنـ̡ ۔\n5.\\tمیہ بوز ژے بوزمُت تہ وۅنۍ چھیہ میانہِ اچھ ژیہ وچھان۔\n6. اَمہِ مۄکھٕ چُھس بہٕ نفرت کَران، تہٕ گردِ تہٕ رٔٹِتھ توبہ کَران۔\n7. تہٕ یہِ اوس {یِتھ} زِ خداوند سٕندِ یِم لفظ ایوب سٕندِ سٍتـ̡ وَننہٕ پتہٕ، خداوند ووٚن الیفاز تیمانِس سٍتـ̡ میٲنۍ قہر تہٕ تێہٕندِس دۄن یارن سٍتـ̡ دِنہٕ آمُت، تێکیازِ ژے چُھہ نہٕ میانہِ مُتلق کتھ کٔرمٕژ، یُس میانہِ خادم ایوب سٕندِ پٲٹھـ̡ چُھہ صحیح۔\n8. تێمہِ کِنۍ نِو پانس نِش سَتھ بیل تہٕ ستھ مینڈٕ، تہٕ گژھ میٲنِس خادم ایوب نِش تہٕ پانس خٲطرٕ اکھ زالنہٕ نذرانہ پیش کرُن۔ تہٕ میون خادم ایوب کرِ تۅہہِ خٲطرٕ دُعا: تٔمِس خٲطرٕ کٔرٕ بہٕ قبول: نتہٕ بہٕ تہٕ ژے سٍتـ̡ {ام: ہیب۔ تٔمۍ سُند بُتھ، یا، شخص}\n9.\\tتہ الیفاز تیمانی تہٕ بلداد شُہیت {تہٕ} زوفر نعمتی گٔیہ، تہٕ کٔرٕکھ خداوند سُند حُکُم تہٕ کٔرٕن ایوب تہِ قبول۔ {جاب: ہیب۔ ایوب سُند بُتھ}\n10.\\tتہٕ خداوند کٔر ایوب سٕندِ قٲد ییلہ تٔمۍ پننین دوستن ہٕندِ خٲطرٕ دُعا کٔر، تہٕ خداوند دِژ ایوب سٕندِ دُبارٕ دۄگنہٕ۔ {دِیُت...: ہیب۔ سُہ سورُے یُس ایوب اوس دگنہٕ سٍتـ̡ شٲمل کرنہٕ}\n11.\\tاَمہِ پَتہٕ آیہِ أمِس نِش تٔمۍ سٕندِ سارِنٕے بٲے تہٕ سارِنٕے بیٚنہِ تہٕ تِم یِم أمِس گَرٕ سٍتـ̡ وٲتِتھ تہٕ تٔمِس سٍتـ̡ کھیوٚکھ أمِس سٍتـ̡ بٔرِس سٍتـ̡ تہٕ یِمو دِژ أمِس سٍتـ̡ سارِنٕے بُرٲیی ہٕندِس سٍتـ̡ تسلی دِنہٕ۔  تہٕ پرٮ۪تھ أکِس سۄنہٕ سٕندِ بالہٕ۔\n12. یێمہِ کِنۍ دِژ خداوند ایوب سٕندِس ٲخری اندس پنہٕ نِس آغازس سٍتـ̡ زیادٕ برکت دِژمٕژ، تکیازِ أمِس ٲس ژۅداہ ساس کۅکر، تہٕ شیہ ساس وونٹ، تہٕ اکھ ساس بیل تہٕ اکھ ساس گٔرۍ۔\n13. أمِس ٲس سَتھ نیٚچِوِ تہٕ ترےٚ کورِ تہِ۔\n14.\\tتہٕ تٔمۍ ووٚن گۅڈنِچ جمائمہ سُند ناو۔ تہٕ دیمہٕ سُند ناو، کیزیا؛ تہٕ تریمس سُند ناو، کیرن ہاپچ۔\n15. تہٕ سارِنٕے زمینس مَنٛز ٲس نہٕ کانٛہہ تہِ زنانہٕ ایوب سٕنزِ کورِ ہٕندۍ پٲٹھۍ، تہٕ تِہندِ مٲلہِ دِژ تِمن پننین باین مَنٛز وراثت۔\n16.\\tامہ پتہ گۆو ایوب ہتھ ژتٲجی ؤری زندٕ، تہٕ وُچھن پننین نیچوین تہٕ نیچوین ہٕندِ نیچوۍ، ژۅن نسلن تام وُچھمُت۔\n17. یێلہِ گۆو ایوب بُزرگ تہٕ دۅہن سٍتـ̡ بٔرِتھ مٔرِتھ۔"];
